Ceviri.ekle("hy","olay",{
"OLAYLAR_EK10:1484-08-04:0":{"b": ["Աքքերմանի նվաճումը. Դնեստրի գետաբերանը և Մոլդովայի սևծովյան դարպասի փակումը", "7cb20feb"], "d": ["Կիլիայի հանձնումից քսան օր անց բանակը հասավ Դնեստրի գետաբերանի Աքքերմանի առջև, և բերդը գրավվեց օգոստոսի 4-ին։ Քաղաքը Մոլդովայի ամենաաշխույժ նավահանգիստն էր. Ֆաթիհի օրոք, երբ վոյևոդ Պետրու III-ը 1455 թ. ճանաչեց օսմանյան տիրապետությունը, Աքքերմանի առևտրականներին առևտրի թույլտվություն էր տրվել, իսկ այժմ նավահանգիստը դարձավ անմիջապես պետությանը։ Նվաճումից հետո Ռումելիի բեյլերբեյությանը ենթակա սանջակ դարձված Աքքերմանը 1593 թ. միացվեց նորաստեղծ Օզիի էյալեթին։ Այսպիսով, Մոլդովայի արտաքին պատյանը, որը հյուսիսից շրջապատված էր Խոտինով, իսկ հարավից՝ Կիլիայով և Աքքերմանով, սկսեց անցնել օսմանյան անմիջական վերահսկողության տակ. վոյևոդությունը ներքին գործերում ազատ մնաց, բայց այլևս ծով ելք չուներ։ Քարտեզում դրանց միջև դատարկ շրջան չկա. մուգ երանգով նավահանգստային սանջակները և բաց երանգով վոյևոդության հողը հպվում են միմյանց. դրանց միջև ընկած Բուջակի տափաստանը մինչև 1538 թ. դեռ վոյևոդության մաս է։", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["Նավպակտոսի (Իներահտը) հանձնումը. Կորնթոսի ծոցի մուտքը վերցվում է Վենետիկից", "2cfe0777"], "d": ["Նավպակտոսը 1407 թ. ի վեր Վենետիկի ձեռքում էր և պահում էր Կորնթոսի ծոցի մուտքը. ծոցի ներսի ամբողջ ափը կախված էր այս բերդի հրաձգության հեռահարությունից։ 1499 թ. արշավանքում բերդը պաշարվեց ցամաքից, իսկ Նավպակտոսի բաց ծովում վենետիկյան նավատորմի հետ կռիվ մղող օսմանյան նավատորմը ծովից օգնեց պաշարող ուժերին։ Բերդի վենետիկցիները օգոստոսի 26-ին ավանը հանձնեցին օսմանցիներին։ Դրանից հետո քաղաքը հարյուր ութսունութ տարի մնաց Օսմանյան պետության ձեռքում, 1687 թ. Մորեայի կորստով կրկին անցավ Վենետիկին և 1715 թ. հետ գրավվեց։ Նույն ամռան ծովամարտը և այս հանձնումը երկու տարբեր իրադարձություններ են. նավատորմի բախումը տեղի ունեցավ Մորեայի արևմտյան ծայրին՝ Սապիենցա-Զոնկիոյի ջրերում, իսկ Նավպակտոսն ընկավ Կորնթոսի ծոցի մուտքին՝ ցամաքային պաշարմամբ։", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["Սրեբրենիկի բանության բռնակցումը. հյուսիսային Բոսնիայում հունգարական գծի առաջին ճեղքը", "6d98c725"], "d": ["1463 թ. Բոսնիայի թագավորության կործանումից հետո Մաթիաս Կորվինը անցել էր հակահարձակման և թագավորության հյուսիսում ստեղծել երկու բանություն, որոնք կասեցնում էին օսմանյան առաջխաղացումը. արևմուտքում՝ Յայցեն, հյուսիս-արևելքում՝ Սրեբրենիկը։ Դրանք Հունգարիայի առաջավոր պաշտպանական գիծն էին Բոսնիայում և փակում էին Սավայի և Բոսնիայի միջև միջանցքը։ Սրեբրենիկի բանությունը գրավվեց 1512 թ.. այսպիսով, փլուզվեց գծի արևելյան թևը, և Զվորնիկի սանջակը կարողացավ ընդարձակվել դեպի հյուսիս։ Իսկ արևմտյան թևի Յայցեն դիմանալու էր ևս տասնվեց տարի և կարող էր գրավվել միայն Մոհաչից հետո՝ 1528 թ.։", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["Շաբացի (Բյոյուրդելեն) գրավումը. Կանունիի գրաված առաջին բերդը և Բելգրադի վերաբերյալ որոշման կայացման վայրը", "85177a90"], "d": ["Կանունի Սուլթան Սուլեյմանի հունգարական առաջին արշավանքի ժամանակ շրջան ուղարկված Ռումելիի բեյլերբեյ Ահմեդ փաշայի ուժերը, կատաղի պաշարումից հետո, 1521 թ. հուլիսի 7-ին գրավեցին բերդը։ Շաբացը Կանունիի գահակալության ընթացքում գրավված առաջին բերդն է։ Նվաճումից հետո փադիշահը անձամբ մտավ բերդ և հրամայեց կառուցապատել քաղաքը. Բելգրադի գրավման վերաբերյալ որոշումները նույնպես ընդունվեցին այնտեղ, այսինքն՝ 1521 թ. օգոստոսի 29-ին ընկնելիք Բելգրադի ծրագիրը կազմվեց Շաբացում։ Այդ ժամանակից ի վեր բերդը գրեթե երկու հարյուր տարի մնաց օսմանյան ձեռքում. նախ ենթարկվեց Ռումելիի, 1580 թվականից՝ Բոսնիայի էյալեթին, ապա կարճ ժամանակով Սմեդերևոյի և վերջապես Զվորնիկի սանջակին։ Քարտեզում այս թիվը այն օրն է, երբ Սավայի գիծը փակվեց հօգուտ Օսմանյան պետության։", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["Սկսվում է երեք վոյևոդությունների ապստամբությունը. Տրանսիլվանիան անցավ Սրբազան լիգա, օսմանամետ բոյարները ձերբակալվեցին", "68a33800"], "d": ["Երկարատև պատերազմի երկրորդ տարում Կենտրոնական Եվրոպայում Օսմանյան պետության վասալական գոտին միանգամից քայքայվեց։ Հռոմի պապ Կղեմես VIII-ի հովանավորությամբ ստեղծված Սրբազան լիգային ամռան վերջում միացան Մոլդովան և Տրանսիլվանիան. Մոլդովայի վոյևոդ Արոն Վոդան 1594 թ. օգոստոսի 16-ին քրիստոնյա կողմին իր միանալը պաշտոնականացրեց փաստաթղթով, իսկ Տրանսիլվանիայի իշխան Ժիգմոնդ Բատորին 1594 թ. օգոստոսի 28-ին վերացրեց պատերազմի դեմ հանդես եկող օսմանամետ բոյարներին և կոտրեց ներքին ընդդիմությունը։ Վալախիայի վոյևոդ Միհայ Քաջը նույն տարվա աշնանը միացավ լիգային։ Այսպիսով, Դանուբից հյուսիս գտնվող օսմանյան երեք հպատակ իշխանությունները՝ հարյուր հիսուն տարի հարկ վճարող և Ստամբուլի կողմից հաստատվող վոյևոդներ ունեցող երեք վոյևոդությունները, նույն աշնանը միանգամից անցան հակառակ կողմ։ Որոշումը պաշտոնականացվեց 1595 թ. հունվարի 28-ին Պրահայում ստորագրված պայմանագրով։ Սա Բալկաններից հյուսիս օսմանյան անուղղակի կառավարման կարգի կրած ամենածանր ցնցումն էր. ապստամբությունը ճնշվելու էր, բայց երեք իշխանությունների հավատարմությունը այլևս երբեք այնքան ամուր չէր լինելու, որքան 1526-1593 թթ.։", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["Բուխարեստի ապստամբությունը և հարձակումը դանուբյան բերդերի վրա", "18971100"], "d": ["Սրբազան լիգայի որոշումը մեկ ամիս անց իրագործվեց արյունով. Միհայ Քաջը Բուխարեստում սրի քաշեց օսմանյան պահակազորը և քաղաքի լևանտացի պարտատերերին։ Ապստամբությունը նույն ձմռանը տարածվեց Դանուբի գծով. վալախական ուժերը հարձակվեցին Ջուրջուի (Յերկյոկյու), Բրաիլայի, Հըրշովայի և Սիլիստրայի վրա, իսկ Մոլդովայի կողմից Արոն Վոդան նույնպիսի հարձակում կատարեց Բենդերի օսմանյան պահակների վրա։ Հարվածված վայրերի ընտրությունը պատահական չէ. դրանք բոլորը ոչ թե վոյևոդության հող էին, այլ Դանուբի երկայնքով օսմանյան անմիջական կառավարմանը ենթակա բերդեր և կազաներ. Ջուրջուի կազան ենթարկվում էր Նիկոպոլիսի սանջակի բեյությանը, Բրաիլան 1538 թ. ի վեր՝ անմիջապես պետությանը, Բենդերը, դարձյալ 1538 թ. ի վեր, Բուջակի սանջակին։ Այսինքն՝ ապստամբությունը հարվածել էր ոչ թե վասալ ներքին շրջանից, այլ այդ շրջանը շրջապատող անմիջական օսմանյան պատյանին։ Առանց այս պատյանը ծակելու Տրանսիլվանիա-Վալախիա-Մոլդովա եռանկյունին հնարավոր չէր միացնել Հաբսբուրգյան ճակատին։", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["Կալուգերանի ճակատամարտը. Քոջա Սինան փաշայի վալախական արշավանքը", "201210a1"], "d": ["Երեք վոյևոդությունների միանգամից կորստի պատճառով մեծ վեզիր Քոջա Սինան փաշան մեծ բանակով անցավ Դանուբը և շարժվեց Վալախիան կրկին հնազանդեցնելու համար։ Միհայ Քաջը, իմանալով, որ բաց պատերազմում չի կարող դիմադրել, բանակին սպասեց Նեյաժլովի ճահճոտ անցումում՝ Կալուգերանում, և նեղ տարածքում խցկված ուժերի վրա հանկարծակի հարձակվեց։ Հարձակումից հետո, չկարողանալով դիմակայել թվաքանակով գերազանցող օսմանյան բանակին, նա նահանջեց հյուսիս՝ լեռները. Սինան փաշան, օկուպացնելով Բուխարեստը և Թըրգովիշտեն, փորձեց Վալախիան ենթարկել անմիջական կառավարմանը։ Այդ պատճառով Կալուգերանը օսմանցիների համար պարտություն չէր, այլ հանկարծակի հարձակում, որը հետաձգեց արշավանքի ավարտը. սակայն այն, որ Միհայը կարողացել էր պահպանել իր բանակը, հնարավորություն տվեց մի քանի շաբաթ անց Տրանսիլվանիայից ստացված օգնությամբ անցնել հակահարձակման։", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["Նահանջ Վալախիայից և Ջուրջուի հանկարծակի հարձակումը. ճնշման արշավանքի անարդյունք մնալը", "118806e1"], "d": ["Տրանսիլվանիայի իշխանի ուժերի հետ միավորված Միհայ Քաջի հակահարձակման պատճառով Սինան փաշան դատարկեց Թըրգովիշտեն և Բուխարեստը և նահանջեց դեպի Դանուբ։ Նահանջի ամենաթանկ պահը տեղի ունեցավ անցման մոտ. 1595 թ. հոկտեմբերին Վալախիայից վերադարձող բանակին հետապնդող ակընջիները Ջուրջուի մոտ ենթարկվեցին Միհայի հանկարծակի հարձակմանը։ Արշավանքն այսպես ավարտվեց՝ չհասնելով Վալախիան անմիջական կառավարմանը ենթարկելու նպատակին, և վոյևոդությունը փաստացի մնաց կորսված։ Օսմանյան իշխանությունը այս եռանկյունում կարողացավ վերականգնվել միայն տարիների ընթացքում և մաս առ մաս. Տրանսիլվանիայի վերադարձը հնազանդության սպասելու էր 1604 թ. Բոչկաի ապստամբությանը, իսկ ճակատի լիովին փակումը՝ 1606 թ. Ժիտվատորոկի պայմանագրին։", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["Խոտինի անջատումը Մոլդովայից. օսմանյան անմիջական սանջակ վոյևոդության մեջտեղում", "947517cb"], "d": ["Պրուտի արշավանքի ժամանակ Մոլդովայի վոյևոդ Դիմիտրիե Կանտեմիրի անցումը Ռուսաստանի կողմը ցույց տվեց, որ վոյևոդության հյուսիսային սահմանն այլևս չի կարելի թողնել վոյևոդին։ Դրա հիման վրա Խոտինը 1711 թ. հետո վերցվեց Մոլդովայից և դրվեց օսմանյան անմիջական կառավարման տակ. նախ նրան տրվեց նահիեի, ապա սանջակի կարգավիճակ։ 1713 թ. ժամանակավոր ռուսական օկուպացիայից հետո բերդը Ստամբուլից ուղարկված օսմանյան և ֆրանսիացի տեխնիկական պատվիրակության հսկողությամբ կրկին վերանորոգվեց և ընդարձակվեց և դարձավ Դանուբից հյուսիս օսմանյան ամենահզոր ամրությունը։ Այդ ժամանակից ի վեր քարտեզում Խոտինի դուրս գալը հպատակ վոյևոդության երանգից և անմիջական օսմանյան գույն ստանալը, ինչպես նաև այն, որ հպատակ Մոլդովայի մեջտեղում այն կանգնած է միայնակ կղզու նման, հենց այս վարչական անջատման արտացոլումն է, այլ ոչ թե գծագրման սխալ։ Նույն կառուցվածքն արդեն գոյություն ուներ Բուջակում 1538 թ., Կիլիայում և Աքքերմանում՝ 1484 թ. ի վեր. վոյևոդությունը ազատ էր ներքին գործերում, իսկ սահմանային բերդերը պետությանն էին։", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["Շաբացի երկրորդ ավստրիական օկուպացիան. Սավայի ճակատի բացումը", "063b3ad0"], "d": ["1788 թ. փետրվարի 9-ին Ավստրիայի՝ Ռուսաստանի կողքին պատերազմի մեջ մտնելուց հետո Սավայի գիծը կրկին ճակատ դարձավ, և Շաբացը 1788 թ. ապրիլի 24-ին անցավ ավստրիական տիրապետության տակ։ Բերդը ավելի վաղ՝ 1717 թ. օգոստոսի 17-ին, առանց պատերազմի զիջվել էր Ավստրիային և նրա ձեռքում էր պահվել մինչև Բելգրադի պայմանագիրը (1739). այդ ժամանակ նրա բնակչությունն այնքան էր նվազել, որ քաղաքում մնացել էր երեսունչորս քրիստոնյա տուն, իսկ մուսուլման ոչ մեկը չէր մնացել։ 1739-1788 թթ. օսմանյան շրջանում բնակչությունը կրկին հասել էր 1500-2000-ի։ Երկրորդ օկուպացիան ավարտվելու էր Սվիշտովի պայմանագրով (1791 թ. օգոստոսի 4), և բերդը վերադարձվելու էր օսմանցիներին։", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["Շաբացի հանձնումը Կարա Յորգիին. առաջին բերդը Սերբական առաջին ապստամբության ժամանակ", "5c913eb4"], "d": ["1804 թ. Բելգրադում դեյիների և յամաքների ճնշման դեմ ի պատասխան սկսված և հետագայում ազգայնական բնույթ ստացած առաջին սերբական ապստամբության ժամանակ Շաբացի բերդը 1806 թ. հունվարի 26-ին հանձնվեց Կարա Յորգիին։ Սավայի ափի այս բերդը ապստամբների գրաված առաջին խոշոր օսմանյան ամրությունն է և ավետում է Բելգրադի անկումը։ Երբ 1813 թ. ապստամբությունը ճնշվեց և Բելգրադը հետ գրավվեց, բերդն էլ վերադարձավ օսմանյան կառավարման տակ. սակայն 1830 թ. ֆիրմանի կայազորի պայմանով Շաբացը, Բելգրադի, Սմեդերևոյի և Ֆեթհյուլիսլամի հետ միասին, սահմանվեց որպես ինքնավար Սերբիայի ներսում օսմանյան զորքի մնացած չորս բերդերից մեկը և այդ կարգավիճակով մնաց մինչև 1867 թ., երբ կայազորը դուրս բերվեց։", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["Լամիան (İzdin) մնաց Հունաստանի սահմանների ներսում. Արտա-Վոլոս գիծը", "930f63b8"], "d": ["Անկախ հունական պետության հյուսիսային սահմանը 1832 թ. գծվեց Արտայի ծովածոցից մինչև Վոլոսի ծովածոց ձգվող գծով։ Օսմանյան շրջանում (1424-1832) Էվբեայի սանջակին ենթակա կազայի կենտրոն եղած Լամիան, այդ գծից հարավ մնալով, անցավ Հունաստանին. Թեսալիայի մնացած մասը (Լարիսա, Տրիկալա) մինչև 1881 թ. մնաց Օսմանյան պետությանը։", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["Ռուսաստանի պատերազմի հայտարարությունը. «93-ի պատերազմի» սկիզբը", "ac548ab8"], "d": ["1876 թ. բուլղարական ապստամբության ճնշումը մեծ զայրույթ էր առաջացրել եվրոպական հասարակական կարծիքում, և Ռուսաստանը դա լիովին օգտագործել էր Բաբը Ալին (Բարձր Դուռը) մեկուսացնելու համար։ Երբ Օսմանյան պետությունը մերժեց Ստամբուլի (նավաշինարանի) համաժողովի՝ Բուլղարիան երկու ինքնավար էյալեթի բաժանելու առաջարկը և ապա 1877 թ. մարտի 31-ի Լոնդոնի արձանագրությունը, Ռուսաստանը 1877 թ. ապրիլի 24-ին պատերազմ հայտարարեց, և նրա բանակը մտավ իր կողմը գրաված Ռումինիայի իշխանության տարածք (քարտեզը Վալախիա-Մոլդովան այդ պահից մինչև Ադրիանապոլսի զինադադարը ցույց է տալիս ռուսական առաջխաղացման շտրիխավորված ծածկույթով)։ Քանի որ ռումի օրացույցով այն համընկնում էր 1293 թ.-ին, պատերազմը հիշվում է «93-ի պատերազմ» անունով։ Գործողությունն ընթացավ երկու ճակատով՝ դանուբյան և Արևելյան Անատոլիայի. Դանուբում 180.000-անոց օսմանյան բանակը գետի ձախ ափը համարել էր առաջին, իսկ Բալկանյան լեռները՝ երկրորդ պաշտպանական գիծ. արևելքում Ահմեդ Մուխթար փաշայի 55.000 զինվորը դիրքավորված էր Արդահանի և Դողուբայազիթի միջև։ Քարտեզում այս պատերազմը այն իրադարձությունն է, որ սկիզբ դրեց օսմանյան Ռումելիի փլուզմանը. Բուլղարիայի, Սերբիայի, Չեռնոգորիայի և Ռումինիայի ներկայիս բոլոր սահմանները այս տասնհինգ ամիսների արդյունքն են։", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["Ռումինիան հռչակում է անկախություն. Վալախիա-Մոլդովայի հպատակության վախճանը", "bdd164b3"], "d": ["«93-ի պատերազմի» հայտարարությունից երկու շաբաթ անց Ռումինիայի իշխանությունը հռչակեց անկախություն և պատերազմի մեջ մտավ Ռուսաստանի կողմից. Պլևնայի պաշարման մեջ նրա մասնակցությունը վճռորոշ եղավ օսմանյան պարտության համար։ Այսպիսով, Վալախիայի և Մոլդովայի ավելի քան չորսհարյուրամյա հպատակությունը փաստացի ավարտվեց. անկախությունը միջազգային ճանաչում ստացավ Բեռլինի վեհաժողովում (1878)։ Քարտեզը այդ ժամանակից ի վեր Ռումինիան ցույց է տալիս ոչ թե որպես հպատակ, այլ սեփական գույնով անկախ պետություն։ Անկախության հռչակմամբ Վալախիան և Մոլդովան ամբողջությամբ (Յասի, Գալաց, Բրաիլա, Ջուրջու, Կալաֆաթ, Բոտոշան և այլն) դարձան անկախ Ռումինիա։", "9e037d13"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["Ռուսական բանակը անցնում է Դանուբը. Սվիշտովի և Տառնովոյի անկումը", "811367b1"], "d": ["Պատերազմի սկսվելուն պես Ռումինիայի տարածք մտած և այդ իշխանությունը իրենց կողմը գրաված ռուսները առաջ շարժվեցին երկու ուղղությամբ՝ մեկը դեպի Դոբրուջա, մյուսը՝ դեպի Բուխարեստ։ Դանուբն անցան Ռուսչուկի և Նիկոպոլիսի միջև, հունիսի 27-ին գրավեցին Սվիշտովը, իսկ հուլիսի 1-ին՝ բուլղարական նախկին մայրաքաղաք Տառնովոն։ Թեև հրամայված էր դատարկել, բայց դրան ուշադրություն չդարձվեց, և Նիկոպոլիսը նույնպես որոշ ժամանակ դիմադրելուց հետո հանձնվեց։ Առաջին պաշտպանական գծի մեկ շաբաթվա ընթացքում ճեղքվելը Ստամբուլում մեծ խուճապ առաջացրեց. անգամ լուրեր տարածվեցին, թե սուլթանության կենտրոնը տեղափոխվելու է Բուրսա, և պատերազմի ղեկավարումը հանձնվեց մայրաքաղաքում ստեղծված ռազմական խորհրդին։", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["Շիպկայի լեռնանցքի դատարկումը. բալկանյան գծի ճեղքումը", "1f45e50a"], "d": ["Բալկանյան լեռները հատող լեռնանցքներից ամենառազմավարականը հանդիսացող Շիպկայի օսմանյան ուժերը կատաղի կերպով դիմակայեցին ռուսական հարձակումներին. սակայն համոզվելով, որ պարտվելու են՝ հուլիսի 19-ին գաղտնի դատարկեցին լեռնանցքը։ Այսպիսով, բացվեց նաև երկրորդ պաշտպանական գիծը, և գեներալ Գուրկոն հուլիսի 22-ին գրավեց Ստարա Զագորան։ Չեռնոգորիայի կողմից հասած Սուլեյման փաշան, թեև պարտության մատնելով Գուրկոյին, հետ գրավեց Բալկաններից հարավ օկուպացված վայրերը, օգոստոսի 21-ից ամիսներ շարունակ տևած հարձակումներին չնայած՝ Շիպկան հետ գրավել չկարողացավ։ Քարտեզում սա նշանակում է, որ Բալկանյան լեռնաշղթայի հյուսիսի և հարավի միջև պաշտպանական ամբողջականությունը այլևս չվերականգնվեց. դանուբյան ճակատի պայքարն այսուհետ հանգուցվելու էր Պլևնայում։", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["Լովեչը (Լոֆչա) օկուպացվեց ռուսական բանակի կողմից", "70e54611"], "d": ["«93-ի պատերազմում» Լովեչը 1877 թ. հունիսի 5-ին օկուպացվել էր ռուսների կողմից, հունիսի 15-ին Ռիֆաթ փաշայի հրամանատարությամբ օսմանյան ուժերը հետ էին մղել ռուսներին. օգոստոսի 23-ին օսմանցիները լքեցին քաղաքը, և այն կրկին անցավ ռուսական օկուպացիայի տակ։ Քարտեզը Լովեչը այդ օրից մինչև Բեռլինի պայմանագիրը ցույց է տալիս ռուսական օկուպացիայի տակ (շտրիխավորված). իրավաբանորեն այն շարունակում է լինել օսմանյան հող։", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["Կարսի անկումը. արևելյան ճակատի քայքայումը և Ազիզիեի ամրությունները", "53fc3bf5"], "d": ["Արևելյան Անատոլիայում Կարսի, Դողուբայազիթի և Արդահանի ուղղությամբ երեք թևով առաջացող ռուսները ապրիլի 30-ին գրավել էին Դողուբայազիթը և մտել Արդահան, բայց Էրզրումի վրա շարժվելիս հուլիսի 15-ին պարտվելով դուրս էին մղվել սահմանից։ Ահմեդ Մուխթար փաշային «Ղազի» տիտղոսը վաստակեցրած այս հաջողությունը օգոստոսին գեներալ Լազարևի կրկին հարձակման անցնելով հակառակ ընթացք ստացավ, և նոյեմբերի 18-ին Կարսն ընկավ։ Ավելի հարմար պաշտպանության համար Էրզրում նահանջած օսմանյան ուժերը Ազիզիեի ամրություններում, Նենե Հաթունի կողմից բնակչության քաջալերմամբ, մեծ դիմադրություն ցույց տվեցին։ Կարսը, Արդահանը և Բաթումը ութ ամիս անց Բեռլինում ռազմատուգանքի մի մասի դիմաց զիջվելու էին Ռուսաստանին։", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["Բալկանյան առաջին պատերազմի սկիզբը. Չեռնոգորիայի պատերազմի հայտարարությունը", "c0c2697e"], "d": ["Բալկանյան պետությունները, այն բանից հետո, երբ «Միություն և առաջադիմություն» կոմիտեն 1911 թ. հուլիսի 3-ի օրենքով լուծեց եկեղեցիների հարցը, վերացրին իրենց միջև ամենամեծ խոչընդոտը և Ռուսաստանի դրդմամբ 1912 թ. ընթացքում միմյանց հետ դաշինքի պայմանագրեր ստորագրեցին (մարտի 13-ին՝ Սերբիա-Բուլղարիա, մայիսի 29-ին՝ Բուլղարիա-Հունաստան, օգոստոսին՝ Չեռնոգորիա-Բուլղարիա, հոկտեմբերի 6-ին՝ Չեռնոգորիա-Սերբիա)։ Բաբը Ալին դա չնկատեց. նույնիսկ, վստահելով Ռուսաստանի երաշխիքին, զորացրեց Ռումելիի 120 վարժեցված գումարտակները։ Չորս պետությունները հոկտեմբերի 3-ին համատեղ նոտա տալով՝ պահանջեցին ինքնավարություն Մակեդոնիայի, Ալբանիայի և Կրետեի համար. պատասխան չստանալով՝ 1912 թ. հոկտեմբերի 8-ին Չեռնոգորիայի պատերազմի հայտարարությամբ սկսվեց գործողությունը։ Հոկտեմբերի 13-ին Սերբիայի և Բուլղարիայի դեսպաններին հանձնվեցին նրանց անձնագրերը, հաջորդ օրը այս երկու պետությունները, ապա Հունաստանը պատերազմ հայտարարեցին։ Պատերազմի ընթացքում բանակի ներսում քաղաքական հայացքների տարաձայնությունները մեծ դեր խաղացին պարտության մեջ։", "33b60249"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["Ռոդոպներում Քըրջալիի զորախումբը ջախջախվեց, Քըրջալին ընկավ", "8cf59b7f"], "d": ["Բուլղարիայի պատերազմի հայտարարությունից հետո Ռոդոպներից իջնող բուլղարական ուժերը, հաղթելով Մեհմեդ Յավեր փաշայի Քըրջալիի զորախմբին, մտան Քըրջալի։ Ջախջախված զորախումբը նահանջեց Կոմոտինիի ուղղությամբ. Ռոդոպների արևելյան հատվածը կորսվեց պատերազմի առաջին շաբաթում։", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["Արևելյան բանակի ջախջախումը և նահանջը Չաթալջայի գիծ. Կումանովոյի և Սալոնիկի կորուստը", "cf95591a"], "d": ["Օսմանյան Արևելյան բանակը 1912 թ. հոկտեմբերի 23-ին, պարտվելով իրենից երեք անգամ բազմաքանակ բուլղարական բանակին, նահանջեց մինչև Ստամբուլից երեսուն կիլոմետր արևմուտք ընկած Չաթալջայի գիծը. մայրաքաղաքը պատերազմի առաջին ամսում ընկավ անմիջական սպառնալիքի տակ։ Նույն օրերին Արևմտյան բանակը հոկտեմբերի 23-24-ին Կումանովոյում պարտվեց սերբերին, և Թահսին փաշան իր 35.000-անոց բանակով Սալոնիկում անձնատուր եղավ հույներին։ Այս ջախջախումների հետևանքով հոկտեմբերի 29-ին Ղազի Ահմեդ Մուխթար փաշայի կաբինետը հրաժարական տվեց. Սալոնիկում աքսորական կյանք վարող Աբդուլհամիդ II-ը նոյեմբերի 1-ին տեղափոխվեց Ստամբուլ։ Չաթալջայի գիծը պահվեց մինչև պատերազմի ավարտը. Ռումելիի հինգհարյուրամյա օսմանյան աշխարհագրությունը մի քանի շաբաթում սեղմվեց այս նեղ գոտու մեջ։", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["Նովի Պազարի սանջակի կենտրոն մտավ իշխան Ալեքսանդարը", "326d0616"], "d": ["Սերբական ուժերը պատերազմի առաջին շաբաթում գրավեցին Նովի Պազարը և միացան արևմուտքից եկող չեռնոգորական ուժերին։ Այսպիսով, Սերբիան և Չեռնոգորիան հարյուր տարի բաժանող Նովի Պազարի սանջակը վերածվեց երկու դաշնակիցների միջև կամրջի։", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["Քըրքքիլիսեի ճակատամարտից հետո Քըրքլարելին կորսվեց", "eda4c759"], "d": ["Արևելյան Թրակիայում Արևելյան բանակի՝ Քըրքքիլիսեի ճակատամարտում պարտվելուց հետո Քյոլեմեն Աբդուլլահ փաշայի պաշտպանած քաղաքը թողնվեց բուլղարական ուժերին։ Քաղաքը իննամսյա օկուպացիայից ազատագրվեց միայն Բալկանյան երկրորդ պատերազմում՝ 1913 թ. հուլիսի 21-ին։", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["Կոսովոյի վիլայեթի կենտրոն Սկոպյեն լքվեց առանց դիմադրության", "455d9b71"], "d": ["Կումանովոյի պարտությունից (հոկտեմբերի 23-24) հետո Կոսովոյի վիլայեթի կենտրոն Սկոպյեն մնաց անպաշտպան։ Քանի որ ժողովուրդը չէր ցանկանում կռիվ քաղաքի շուրջ, հյուպատոսների միջոցով հրավիրված իշխան Ալեքսանդարի հրամանատարությամբ սերբական ուժերը հոկտեմբերի 26-ի երեկոյան առանց դիմադրության մտան քաղաք։", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["Վարդարի երկայնքով Վելեսը (Քյոփրյուլյու) կորսվեց", "73d20b7d"], "d": ["Սկոպյեի անկումից երկու օր անց Վարդարի երկայնքով դեպի հարավ իջնող սերբական բանակը գրավեց Վելեսը։ Այսպիսով, Վարդարի հովտի՝ դեպի Սալոնիկ բացվող դարպասը անցավ սերբերի ձեռքը։", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["Բրեգալնիցայի ավազան. գեներալ Ստեֆանովիչը մտավ Շտիպ", "70a84256"], "d": ["Գեներալ Ստեֆանովիչի հրամանատարությամբ սերբական զորամասերը առանց դիմադրության հանդիպելու գրավեցին Շտիպը. քաղաք նախ մտան անկանոն ջոկատները։ Կումանովոյից հետո արևելյան Մակեդոնիայի Բրեգալնիցայի ավազանը անցավ սերբական վերահսկողության տակ։", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["Սարանդապորոյի լեռնանցքից հետո Վերիան (Կարաֆերիե) անցավ հունական տիրապետության տակ", "02a68e02"], "d": ["Թեսալիայից դեպի հյուսիս առաջացող հունական բանակը, հաղթահարելով Սարանդապորո (Քըրքգեչիթ) լեռնանցքը, տիրեց Վերիային։ Քաղաքի մուսուլման բնակչության մի մասը այդ ժամանակ լքեց շրջանը։", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["Սալոնիկ-Մոնաստիր (Բիթոլա) երկաթուղու վրա գտնվող Վոդենան կորսվեց", "fc15b917"], "d": ["Սալոնիկ-Մոնաստիր երկաթուղու վրա գտնվող Վոդենան անցավ հունական բանակի ձեռքը։ Սլավոնական և թուրք բնակչության բռնի հեռացմամբ քաղաքի բնակչությունը կարճ ժամանակում լրջորեն նվազեց։", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["Ենիջեի ճակատամարտը. Ենիջե-ի Վարդարի անցումը հույներին", "8f6cb76e"], "d": ["Հասան Թահսին փաշայի 8-րդ համակցված կորպուսը Սալոնիկից արևմուտք գտնվող Ենիջեում պարտվեց հունական բանակին և նահանջեց Սալոնիկի շրջան։ Ճակատամարտի ընթացքում ավանի մեծ մասն այրվեց. դեպի Սալոնիկ ճանապարհը բացվեց հունական բանակի առաջ։", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["Պրիզրենը Կոսովոյի հարավ-արևմուտքում հանձնվեց", "bae6b1b9"], "d": ["Կոսովոյի հարավ-արևմուտքում գտնվող Պրիզրենը հանձնվեց սերբական ուժերին։ Քաղաք մտած զորամասերի վերաբերմունքը մուսուլման բնակչության նկատմամբ արձանագրվեց որպես Կոսովոյում պատերազմի ամենածանր էջերից մեկը։", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["Գնդապետ Միտովը Ստրումիցայում ռազմական դրություն հայտարարեց", "bcad75cc"], "d": ["Բուլղարացի գնդապետ Միտովը, մտնելով Ստրումիցա, ռազմական դրություն հայտարարեց. հաջորդ օրը հեռանալիս ավանը թողեց բուլղարացի կայմակամի և սերբ հրամանատարի։ Ստրումիցան պատերազմի ողջ ընթացքում ձեռքից ձեռք անցավ դաշնակիցների միջև և 1913 թ. միացվեց Բուլղարիային։", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["Հասան Թահսին փաշան Սալոնիկը թողեց հույներին", "1738933c"], "d": ["Ենիջեի պարտությունից հետո Սալոնիկ նահանջած Հասան Թահսին փաշան, երբ բուլղարական բանակը մոտենում էր հյուսիսից, քաղաքը թողեց հույներին. հունական բանակը քաղաք մտավ նոյեմբերի 8-ի կեսօրին։ Այսպիսով, կորսվեց օսմանյան Ռումելիի ամենամեծ նավահանգստային քաղաքը և «Միություն և առաջադիմություն» կոմիտեի ծննդավայր Սալոնիկը։", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["Արևմտյան Թրակիայի կենտրոն Կոմոտինին բացվեց բուլղարների առաջ", "96eec25f"], "d": ["Քըրջալիից նահանջած Յավեր փաշայի զորախմբի՝ Ֆերեի ուղղությամբ հետ քաշվելուց հետո Կոմոտինին հանձնվեց բուլղարական ուժերին։ Արևմտյան Թրակիայի կենտրոնը պատերազմի վերջում Բուլղարիային թողնվելիք հողերի գլխին էր։", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["Էլբասան հասած սերբերը նույն օրը մտան Դիբրա", "16720246"], "d": ["Մոնաստիրից դեպի արևմուտք առաջացող սերբական ուժերը այն օրը, երբ հասան Էլբասան, մտան նաև Դիբրա և իջան դեպի Ադրիատիկ։ Նույն օրը Ավլոնիայում հռչակվում էր Ալբանիայի անկախությունը։", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["Լենկթեմուրը երկրորդ անգամ օկուպացրեց Բաղդադը. քաղաքի աբբասյան թաղամասերը քանդվեցին", "04b68a24"], "d": ["Լենկթեմուրը ութ տարվա ընդմիջումով երկու անգամ գրավեց Բաղդադը։ 1393 թ. առաջին օկուպացիայի ժամանակ քաղաքը շատ վնաս չէր կրել. իսկ 1401 թ. երկրորդը համարվում է Բաղդադի մշակութային կյանքին հասցված երկրորդ ծանր հարվածը. ժողովուրդը սրի քաշվեց, աբբասյան ժամանակաշրջանից մնացած թաղամասերի և շենքերի մեծ մասը ավերվեց։ Ջալայիրյան տիրակալ Ահմեդը, թեև 1405 թ. քաղաք վերադառնալով փորձեց նորոգել քանդված պարիսպները և շուկաները, ժամանակ չունեցավ. Բաղդադը 1410 թ. անցավ Կարա-Կոյունլու թուրքմենների ձեռքը։ Այս երկու օկուպացիաները Անկարայի ճակատամարտին տանող ճանապարհին ամենաշոշափելի քայլերից են, որոնք ցույց են տալիս, թե որքան էր Լենկթեմուրը մոտեցել օսմանյան և մամլուքյան սահմաններին։", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["Ջյունեյդ բեյը վերադարձավ Այդընի երկրի գլուխ. Այդընօղուլները կրկին անկախ են", "63281658"], "d": ["Մեհմեդ Չելեբին 1414-15 թթ., գրավելով Իզմիրը և Ջյունեյդ բեյին ուղարկելով Նիկոպոլիսի սանջակի բեյության, Այդընի երկիրը կապել էր օսմանյան կառավարմանը։ Ջյունեյդը Մեհմեդ Չելեբիի մահից հետո կրկին բեմ դուրս եկավ Մուստաֆա Չելեբիի կողքին, որին Բյուզանդիան առաջ էր քաշել որպես գահի հավակնորդ, և նույնիսկ նրա վեզիրն էր։ Մուրադ II-ը, խոստանալով վերադարձնել նրա նախկին բեյությունը, անջատեց նրան այդ դաշինքից. Ջյունեյդն էլ, վերադառնալով Իզմիր, գրավեց Այասուլուկը և, սպանելով Այդընօղլու Մուստաֆա բեյին, անցավ բեյության գլուխ։ Այսպիսով, Այդընի երկիրը ծնվեց որպես Կեղծ Մուստաֆայի ճգնաժամի ընթացքում օսմանյան կառավարումից դուրս եկած երկիր։", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["Ջյունեյդ բեյի և նրա ընտանիքի մահապատիժը. Այդընօղուլների բեյության վախճանը", "efa684ba"], "d": ["Այդընի երկրում կրկին իշխանություն ձեռք բերած Ջյունեյդ բեյը գրգռում էր Անատոլիայի բեյերին և կապ էր փնտրում Վենետիկի հետ. դրա պատճառով Մուրադ II-ը նրա դեմ ուղարկեց Անատոլիայի բեյլերբեյ Համզա բեյին։ Երբ նրա որդի Կուրդ Հասանը Ակհիսարի մոտ պարտվեց և գերի ընկավ, Ջյունեյդը նահանջեց Սամոս կղզու դիմաց գտնվող Իփսիլի. Կարամանօղլուից սպասած օգնությունը չգալուց և օսմանցիների հետ գործող ջենովացիների կողմից ծովից շրջափակվելուց հետո նա ստիպված եղավ անձնատուր լինել և իր ողջ տոհմով վերացվեց։ Այսպիսով, Այդընօղուլների հողերն ամբողջությամբ անցան օսմանյան կառավարման տակ։", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["Էրզրումը և Վանի գոգավորությունը անցան Սեֆյաններին. փլուզվեց Ակ-Կոյունլուների հյուսիսային թևը", "b418875f"], "d": ["Շարուրում Էլվենդ բեյին հաղթած և 1501 թ. ամռանը Թավրիզ մտած Շահ Իսմայիլը հաջորդ տարի, առաջանալով հյուսիս-արևմտյան ուղղությամբ, իր տիրապետության տակ առավ Էրզրումից մինչև Վանա լճի գոգավորությունը ձգվող գիծը։ Ակ-Կոյունլու պետությունը Ուզուն Հասանի մահից հետո արդեն գահակալական կռիվներով բաժանվել էր երկուսի. Էլվենդ բեյը պահում էր Ատրպատականը և Դիարբեքիրը, իսկ նրա հորեղբորորդի Մուրադը՝ Պարսկական Իրաքը և Ֆարսը։ Այս բաժանումը հեշտացրեց սեֆյան առաջխաղացումը. շրջանը տասը գրառման չափով մեկ տարում ձեռքից ձեռք անցավ։ Էրզրումը դրանից հետո տասնվեց տարի մնաց սեֆյան ձեռքում և օսմանյան տիրապետության տակ անցավ միայն Չալդըրանից հետո՝ 1518-19 թթ.։ Այդ տարում (1502) Աշկալեն և Բասենը (Հասանկալե), Էրզրումի շրջանի հետ միասին, Ակ-Կոյունլուներից անցան Սեֆյաններին (օրը հաստատված չէ)։", "2f80b39d"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["Մուրադ բեյի պարտությունը Համադանում. Պարսկական Իրաքը և Ֆարսը անցան Սեֆյաններին", "8de07a31"], "d": ["Ակ-Կոյունլու գահի երկրորդ հավակնորդ Սուլթան Մուրադը Համադանի մոտ Շահ Իսմայիլի դեմ տեղի ունեցած ճակատամարտում ծանր պարտություն կրեց և փախավ Բաղդադ։ Այս մեկ ճակատամարտով Պարսկական Իրաքը, Ֆարսը և Քերմանի շրջանները անցան սեֆյան կառավարման տակ. քարտեզում այս շրջանները միաժամանակ ձեռքից ձեռք են անցնում։ Սա Ակ-Կոյունլու պետության կազմալուծման ամենամեծ միակ քայլն է. Թավրիզի կորուստը հարստությունը թողել էր առանց մայրաքաղաքի, իսկ Համադանի պարտությունը՝ առանց հողի։", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["Շահ Իսմայիլը մտավ Յազդ. ընկավ Ակ Կոյունլուների մնացորդի վերջին ամրոցը Կենտրոնական Իրանում", "6f9835df"], "d": ["Թեև 1503 թ. Համադանի պարտությունից հետո Իրաք-ի Աջեմն ու Ֆարսն անցել էին Սեֆյաններին, Յազդը դեռ առանձին մնում էր Ակ Կոյունլու հարստությունից սերած Բայընդըրլը Մուրադ բեյի ձեռքին։ Քաղաքն ընկավ մեկամսյա պաշարումից հետո, և փակվեց Կենտրոնական Իրանում Ակ Կոյունլուների վերջին կղզյակը։ TDV-ի գրառումը. «Շահ Իսմայիլը մեկամսյա պաշարումից հետո քաղաք մտավ հիջ. 910 թ. Ջումադա աս-սանիյա ամսի 28-ին (1504 թ. դեկտեմբերի 6)»։", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["Շահ Իսմայիլի Դիարբեքիրի արշավանքը. ընկան Ակ Կոյունլուների վերջին կենտրոնները", "b6d8504e"], "d": ["Ատրպատականն ու Իրանական սարահարթը գրաված Շահ Իսմայիլը 1507 թ. ուղղվեց դեպի արևմուտք՝ Դիարբեքիրի շրջան, որտեղ ծնվել էր Ակ Կոյունլու հարստությունը։ Ամիդից Մարդին և Ուրֆայից Խարբերդ ձգվող գիծը երկու հարվածով անցավ սեֆյան կառավարման տակ, և Ակ Կոյունլուները փաստացի վերացան։ Այս արշավանքը միաժամանակ առաջին անգամ սեֆյան սահմանը հասցրեց օսմանյան և մամլուքյան սահմաններին. այդպես ձևավորվեց դեպի Չալդըրան տանող լարվածության աշխարհագրական հիմքը։", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["Բաղդադն անցավ Սեֆյաններին. Իրաք-ի Արաբը ձեռքից ձեռք անցավ", "39730186"], "d": ["Համադանի պարտությունից հետո Բաղդադում ապաստանած Ակ Կոյունլու սուլթան Մուրադի հետևից Շահ Իսմայիլը 1508 թ. մտավ Իրաք-ի Արաբ և գրավեց Բաղդադը։ Քարբալայի և Նաջաֆի սրբավայր-դամբարանների անցումը սեֆյան կառավարման տակ շարժման կրոնադավանական հավակնության տեսանկյունից նույնքան կարևոր էր, որքան Թավրիզի գրավումը։ Քարտեզում Իրաք-ի Արաբը ձեռքից ձեռք է անցնում նույն օրը. սա փլուզման վերջին և աշխարհագրորեն ամենալայն քայլն է։ Բաղդադը Սեֆյանների ձեռքին մնաց մինչև 1534 թ.՝ Կանունի Սուլեյմանի «երկու Իրաքների» արշավանքը։", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["Մերվի ճակատամարտը. ուզբեկները ծանր պարտություն կրեցին, գրավվեցին Մերվն ու Հերաթը", "f8e45aaf"], "d": ["Արևմուտքում Ակ Կոյունլուների ժառանգությունն ամբողջացրած Շահ Իսմայիլը շարժվեց արևելք՝ Խորասան, և Մերվի մատույցներում ծանր պարտության մատնեց ուզբեկներին. Շեյբանի խանը զոհվեց ռազմադաշտում։ Մերվն ու Հերաթն անցան սեֆյան տիրապետության տակ, և Սեֆյան պետությունը հասավ Եփրատից մինչև Ամու Դարիա ձգվող սահմաններին։ Այսպիսով, 1501 թ. ամռանը Թավրիզ մտնելով սկսված ընթացքն ավարտվեց ինը տարում. Ակ Կոյունլուների ժառանգությունն ամբողջությամբ անցավ սեֆյան կառավարման տակ, և Օսմանյան պետությունն արևելքում հարևան դարձավ իր չափի երկրորդ պետությանը։", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["Զաբիդի վերջնական անցումը օսմանյան տիրապետության տակ", "ddd971c7"], "d": ["1538 թ. նոյեմբերի 5-ին Դիուի պաշարումը վերացրած նավատորմը վերադարձի ճանապարհին կանգ առավ Եմենի ափին, և Զաբիդը վերջնականապես կապվեց օսմանյան կառավարմանը. Հադըմ Սուլեյման փաշան քաղաքից մեկնեց 1539 թ. մարտի 10-ին և ապրիլի 1-ին հասավ Ջիդդա։ 1517 թվականից քաղաքը Օսմանյան պետության անունից կառավարում էին նախկին մամլուք բեյերը. այս թվականից այն անցավ ուղղակի կառավարման տակ։", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["Իբերիական միություն. Պորտուգալիայի թագն անցավ Իսպանիայի թագավորին", "1cc6dfdc"], "d": ["Կարդինալ-թագավոր Էնրիկեի անժառանգ մահով բացված գահաժառանգության վեճը Ալկանտարայի ճակատամարտում (1580 թ. օգոստոսի 25) վերջացավ հօգուտ Իսպանիայի, և Տոմարում հավաքված Պորտուգալիայի կորտեսը 1581 թ. ապրիլի 16-ին Ֆիլիպ II-ին ճանաչեց Պորտուգալիայի թագավոր։ Տոմարի պայմանների համաձայն՝ Պորտուգալիան պահպանելու էր իր հաստատությունները, դրամն ու լեզուն, կառավարման պաշտոններում նշանակվելու էին միայն պորտուգալացիներ, իսկ Մադրիդում լինելու էր առանձին Պորտուգալական խորհուրդ. այսինքն՝ միավորումը անձնական ունիա էր, ոչ թե բռնակցում։", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["Վերականգնում (Restauração). Պորտուգալիան վերականգնեց իր անկախությունը", "64ec0738"], "d": ["Այն օրերին, երբ Կատալոնիայի ապստամբությունը զբաղեցնում էր Իսպանիային, Լիսաբոնում մի խումբ ազնվականներ, հարձակվելով պալատի վրա, տապալեցին իսպանական կառավարումը և Բրագանսայի դուքսին Ժուան IV անունով թագավոր հռչակեցին։ Այսպես ավարտվեց վաթսուն տարի տևած Իբերիական միությունը. սակայն Սեուտան ընտրեց մնալ Իսպանիայի կազմում, և դա ճանաչվեց 1668 թ. Լիսաբոնի պայմանագրով։ Այս ժամանակահատվածը, երբ Պորտուգալիան ներքաշված էր Հաբսբուրգների պատերազմների մեջ, նաև Ասիայում նրա կորուստների շրջանակն է. Որմուզը կորսվեց 1622 թ., Մալաքան՝ 1641 թ., Կոլոմբոն՝ 1656 թ., իսկ Տանժերն ու Բոմբեյը, որպես անկախության գին, տրվեցին Անգլիային։ Աղբյուր՝ Britannica, History of Portugal — Restoration։", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["Տանժերը հանձնվեց Անգլիային", "1f7cad6d"], "d": ["Պորտուգալիայի անկախության պատերազմում անգլիական աջակցությունն ապահովելու համար կնքված ամուսնական պայմանագրի (1661 թ. հունիսի 23) երկրորդ հոդվածով Տանժերը որպես Եկատերինա Բրագանսացու օժիտ անցնում էր Անգլիային։ Սենդվիչի կոմսի նավատորմը խարիսխ գցեց 1662 թ. հունվարի 29-ին, և հաջորդ օրը Պիտերբորոյի կոմսի ղեկավարած արարողությամբ կատարվեց պաշտոնական հանձնումը։ Անգլիացիները քաղաքը լքելու էին 1684 թ.։", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["Նադիր շահի սպանությունը. Աֆշարների իշխանության քայքայումը", "19c218c0"], "d": ["Սեֆյան գահին վերջ դրած և 1736 թ. իր անունով թագավորություն հռչակած, հնդկական արշավանքով մինչև Դելի հասած, Օսմանյան պետության դեմ երեք պատերազմ մղած և 1746 թ. Քերդենի պայմանագրով հաշտություն կնքած Նադիր շահը իր վրանում սպանվեց սեփական թիկնապահների ձեռքով։ Դրանից հետո Իրանն այլևս հնարավոր չեղավ կառավարել մեկ կենտրոնից. քառասունինը տարի երկիրը բաժանված էր Խորասանում Աֆշարների մնացորդի, հարավում Զենդերի և հյուսիսում վերելք ապրող Ղաջարների միջև։ Օսմանյան արևելյան սահմանն այս մասնատվածության շնորհիվ երկար ժամանակ հանգիստ մնաց։ Նադիր շահը սպանվեց 1747 թ. հունիսի 20-ին. ըստ TDV-ի՝ Երևանի խանությունը հիմնվեց նույն տարում (1747), օրը հաստատված չէ։", "75fd6ab9"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["Ղաջար հարստության հաստատվելը Իրանի վրա", "744b48c5"], "d": ["Ղաջար ցեղի առաջնորդ Աղա Մուհամմեդ խանը, տապալելով Զենդերի իշխանությունը և կոտրելով նաև Խորասանում Աֆշարների վերջին դիմադրությունը, Իրանը կրկին միավորեց մեկ իշխանության ներքո և Թեհրանը դարձրեց մայրաքաղաք։ Այսպես փակվեց քառասունինը տարի տևած մասնատվածության շրջանը. այսուհետ մինչև 1923 թ. Օսմանյան պետության արևելյան հարևանը լինելու էր Ղաջարների Իրանը։ Մաշհադում, ըստ TDV İslâm Ansiklopedisi-ի, 1796 թ. Աղա Մուհամմեդ շահին դիմավորեց Աֆշար տիրակալ Շահռուխը, և քաղաքն անցավ Ղաջարների տիրապետության տակ (օրը աղբյուրում նշված չէ)։", "755b544a"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["Ֆերդինանդը գրավեց Բուդան. Սապոյայիին դուրս մղեցին մայրաքաղաքից", "99f77c29"], "d": ["Մոհաչից հետո հունգարական գահին երկու թագավոր հայտնվեց. ազնվականների մի մասն ընտրել էր Յանոշ Սապոյայիին, մյուս մասը՝ Ֆերդինանդ Հաբսբուրգին։ 1527 թ. Ֆերդինանդը գրավեց Բուդան և Սապոյայիին դուրս մղեց մայրաքաղաքից. Սապոյայիը օգնություն խնդրեց սուլթան Սուլեյմանից։ Սա է պատճառը, որ 1529 թ. Վիեննայի արշավանքի առաջին թիրախը Բուդան էր։", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["Բարբարոսի արշավանքը Էգեյան կղզիների դեմ. Նաքսոսի դքսությունն անցավ օսմանյան վերահսկողության տակ", "722b2fea"], "d": ["1207 թվականից Վենետիկի խնամակալությամբ լատին դուքսերի կառավարած Նաքսոսի դքսությունը Բարբարոս Հայրեդդին փաշայի կղզիական արշավանքով անցավ օսմանյան վերահսկողության տակ։ Կղզու կարգավիճակին ձեռք չտվեցին. դքսությունը շարունակեց գոյատևել որպես Օսմանյան պետությանը ենթակա, իսկ 1540 թ. օսմանա-վենետիկյան պայմանագրով տիրապետության իրավունքը պաշտոնապես փոխանցվեց օսմանցիներին։", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["Խաչակրաց նավատորմը գրավեց Ջերբան. Թուրգութ փաշայի հենակետը ձեռքից գնաց", "f41b3f2a"], "d": ["Իսպանիայի, Պապական պետության, Մալթայի, Ջենովայի և Ֆլորենցիայի նավերից կազմված խաչակրաց նավատորմը թիրախ դարձրեց Ջերբան, որը Թուրգութ ռեիսը 1551 թվականից օգտագործում էր որպես ասպատակությունների հենակետ։ Փոթորիկների և համաճարակի պատճառով նավատորմը կղզու մատույցներ կարողացավ հասնել միայն 1560 թ. սկզբին. 1560 թ. մարտի 12-ին այն գրավեց կղզին և բերդ կառուցեց։ Լուրն առնելով՝ Փիյալե փաշան մարտի 28-ին 120 գալերայից կազմված նավատորմով դուրս եկավ Ստամբուլից։ Գրավումը երկար չտևեց. օսմանյան նավատորմը մայիսին Ջերբայի առջև հաղթեց դաշնակիցներին, իսկ բերդը հետ առնվեց հուլիսի վերջին։ Այս արշավանքը Պրևեզայից հետո Միջերկրական ծովում օսմանյան գերակշռությունն ամրապնդած երկրորդ խոշոր ծովային գործողության սկիզբն է։", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["Ջերբայի բերդի անկումը. կղզին անցավ օսմանյան կառավարման տակ", "f1efc0df"], "d": ["1560 թ. մայիսի 14-ին Փիյալե փաշայի ծովային հաղթանակից հետո խաչակրաց ուժերը փակվեցին կղզում իրենց կառուցած բերդում. Տրիպոլիի (Լիբիա) բեյլերբեյ Թուրգութ փաշայի ուժերը այն պաշարեցին ցամաքից։ Երկու ամիս տևած պաշարումն ավարտվեց 1560 թ. հուլիսի 30-ին բերդի անկմամբ, և կղզին կապվեց Տրիպոլիի բեյլերբեյությանը։ Ծովային հաղթանակի և բերդի գրավման միջև յոթանասունյոթ օր կա. կղզին փաստացի ձեռքից ձեռք անցավ ոչ թե մայիսի 14-ին, այլ հուլիսի 30-ին։", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["Դանցիգում ավարտվեց ռուս-պրուսական երկիշխանությունը. Նապոլեոնի ազատ քաղաքը վերադարձավ Պրուսիային", "1ccda4d2"], "d": ["Թիլզիտի հաշտությամբ (1807 թ. հուլիսի 9) Պրուսիայից անջատված և ֆրանսիական հովանավորության տակ ազատ քաղաք դարձած Դանցիգը Նապոլեոնի ուժերը լքեցին 1813 թ. պաշարումից հետո։ 1814 թ. հունվարի 2-ից փետրվարի 4-ը քաղաքում տևեց ռուս-պրուսական երկիշխանությունը. երբ Ալեքսանդր ցարը հրաժարվեց Դանցիգն ու Վիստուլայի գետաբերանը վերցնելու ծրագրից, քաղաքն անցավ պրուսական կառավարման տակ։", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["Վիեննայում Կրակովը հռչակվեց ազատ, անկախ և չեզոք քաղաք", "19eea839"], "d": ["Վիեննայի վեհաժողովում Ռուսաստանը, Ավստրիան և Պրուսիան Կրակով քաղաքն իր շրջակայքով դարձրին ազատ պետություն՝ երեք տերությունների պաշտպանության ներքո. Վիեննայի եզրափակիչ ակտն ամրագրեց այս կարգը։", "21a6fe2b"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["Բորնուն անցավ Ռաբիհ իբն Զուբեյրի տիրապետության տակ", "8be4ca96"], "d": ["Բագիրմին և Վադաին ցնցած սուդանցի զորավար Ռաբիհ իբն Զուբեյրը գրավեց Բորնուն. մինչև 1896 թ. նա տիրեց ամբողջ երկրին և Դիկվան դարձրեց իր կենտրոնը։", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["Ռաբիհ իբն Զուբեյրը պարտվեց ֆրանսիացիներին և սպանվեց. Բորնուում նրա իշխանությունը քայքայվեց", "fb5a3ace"], "d": ["Ֆրանսիական գաղութային բանակից պարտված Ռաբիհը սպանվեց. նրա որդին թեև ցանկացավ շարունակել իշխանությունը, չկարողացավ դիմանալ, և 1902 թ. Բորնուն բաժանվեց Ֆրանսիայի, Անգլիայի և Գերմանիայի միջև։", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["Հռչակվեց Արևմտյան Թրակիայի ժամանակավոր կառավարությունը՝ Կոմոտինի կենտրոնով", "974b2e28"], "d": ["Երբ Բուխարեստի պայմանագիրը (1913 թ. օգոստոսի 10) Արևմտյան Թրակիան թողեց Բուլղարիային, շրջանի թուրք բնակչությունը հռչակեց Կոմոտինի կենտրոնով ժամանակավոր կառավարություն. Ալեքսանդրուպոլիսի (Դեդեաղաչի) գրավումից հետո կառավարությունն իր անկախությունն ազդարարեց «Արևմտյան Թրակիայի անկախ կառավարություն» անունով։ Մեծ տերությունների միջամտության հետևանքով օսմանյան կառավարությունը նրան չաջակցեց. 1913 թ. սեպտեմբերի 29-ի Կոստանդնուպոլսի պայմանագիրը Արևմտյան Թրակիան թողեց բուլղարներին, և կառավարությունը մինչև 1913 թ. հոկտեմբերի 25-ը գոյատևեց ընդամենը հիսունյոթ օր։", "86d3bfee"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["Օրհան Ղազիի մահը. բեյությունից պետության անցման քառասուն տարիների ավարտը", "62c59cfd"], "d": ["1324 թ. Օսման Ղազիի մահից հետո բեյության գլուխ անցած Օրհան Ղազին իր երեսունութամյա կառավարման ընթացքում Օսմանյան բեյությունը սահմանային իշխանությունից վերածեց Մարմարայի երկու ափերին հաստատված պետության. գրավվեցին Բուրսան (1326), Իզնիկը (1331) և Իզմիթը (1337), բռնակցվեց Կարեսիի բեյությունը, հատվեց առաջին ակչեն (1327), Իզնիկում հիմնվեց առաջին մեդրեսեն (1331), իսկ Ռումելիա անցումը կայուն դարձավ Չիմպեի (1352) և Գելիբոլուի (1354) միջոցով։ 1357 թ. որսի ժամանակ պատահած դժբախտ դեպքի հետևանքով նա կորցրեց Ռումելիայի նվաճումները վարող ավագ որդուն՝ Սուլեյման փաշային. ինքը մահացավ 1362 թ. մարտին Բուրսայում, և նրան հաջորդեց որդին՝ Մուրադ I-ը։", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["Բահրեյնի կղզիներն անցան Ջաբրիների ձեռքը", "6a242b16"], "d": ["TDV-ի «Բահրեյն» հոդվածը գրառում է, որ կղզին «հաջորդաբար մնաց Ույունիների, Սալղուրյանների, Թաբիների և Ջաբրիների կառավարման տակ, և Ջաբրիների օրոք բնակչության մեծամասնությունը շիաներից դարձավ սուննիներ». դրանցից ոչ մեկի համար թվական չի տալիս։ Ընդհանուր գրականության համաձայն՝ Ջաբրիների հարստությունը հիմնվել է 15-րդ դարի սկզբին՝ Կատիֆի վերջին Ջարվանյան տիրակալին գահընկեց անելով, և իր ամենափայլուն շրջանում (Ակվադ իբն Զամիլ, մահ. 1496) վերահսկել է Պարսից ծոցի ամբողջ արաբական ափը, Լահսան, Կատիֆը և Բահրեյնի կղզիները։ Ակվադից հետո Ավալ կղզիներն անցան Մուկրին իբն Զամիլին. նա է այն տիրակալը, որը 1521 թ. պարտվելու էր պորտուգալացիներին։", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["Պորտուգալիան գրավեց Արզիլան. երկրորդ հենակետը Մարոկկոյի ափին", "83444a11"], "d": ["Աֆոնսու V-ը 30.000 հոգանոց ուժով և 400 նավից բաղկացած նավատորմով անձամբ ափ իջավ Մարոկկոյում և 1471 թ. օգոստոսի 24-ին գրավեց Վատասյանների կառավարման տակ գտնվող Արզիլան։ Քաղաքի անկումը կոտրեց Տանժերի դիմադրությունը. չորս օր անց՝ օգոստոսի 28-ին, Տանժերը հանձնվեց առանց կռվի։ Այսպիսով Պորտուգալիան Սեուտայից (1415) և Կասր աս-Սղիրից (1458) հետո Մարոկկոյի Ատլանտյան ափին հաստատեց իր երրորդ և չորրորդ դիրքերը. այս արշավանքից հետո թագավորն իր տիտղոսին ավելացրեց «Աֆրիկայի տիրակալ» արտահայտությունը։", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["Սաֆիի անցումը պորտուգալական ազդեցության տակ", "765e703e"], "d": ["Ատլանտյան ափի հացահատիկի և ձկնորսության ամենաբանուկ նավահանգիստ Սաֆին 1488 թ. անցավ պորտուգալական ազդեցության տակ. որոշ ժամանակ քաղաքը կառավարվեց տեղացի իշխանավորների ձեռքով՝ պորտուգալական հովանավորության ներքո, իսկ 1508 թ. ուղղակիորեն գրավվեց։ Քանի որ աղբյուրներն այս երկու փուլին տարբեր կշիռ են տալիս, սկզբի թվականը տատանվում է 1488 և 1508 թվականների միջև. երկուսն էլ նույն ընթացքի ծայրակետերն են։ Սաֆին հիսուներեք տարի մնաց Պորտուգալիայի ձեռքին և դատարկվեց 1541 թ.՝ Ագադիրի անկումից հետո։", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["Santa Cruz do Cabo de Gué-ի հիմնումը. պորտուգալական բերդը Ագադիրում", "cc22c433"], "d": ["Սուսի ափին, մի կետում, ուր մինչ այդ Պորտուգալիան չէր հասել, մասնավոր նախաձեռնությամբ հիմնված Santa Cruz do Cabo de Gué բերդը կառուցվեց 1505 թ. և 1513 թ. փոխանցվեց Պորտուգալիայի թագին։ Վերահսկելով Սուսի հովտի շաքարի և ոսկու առևտուրը՝ բերդը փակում էր Մարաքեշի հարավարևմտյան ելքը. ուստի այն դարձավ Սաադյան շարժման առաջին խոշոր թիրախը։ 1533 թ. պաշարումը ետ մղվեց, իսկ 1541 թ. պաշարումը հաջողության հասավ և սկիզբ դրեց Մարոկկոյում Պորտուգալիայի փլուզմանը։", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["Ազեմմուրի գրավումը. Ումմ ար-Ռաբիի գետաբերանի վերահսկողությունը", "232acd4b"], "d": ["Բրագանսայի դուքս Ժայմեի հրամանատարությամբ պորտուգալական բանակը 1513 թ. սեպտեմբերի 3-ին առանց դիմադրության մտավ Ումմ ար-Ռաբի գետի գետաբերանի մոտ գտնվող Ազեմմուր։ Քաղաքի գրավումը ապահովեց ինչպես գետաբերանի, այնպես էլ դեպի ներքին շրջաններ տանող հացահատիկի ճանապարհի վերահսկողությունը և հաջորդ տարի ճանապարհ բացեց նրանից 12 կմ հարավ-արևմուտք Մազագան բերդի հիմնման համար։ Ազեմմուրը քսանութ տարի մնաց Պորտուգալիայի ձեռքին։", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["Մազագան բերդի հիմնումը. պորտուգալական դիրքը, որ ամենաերկարը կմնա Մարոկկոյում", "786cdb40"], "d": ["Ազեմմուրի գրավման հաջորդ տարի՝ 1514 թ. ամռանը, ափին կառուցվեց Մազագանի ամրոցը։ 1541 թ. ընդհանուր փլուզումից հետո Պորտուգալիան, լքելով Մարոկկոյում իր բոլոր դիրքերը, Մազագանը չլքեց. ընդհակառակը, բերդը հիմքից վերակառուցել տվեց իտալական ոճի բաստիոններով, և քաղաքը պահվեց երկու հարյուր հիսունհինգ տարի։ 1562 թ. մեծ պաշարումն էլ ետ մղվեց։ Մազագանը՝ Մարոկկոյում Պորտուգալիայի վերջին դիրքը, դատարկվելու էր 1769 թ.։", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["Մարդինի բերդի հանձնումը. Դիարբեքիրի հարավում սեֆյան դիմադրության վերջը", "e6226de5"], "d": ["Չալդըրանից հետո Դիարբեքիրի շրջան շարժված Բըյըքլը Մեհմեդ փաշան, երբ պաշարեց Մարդինը, 1515 թ. հոկտեմբերին սեֆյան ուժերը քաշվեցին բերդ. թեև քաղաքն անցավ օսմանյան ձեռքը, բերդը դիմադրեց։ Սեֆյան կուսակալ Կարա խանի՝ համալրումով հակահարձակման անցնելը հանգեցրեց 1516 թ. մայիսի Քոչհիսարի (Կըզըլթեփե) ճակատամարտին. Դեդե Գարքընի դաշտում ամբողջ օրը տևած կռվում Կարա խանին գլխատեցին, և նրա բանակը ցրվեց։ Իսկ բերդը, TDV-ի ձևակերպմամբ, հանձնվեց «միայն ինը ամիս անց»։", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["Պորտուգալիան գրավեց Բահրեյնը. Ջաբրիների տիրապետության վերջը", "315a435a"], "d": ["Երբ Ջաբրի տիրակալ Մուկրին իբն Զամիլը հրաժարվեց հարկ վճարել Որմուզին, պորտուգալական նավատորմը և Պորտուգալիային ենթակա Որմուզի թագավորության ուժերը ափ իջան կղզում. Մուկրինը պարտվեց կռվում, և 1521 թ. Բահրեյնն անցավ պորտուգալական կառավարման տակ։ Այնուհետ ութսուն տարի կղզին կառավարվեց Որմուզի միջոցով, հիմնականում սուննի իրանցի կուսակալների ձեռքով։ Բահրեյնի մարգարիտն ու ռազմավարական դիրքը կղզին դարձնելու էին Պարսից ծոցում օսմանա-պորտուգալական մրցակցության ուղղակի թիրախ։", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["Ագադիրի անկումը. սկսվում է Սաադյանների կողմից Պորտուգալիայի արտամղումը Մարոկկոյից", "bb1568f6"], "d": ["Սաադյան սուլթան Մուհամմեդ աշ-Շեյխը 1541 թ. փետրվարի 16-ին պաշարեց Սանտա Կրուզ բերդը և մարտի 12-ին գրավեց այն. գերի ընկան մոտ վեց հարյուր պորտուգալացի, այդ թվում կուսակալ Գուտերե դե Մոնրոյը։", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["Սաֆիի և Ազեմմուրի դատարկումը. Պորտուգալիան նահանջում է Ատլանտյան ափից", "4cb6099a"], "d": ["1541 թ. մարտի 12-ին Ագադիրի անկման և Մարոկկոյի սուլթանի հետ հուսացած դաշինքը չկայանալու պատճառով Ժուան III-ը հրամայեց դատարկել Ատլանտյան ափի երկու խոշոր դիրքերը. Սաֆիի և Ազեմմուրի տարհանումն ավարտվեց 1541 թ. աշնանը՝ սեպտեմբեր-հոկտեմբեր ամիսներին։ Այսպիսով մեկ տարվա ընթացքում ձեռքից գնաց երեք դիրք, և Մարոկկոյի ափին Պորտուգալիայի հիսնամյա ընդարձակումը շրջվեց հակառակ ուղղությամբ. մնացին Սեուտան, Տանժերը, Արզիլան, Կասր աս-Սղիրը և նոր ամրացված Մազագանը։", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["Արզիլայի դատարկումը. Պորտուգալիան նեղացնում է իր ներկայությունը հյուսիսային ափին", "b5d18373"], "d": ["Ֆինանսական ճգնաժամի և Սաադյանների ճնշման միաժամանակյա ազդեցությամբ Ժուան III-ը դատարկեց 1471 թվականից պահվող Արզիլան։ Այսպիսով Մարոկկոյում Պորտուգալիայի ներկայությունը սահմանափակվեց Սեուտայով, Տանժերով և Մազագանով։ 1577 թ. Արզիլան կարճ ժամանակով կրկին գրավվելու էր, իսկ 1589 թ. վերջնականապես լքվելու էր։", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["Օսմանյան արշավանքը Բահրեյնի դեմ. վերջին խոշոր քայլը Պորտուգալիայի դեմ Պարսից ծոցում", "14501df3"], "d": ["1546 թ. Բասրայի բռնակցմամբ և Լահսայի էյալեթի հիմնմամբ Պարսից ծոցի արաբական ափին հաստատված Օսմանյան պետությունը, թիրախ ունենալով կղզու մարգարտի առևտուրն ու Պորտուգալիայի Որմուզի գիծը, Լահսայի բեյլերբեյ Մուստաֆա փաշայի հրամանատարությամբ շարժվեց Բահրեյնի վրա։ Արշավանքի ելքի հարցում աղբյուրները տարամիտվում են. TDV İslâm Ansiklopedisi-ն գրում է, որ օսմանցիները «1559 թ. գրավեցին Բահրեյնը և այնտեղ հենակետ» հիմնեցին, իսկ կղզիները «հետագայում կրկին անցան պորտուգալացիների կառավարման տակ». արևմտյան գրականությունն էլ արձանագրում է, որ պաշարումը ձախողվեց, Որմուզից ծովով հասած պորտուգալական համալրումը ետ մղեց օսմանյան ուժերին, և երկու կողմերին էլ խոցած ժանտախտի համաճարակից հետո օսմանցիները խնդրեցին հանձնման պայմաններ։ Երկու պատումները տարբերվում են հենց ելքի հարցում. ընդհանուրն այն է, որ Բահրեյնը կայուն կերպով օսմանյան ձեռքում չմնաց։", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["Ուլուջ Ալի փաշան վերցրեց Թունիսը. Հաֆսյան-իսպանական կարգի վերջը", "d4498698"], "d": ["Երբ 1535 թ. Կարլոս V-ը գրավեց Թունիսը, նա քաղաքն ինքը չկառավարեց, այլ Հաֆսյան սուլթան Մևլայ Հասանին կրկին նստեցրեց գահին. TDV-ի ձևակերպմամբ՝ Թունիս քաղաքը «մինչև 1569 թ. օսմանցիների երկրորդ միջամտությունը» մնաց «իսպանացիների հովանավորության ներքո և Մևլայ Ահմեդ III-ի կառավարման տակ»։ 1568 թ. հունիսի 27-ին Ալժիրի բեյլերբեյ նշանակված Ուլուջ Ալին ցամաքով շարժվեց Թունիսի վրա, Բեջայում հաղթեց Հաֆսյան սուլթանին և մտավ քաղաք. Մևլայ Ահմեդն ապաստանեց իսպանական Գուլետ (Հալկ ալ-Վադի) պրեսիդիոյում։ Այսպիսով ծովածոցը բաժանվեց երկու մասի՝ քաղաքը օսմանյան, նավահանգստի բերդը՝ իսպանական, և այս բաժանումը տևեց չորս տարի։", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["Դոն Խուան Ավստրիացին վերագրավեց Թունիսը. Լեպանտոյի միակ արձագանքը ցամաքում", "a6f044ee"], "d": ["Թեև Լեպանտոյից (1571) հետո Սրբազան դաշինքը քայքայվել էր, Իսպանիան միայնակ ճնշում գործադրեց Հյուսիսային Աֆրիկայի վրա. TDV-ի ձևակերպմամբ՝ «1573 թ. հոկտեմբերի 10-ին իսպանացիները Թունիսում վերահսկողություն հաստատելու նպատակով նոր գործողություն ձեռնարկեցին։ Գրավեցին Թունիսը և այնտեղ թողեցին 8000 զինվոր»։ Դոն Խուան Ավստրիացու հրամանատարությամբ այս գործողությունը միակ տեղն է, որտեղ Լեպանտոյի հաղթանակը արձագանք գտավ ցամաքում. սակայն այն կայուն չեղավ, և տասնմեկ ամիս անց քաղաքը հետ առնվեց։ Գրավման տապալածը արդեն հաստատված օսմանյան կառավարումն էր. հիջ. 980 թ. Զու-լ-հիջջա ամսի 2-ին (1573 թ. ապրիլի 5) Թունիսի հրամանատարը Քըլըչ Ալի փաշան էր, կայմակամը՝ Ռամազան փաշան, բեյլերբեյը՝ Հայդար փաշան։", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["Սեֆյանները Բահրեյնը վերցրին Պորտուգալիայից", "c37d982c"], "d": ["Շահ Աբբաս I-ի ուղարկած ուժերը, միանալով կղզու ապստամբներին, պորտուգալական կայազորին դուրս մղեցին բերդից. TDV-ի ձևակերպմամբ՝ կղզիները «1602 թ. Իրանին կապված ուժերի կողմից» խլվեցին պորտուգալացիներից։ Այսպիսով Բահրեյնը, դուրս գալով ութսունմեկամյա պորտուգալական կառավարումից, անցավ սեֆյան տիրապետության տակ և հարյուր տասնհինգ տարի մնաց Իրանին կապված։ Սա Պարսից ծոցում Պորտուգալիայի քայքայման առաջին օղակն է. քսան տարի անց հենց Որմուզն էլ ընկնելու էր անգլո-իրանական համատեղ գործողությամբ։", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["Օմանցիների ներխուժումը Բահրեյն. սեֆյան տիրապետության վերջը", "c9be5820"], "d": ["Սեֆյան պետության վերջին տարիների քայքայման ժամանակ Յաարուբի հարստության կառավարած Օմանի նավատորմը ներխուժեց կղզի, և սեֆյան տիրապետությունն ավարտվեց։ Դրան հաջորդած երեսունհինգ տարին Պարսից ծոցի ամենախառնակ շրջանն է. կղզին մի քանի անգամ ձեռքից ձեռք անցավ Օմանի, Իրանի և տեղական արաբական ուժերի միջև։", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["Բահրեյնն անցավ Բուշեհրի Ալ Մազքուրների կառավարման տակ", "610e2f9d"], "d": ["Ծագումով Օմանից եկած, Բուշեհրում հաստատված և հուվալա համարվող Ալ Մազքուր ընտանիքը 1753 թ., գործելով Բուշեհրի իր հենակետից, Բահրեյնը վերցրեց իր կառավարման տակ։ Ընտանիքն առաջնորդում էր Իրանի ծոցափնյա արաբական համայնքներին և կղզին կառավարում էր Իրանի անունից. նրա վերջին ներկայացուցիչ Նասր Ալ Մազքուրը Բահրեյնի կուսակալ էր նշանակվել Զենդերի վարչակարգի կողմից։ Սա կղզու վերջին վարչակարգն է Ալ Խալիֆաներից առաջ։", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["Մազագանի դատարկումը. ընկավ Պորտուգալիայի վերջին դիրքը Մարոկկոյում", "f9e9749d"], "d": ["Ալավյան սուլթան Մուհամմեդ III իբն Աբդալլահի 1769 թ. սկզբին սկսած պաշարման դեմ 592 հոգանոց կայազորը չկարողացավ դիմանալ. փետրվարի 1-ին Լիսաբոնից դուրս եկած տարհանման նավատորմը 1769 թ. մարտի 11-ին նավ բարձրացրեց վերջին զինվորներին, իսկ քաղաքը վերջինը լքեց կուսակալ Դինիշ Գրեգորիոն։ Այսպիսով 1415 թ. Սեուտայի գրավմամբ սկսված Պորտուգալիայի ներկայությունը Մարոկկոյում ավարտվեց երեքուկես դար անց։ Մազագանը 1541 թ. ընդհանուր փլուզումից հետո պահված միակ դիրքն էր Ատլանտյան ափին և իր երկու հարյուր հիսունհինգ տարով դարձավ Մարոկկոյում Պորտուգալիայի ամենաերկար պահած վայրը։", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["Ալ Խալիֆաների կողմից Բահրեյնի գրավումը. մինչ այսօր տևող հարստության հիմնադրումը", "8773b011"], "d": ["Զենդերի վարչակարգի Բահրեյնի կուսակալ Նասր Ալ Մազքուրը պաշարեց Կատարի թերակղզու Զուբարան. Ահմեդ իբն Մուհամմեդ իբն Խալիֆայի հրամանատարությամբ ութուբյան ուժերը ճեղքեցին պաշարումը և, անցնելով հակահարձակման, նույն տարում գրավեցին Բահրեյնը։ TDV-ի գրառումը կարճ է. «Բահրեյնը 1783 թ. անցավ Ութուբ ցեղախմբի Ալ Խալիֆաների տիրապետության տակ»։ Այս հաղթանակից հետո Ահմեդ իբն Մուհամմեդը կոչվեց «ալ-Ֆաթիհ» մականունով, և նրա հիմնած հարստությունը կղզում իշխում է մինչ այսօր։", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["Բահրեյնի պայմանագիրը Անգլիայի հետ. մուտք Պարսից ծոցի պրոտեկտորատային կարգ", "576796b2"], "d": ["TDV-ի գրառման համաձայն՝ «1861 թ. մայիսի 21-ին Անգլիան և Բահրեյնը ներկայացնող շեյխ Մուհամմեդի եղբայր Ալին ստորագրեցին համաձայնագիր, որով տարածաշրջանում արգելվում էին ստրկավաճառությունն ու ծովահենությունը». անգլիական փաստաթղթերում նույն պայմանագիրը (Perpetual Truce of Friendship and Peace) կրում է 1861 թ. մայիսի 31 թվականը։ Պայմանագիրը Բահրեյնի արտաքին հարաբերությունները Անգլիային կապող պրոտեկտորատային կարգի առաջին օղակն է, և 1871 թ. Լահսայում ու Կատիֆում օսմանցիների վերահաստատումից հետո էլ կղզին մնաց այդ կարգից դուրս։", "ab2ad5ff"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["Ահի Էվրան. ահիական կազմակերպության հիմնադիր փիրը", "3392e100"], "d": ["Ահի Էվրանը համարվում է Անատոլիայում ահիական կազմակերպության հիմնադիրներից մեկը և կաշեգործների (դաբբաղների) փիրը։ Նրա Կըրշեհիրի զավիեն օսմանյան շրջանում մինչև 20-րդ դարի սկիզբը մնաց որպես արհեստավորների/համքարությունների կազմակերպության հոգևոր կենտրոն. պետությունն այս դիրքը պաշտոնապես հաստատել է 1780, 1782, 1822-23 և 1842 թվականներին։", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["Շեյխ Էդեբալի. ահիականության և Օսմանյան հարստության հիմնադիր կապը", "c1186059"], "d": ["Բիլեջիքում զավիե հիմնած և ահիական կազմակերպության շեյխերից մեկի դիրքը զբաղեցնող Էդեբալին, ըստ ավանդության, մեկնաբանեց Օսման Ղազիի հռչակավոր երազը. այնուհետև Օսման Ղազին ամուսնացավ Էդեբալիի դստեր՝ Մալհուն խաթունի հետ։ Էդեբալին միաժամանակ համարվում է օսմանյան առաջին կադին և մուֆթին։", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["Բուրսայի գրավումից հետո Օրհան Ղազին վաքֆ դարձրեց ջիրիդ խաղերի դաշտը", "da1becbd"], "d": ["TDV-ի «Ջիրիդ» հոդվածի համաձայն՝ Օրհան Ղազին Բուրսայի գրավումից հետո մերձակայքի մի տարածք վաքֆ դարձրեց ձիարշավների և ջիրիդ խաղերի համար. դա Օսմանյան պետությունում ջիրիդ խաղի հաստատութենականացման առաջին արձանագրված օրինակներից մեկն է։", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["Քըրքփընարի ըմբշամարտի ավանդական սկիզբը", "2d93fa65"], "d": ["Ավանդության համաձայն՝ Քըրքփընարի ըմբշամարտի ավանդույթը սկսվել է Ռումելիի նվաճող Սուլեյման փաշայի հետ անցած քառասուն ղազիների միջև կայացած ըմբշամարտի մրցումներով։ TDV-ի «Ըմբշամարտ» և «Քըրքփընար» հոդվածները փոխանցում են այս ավանդությունը, բայց ստույգ հիմնադրման թվական չեն տալիս։", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["Ենիչերիների օջախի հիմնումը", "f4206dce"], "d": ["Չանդարլը Կարա Հալիլի և Մոլլա Ռյուստեմի ուղղորդմամբ, փենջիկի օրենքի համաձայն ռազմագերիներից վերցրած ոչ մուսուլման երիտասարդների վարժեցմամբ սկսված համակարգը Գելիբոլուում հիմնված Աջեմի օջախի միջոցով Մուրադ I-ի օրոք ձեռք բերեց հաստատութենական կերպարանք։", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["Էդիրնեի Հին մզկիթի (Ուլու Ջամի) շինարարության սկիզբը", "da7a22ac"], "d": ["Ժողովրդի մեջ նաև Ուլու Ջամի (Ջամի-ի Աթիկ) անունով հայտնի Էսկի Ջամիի կառուցումը սկսեց Էմիր Սուլեյման Չելեբին 1402-1403 թվականներին։", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["Բուրսայի Կանաչ մզկիթի համալիրի շինարարության սկիզբը", "280b8a21"], "d": ["Ֆեթրեթի դարաշրջանից հետո գահը կրկին միավորած Մեհմեդ I-ը համալիրի շինարարությունը սկսեց 1414 թ. և այն տեղադրեց Բուրսայի կենտրոնական մի կետում՝ այնպես, որ տարբերվի իր պապի և հոր համալիրներից։ Գլխավոր ճարտարապետը Հաջի Իվազ փաշան է։", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["Բուրսայի Կանաչ մզկիթի համալիրի ավարտը", "bc82821f"], "d": ["Կանաչ մզկիթի համալիրը, որը հայտնի է իր հախճասալիկների և զարդարանքի ծրագրով, որին նպաստել են նաև թավրիզցի վարպետները, ավարտվեց 1419 թ. դեկտեմբերին։ Համալիրը բաղկացած է մզկիթից, դամբարանից (Կանաչ թյուրբե), մեդրեսեից, իմարեթից և բաղնիքից. այն վաղ օսմանյան ճարտարապետության ամենահարուստ օրինակներից մեկն է։", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["Դևշիրմեի համակարգի փաստացի կիրառման սկիզբը", "fa835172"], "d": ["Նախորդ իսլամական պետություններում չհանդիպող դևշիրմեի կարգը նախ սկսվեց փենջիկի օրենքի համաձայն ոչ մուսուլման ռազմագերի երիտասարդներին օգտագործելու ձևով։ Ըստ TDV-ի՝ «հասկացվում է, որ այն կիրառվել է Չելեբի Մեհմեդի ժամանակ, բայց օրենքի ուժ է ստացել նրա որդի Մուրադ II-ի օրոք»։", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["Շեյխուլիսլամի պաշտոնի սահմանումը. Մոլլա Ֆենարիի Բուրսայի մուֆթիությունը", "2a8ee2b9"], "d": ["Երկար տարիներ Բուրսայի կադի եղած ուլեմա Մոլլա Ֆենարիի նշանակումը 1425 թ. Բուրսայի մուֆթի, TDV-ի ձևակերպմամբ, համարվում է «օսմանցիների մոտ մուֆթիության և շեյխուլիսլամության սկիզբը»։ Սակայն TDV-ն նշում է, որ դա նույնը չէ, ինչ 16-րդ դարում ամբողջ իլմիյեի կազմակերպությունը ներկայացնող լիովին հաստատութենականացված շեյխուլիսլամի պաշտոնը։", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["Թիմարային համակարգի հաստատութենականացումը", "dc267780"], "d": ["Փաստաթղթերի վրա հիմնված թիմարի առաջին հիշատակումները հասնում են Օրհան բեյի շրջան. համակարգված օրենսգրումը, սակայն, տեղի ունեցավ Մուրադ II-ի օրոք։ Այս շրջանում կազմված թիմարի իջմալ դեֆթերները ցույց են տալիս, որ ձևավորվել են համակարգի բոլոր հիմնական սկզբունքները. մոտ 1432 թ. փաստաթղթերն ապացուցում են, որ օրենքները լիովին ուժի մեջ էին։", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["Երեք պատշգամբով մզկիթի և համալիրի ավարտը", "cde6993e"], "d": ["Մուրադ II-ի կողմից Մուսլիհուդդին և Շեհաբեդդին անունով վարպետներին տասնամյա ժամկետում (1437-1447) կառուցել տրված Երեք պատշգամբով (Ուչ Շերեֆելի) մզկիթը համարվում է օսմանյան ճարտարապետության մեջ կենտրոնական հատակագծով մզկիթների առաջին օրինակը և դասական շրջանին նախորդող անցումային ճարտարապետության շրջադարձային կետերից մեկը։", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["Դիվան-ը Հումայունի հաստատութենականացումը Ֆաթիհի օրենքով", "e8443e77"], "d": ["Դիվանը Մուրադ II-ի օրոք Էդիրնեում կանոնավոր կարգերի ենթարկվելով սկսեց ձեռք բերել «Դիվան-ը Հումայուն»-ի կերպարանք։ Բուն վերափոխումը եկավ Ֆաթիհ սուլթան Մեհմեդի օրենքով. ամենամեծ նորամուծությունն այն էր, որ փադիշահի՝ դիվանի նախագահությունը լիովին վերացվեց և փոխանցվեց մեծ վեզիրին։", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["Ֆաթիհ սուլթան Մեհմեդը Օքմեյդանին հատկացրեց նետաձիգներին", "342a9fd5"], "d": ["Կոստանդնուպոլսի գրավման ժամանակ իր ճամբարը Կասըմփաշայի լանջերին հիմնած Ֆաթիհ սուլթան Մեհմեդը այդ վայրը միաժամանակ օգտագործել էր որպես նետաձիգների վարժադաշտ. քաղաքը վերցնելուց հետո նա տարածքը մշտապես հատկացրեց նետաձիգներին։ Այս հատկացումը սկիզբն է նրա, որ Օքմեյդանին դարեր տևելիք օսմանյան նետաձգության ավանդույթի կենտրոնը դարձավ։", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["Բուրսան հասավ իրանական մետաքսի առևտրի գագաթնակետին", "f1324cdf"], "d": ["Թավրիզից եկող քարավանները Գիլանի, Աստարաբադի և Սարիի մետաքսները տանում էին Բուրսա, որտեղ դրանք մրցակցելով գնում էին ջենովացի, վենետիկցի, ֆլորենցիացի և հրեա վաճառականները։ 1479 թ. Իրանից ներմուծված մետաքսի արժեքը հասավ 150.000 վենետիկյան ոսկու. 1502 թ. քաղաքում գործում էր ավելի քան 1000 ջուլհակահաստոց։", "0f47c417"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["Բայազիդ II-ը մեծ պարգև տվեց Քըրքփընարի ըմբիշներին", "d745b882"], "d": ["TDV-ի «Ըմբշամարտ» հոդվածի համաձայն՝ Բայազիդ II-ը 1504 թ. ըմբիշներին տվել է 3.000 և 1.500 ղուրուշի պարգևներ. դա օսմանյան արքունիքի՝ ըմբշամարտին ցուցաբերած հովանավորության՝ գրավոր արձանագրված վաղ օրինակներից մեկն է։", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["Բայազըթի մզկիթի և համալիրի ավարտը", "eb9ab65b"], "d": ["Բայազիդ II-ի համար կառուցված Բայազըթի մզկիթի և համալիրի շինարարությունը, ըստ արխիվային մի փաստաթղթի, սկսվել է հիջ. 906 թ. (1500) և ավարտվել հիջ. 911 թ. Ջումադա ալ-ուլա ամսի 14-ին (1505 թ. հոկտեմբերի 13)։ Ճարտարապետի հարցը վիճելի է. Այվանսարայիի գրառման հիման վրա երկար ժամանակ այն համարվել է ճարտարապետ Հայրեդդինի գործը, ապա վերագրվել է ճարտարապետ Քեմալեդդինին, ոմանց կարծիքով՝ երկուսն աշխատել են միասին. մինչդեռ նույն փաստաթուղթը ցույց է տալիս, որ վարպետը Յաքուբ Շահ իբն Սուլթան Շահն էր։ Մզկիթը համարվում է օսմանյան ճարտարապետության՝ նախադասականից դասական շրջան անցման կարևոր հուշարձաններից։", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["Կայսերական նավաշինարանի (Tersâne-i Âmire) տեղափոխումը Ստամբուլ (Կասըմփաշա/Ոսկե Եղջյուր)", "f36e3675"], "d": ["Յավուզ Սուլթան Սելիմի օրոք Ղալաթիայի պարիսպներից արևմուտք գտնվող ծովախորշում սկսված նոր նավաշինարանը 1515 թ. ավարտվեց 160 նավախորշով. այսպիսով Գելիբոլուի կենտրոնով նավաշինական գործունեությունը տեղափոխվեց Ստամբուլ։ Ավելի ուշ՝ Բարբարոս Հայրեդդին փաշայի օրոք, հաստատությունը պաշտոնապես ստացավ «Tersâne-i Âmire» անունը։", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["Շեյխ Համդուլլահի մահը և նրա գեղագրական դպրոցի ժառանգությունը", "f5ed4d09"], "d": ["Ամասիացի Շեյխ Համդուլլահը, լինելով Բայազիդ II-ի գեղագրության ուսուցիչը, աքլամ-ի սիթթե (գրի վեց տեսակ) դպրոցը հասցրեց հասունության և դարձավ ամբողջ իսլամական աշխարհում գերիշխելիք օսմանյան գեղագրական ոճի հիմնադիրը։ 1520 թ. մահանալիս նա իր հետևից թողեց աշակերտների լայն շրջանակ։", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["Փիրի ռեիսն ավարտեց Քիթաբ-ի Բահրիյեի առաջին տարբերակը", "fd6cc1ff"], "d": ["Միջերկրական ծովի ափերի, նավահանգիստների և նավագնացության տեղեկությունները ի մի բերող Քիթաբ-ի Բահրիյեի առաջին (արձակ) տարբերակը Փիրի ռեիսն ավարտեց 1521 թ.։ Այս առաջին տարբերակը դեռ փադիշահին չէր ներկայացվել և սևագիր էր, որ հետագա տարիներին ընդլայնվելու էր։", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["Փիրի ռեիսն ընդլայնեց Քիթաբ-ի Բահրիյեն և մատուցեց սուլթան Սուլեյման Կանունիին", "d4abf0b7"], "d": ["Փիրի ռեիսը, Քիթաբ-ի Բահրիյեն ընդլայնելով մասամբ չափածո ձևով, 1526 թ. այն մատուցեց սուլթան Սուլեյման Կանունիին։ Այս տեսքով գիրքը տարածվեց որպես օսմանյան ծովագնացության ամենաընդգրկուն նավարկության ուղեցույց։", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["Մատրաքչի Նասուհը «Բեյան-ի Մենազիլում» պատկերեց Իրաքեյնի արշավանքի երթուղին", "aa012278"], "d": ["Սուլթան Սուլեյման Կանունիի 1534 թ. ձեռնարկած իրանական առաջին (Իրաքեյնի) արշավանքին մասնակցած Մատրաքչի Նասուհը մանրանկարչական-քարտեզագրական տեխնիկայով պատկերեց բանակի՝ Ստամբուլից Թավրիզ, այնտեղից էլ Բաղդադ ձգվող երթուղու յուրաքանչյուր իջևանավայր։ Այս աշխատանքը ամփոփվեց «Beyân-ı Menâzil-i Sefer-i Irâkeyn» անունով երկում և օսմանյան մենզիլնամե (կայանների նկարագրություն) ժանրի ամենաինքնատիպ օրինակն է։", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["Բաղդադի գրավումից հետո Ֆուզուլին կասիդե մատուցեց Կանունիին", "1ef0653f"], "d": ["1534 թ. սուլթան Սուլեյման Կանունիի Բաղդադը գրավելուց հետո Ֆուզուլին օսմանյան սուլթանին մատուցեց հինգ կասիդե, այդ թվում «Geldi burc-ı evliyâya pâdişâh-ı nâmdâr» տողով սկսվող հայտնի կասիդեն. այսպիսով, դուրս գալով սեֆյան հովանավորությունից, նա որոնեց օսմանյան պետական այրերի հովանավորությունը։", "b8e9e300"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["Ֆուզուլիի «Լեյլի և Մեջնուն» մեսնևիի ավարտը", "e3ef4085"], "d": ["Դասական թուրքական գրականության ամենագեղեցիկ մեսնևիներից համարվող «Լեյլի և Մեջնուն»-ը Ֆուզուլին գրեց և ավարտեց 1535 թ.՝ Կանունիի Բաղդադի արշավանքին մասնակցած ստամբուլցի բանաստեղծների խնդրանքով։", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["Ճարտարապետ Սինանի նշանակումը պալատական գլխավոր ճարտարապետ", "7a753f0e"], "d": ["TDV İslâm Ansiklopedisi-ի «Սինան» հոդվածի համաձայն՝ 1537 թ. պալատական գլխավոր ճարտարապետ Աջեմ Ալիսիի մահից հետո Մոլդովայի արշավանքին Պրուտ գետի վրա կառուցած կամրջով ուշադրություն գրաված Սինանը մեծ վեզիր Լութֆի փաշայի գնահատանքով նշանակվեց այդ պաշտոնին։ Այսպես սկսվեց Սինանի ավելի քան հիսուն տարի տևելիք գլխավոր ճարտարապետության շրջանը։", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["Շահզադե մզկիթի և համալիրի շինարարության սկիզբը", "1a70ddfd"], "d": ["Սուլթան Սուլեյման Կանունին հրամայեց կառուցել համալիր 1543 թ. ժանտախտի համաճարակին կորցրած որդու՝ շահզադե Մեհմեդի անունով. շինարարությունը սկսվեց 1543 թ. հունիսին, նախ ավարտվեց դամբարանը, ապա ձեռնամուխ եղան մզկիթի կառուցմանը։ Ճարտարապետ Սինանի իսկ խոսքով՝ այս կառույցը «իմ աշակերտական գործն է»։", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["Ուսկյուդարի Իսկելեի (Միհրիմահ սուլթան) համալիրի ավարտը", "3769007f"], "d": ["Ուսկյուդարի Իսկելե հրապարակի համալիրի շինարարությունը սկսվեց 1540-ականների առաջին տարիներին և ավարտվեց 1547 թ.։ Միհրիմահ սուլթանի՝ ճարտարապետ Սինանին կառուցել տված երկու մեծ մզկիթներից այն ժամանակագրորեն առաջինն է. երկրորդը (Էդիրնեքափը) ավարտվելու էր մոտ քսան տարի անց։", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["Վենետիկը հյուպատոսություն բացեց Հալեպում", "3aad8b9e"], "d": ["16-րդ դարում եվրոպացիների առևտրական ծանրության կենտրոնը Դամասկոսից տեղափոխվեց Հալեպ։ Որպես այս փոփոխության շոշափելի ցուցիչ՝ Վենետիկը 1548 թ. հյուպատոսություն բացեց Հալեպում. նրան հետևեցին Ֆրանսիան 1557 թ. և Անգլիան 1586 թ.։ Քաղաքը դարձավ հիմնական շուկան, որտեղ փոխանակվում էին եվրոպական բրդե կտորներն ու արծաթը հնդկական համեմունքների, իսկ դարավերջին՝ իրանական մետաքսի հետ։", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["Շահզադե մզկիթի բացումը աղոթքի համար", "2bb3f4b2"], "d": ["Մոտ հինգ տարի տևած շինարարությունից հետո Շահզադե մզկիթը 1548 թ. օգոստոսին բացվեց աղոթքի համար։ Զույգ մինարեթով և կենտրոնագմբեթ հատակագծով այն համարվում է ճարտարապետ Սինանի հետագա մեծ գործերի կանխանշանը. համալիրը բաղկացած է մզկիթից, դամբարանից, մեդրեսեից, իմարեթից, թաբհանեից (հյուրատուն) և քարավանատնից։", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["Քըրքչեշմեի ջրատարի գծի շինարարության սկիզբը", "14124b59"], "d": ["Ճարտարապետ Սինանը Կանունիի հրամանով ուսումնասիրեց Բելգրադի անտառներից Ստամբուլ ջուր բերելու հարցը և հայտնեց, որ դա հնարավոր է. խոշոր ջրային կառույցի շինարարությունը սկսվեց 1554 թ. և ավարտվեց մինչև 1563 թ.։ TDV-ն այս կառույցը բնութագրում է որպես Սինանի «ինժեներական տեսանկյունից ամենակարևոր, ծավալով էլ ամենամեծ գործը»։", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["Ստամբուլում առաջին սրճարանների բացումը", "85c12f9f"], "d": ["Սուրճի մուտքը օսմանյան քաղաքային կյանք սկսվեց Թահթաքալեում հալեպցի վաճառական Հաքեմի և Շեմս անունով դամասկոսցի մի անձի բացած սրճարաններով։ Կարճ ժամանակում ծնվեց նոր հանրային տարածք, ուր հավաքվում էին հասարակության բոլոր խավերի մարդիկ. Կանունիի օրոք վերջին շրջանում Ստամբուլում կար հիսուն սրճարան։", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["Էբուսսուուդ էֆենդին իրավական քննության ենթարկեց գեդիքի (արհեստավորական մենաշնորհի իրավունքի) հարցը", "5d4e2930"], "d": ["Արհեստների մեջ որոշակի թվով անձանց տրվող մենաշնորհի և արտոնության իրավունքի՝ «գեդիքի» հարցը Կանունիի օրոք կրկին օրակարգ եկավ. շեյխուլիսլամ Էբուսսուուդ էֆենդին 1555-56 թվականներին խորությամբ ուսումնասիրեց հարցը և փադիշահին ներկայացրեց կիրառության օրինականությունը։", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["Սեյդի Ալի ռեիսն Ստամբուլում ավարտեց «Միրաթ ալ-մամալիքը»", "ee8640e1"], "d": ["Բաղդադից սկսած՝ վերադարձի ճամփորդության ողջ ընթացքում գրած «Միրաթ ալ-մամալիք» ուղեգրական երկը Սեյդի Ալի ռեիսն ավարտեց 1557 թ. հունվարին Ստամբուլում։ Երկը առաջին ձեռքի աղբյուր է, որը պատմում է օսմանյան ծովագնացի՝ Հնդկական օվկիանոսից Կենտրոնական Ասիայի վրայով ցամաքով հայրենիք վերադարձը։", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["Ռյուստեմ փաշայի համալիրի (մզկիթի) կառուցումը", "02e30725"], "d": ["Կանունիի փեսա և մեծ վեզիր Ռյուստեմ փաշայի՝ ճարտարապետ Սինանին կառուցել տված համալիրը կառուցվել է 1555-1561 թվականներին։ Կառույցը հայտնի է իր ինքնատիպ ճարտարապետությամբ՝ ներքևում կամարակապ խանութներով բարձրացված հարթակի վրա, և հարուստ իզնիկյան հախճասալիկներով։", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["Մոստարի կամրջի ավարտը", "e7f434af"], "d": ["Ներետվա գետի վրայի հռչակավոր Մոստարի կամուրջը մոտ 1566-67 թվականներին կառուցել է ճարտարապետ Հայրեդդինը. 1568 թ. պաշտոնական փաստաթղթում կամրջի հիշատակումը հաստատում է, որ այն արդեն ավարտված էր։ Կառույցը մեկ թռիչքով սրածայր կամարով դասական օսմանյան կամրջաշինական ճարտարապետության ամենահայտնի օրինակներից մեկն է։", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["Էդիրնեքափըի (Միհրիմահ սուլթան) մզկիթի ավարտը", "f2d21a82"], "d": ["Կանունիի դուստր Միհրիմահ սուլթանի համար 1563 թ. հաստատված շինթույլտվությունից հետո սկսված մզկիթի շինարարությունն ավարտվեց 1566 թ.. համալիրի վաքֆնամեն կազմվեց 1570-71 թվականներին։ Կառույցը Ստամբուլի պարիսպներին ամենամոտ ճարտարապետ Սինանի մեծ գործերից մեկն է։", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["Բաքին եղերերգ գրեց սուլթան Սուլեյման Կանունիի համար", "7aa6665f"], "d": ["Երբ Սիգեթվարից հասավ սուլթան Սուլեյման Կանունիի մահվան լուրը, ժամանակի «sultânü'ş-şuarâ» (բանաստեղծների սուլթան) Բաքին գրեց օսմանյան գրականության ամենահռչակավոր եղերերգերից մեկը։", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["Բաքիի ջուլուսիեն Սելիմ II-ին", "6027f034"], "d": ["Սելիմ II-ի գահ բարձրանալուց անմիջապես հետո Բաքին նոր փադիշահին մատուցեց «ջուլուսիե» (գահակալման բանաստեղծություն)՝ ըստ TDV-ի՝ Կանունիի մահվան առիթով գրած եղերերգից անմիջապես հետո։", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["Բյույուքչեքմեջեի կամրջի ավարտը", "5f49b3c5"], "d": ["Սուլթան Սուլեյման Կանունիի հրամանով սկսված կամուրջը, Սիգեթվարի արշավանքի ժամանակ փադիշահի մահվան պատճառով, ավարտել տվեց նրա որդի Սելիմ II-ը 1567-68 թվականներին։ Ճարտարապետ Սինանը Բյույուքչեքմեջեի լճի՝ ծով թափվելու կետում կառուցած կամրջի՝ հեղեղից վնասված հատվածները նույնպես ինքը վերանորոգեց։", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["Սելիմիյե մզկիթի (Էդիրնե) շինարարության սկիզբը", "07e18c9e"], "d": ["Սելիմիյեի շինարարությունը, որը ճարտարապետ Սինանն անվանել է «իմ վարպետության գործը», Սելիմ II-ի անունով սկսվեց 1568 թ., տևեց վեց տարի և ավարտվեց 1574 թ. (ավարտը ժամանակագրության մեջ արդեն արձանագրված է)։ Արաստայի արևմտյան խանութներն ու մանկական դպրոցը, սակայն, Սելիմ II-ի մահից հետո Մուրադ III-ի օրոք ավարտել է Դավուդ աղան։", "a3d4551b"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["Քընալըզադե Ալի Չելեբիի մահը՝ օսմանյան բարոյական փիլիսոփայության դասական «Ախլաք-ի Ալայի» երկի հեղինակը", "dd921873"], "d": ["Օսմանյան բարոյական փիլիսոփայության ամենահայտնի դասական «Ախլաք-ի Ալայի» երկի հեղինակ Քընալըզադե Ալի Չելեբին մահացավ 1572 թ. հունվարի 22-ին, երբ Անատոլիայի ղազասքեր էր։ Նրա երկի՝ ավելի քան յոթանասուն ձեռագիր օրինակ կա Ստամբուլի գրադարաններում։", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["Փիյալե փաշայի համալիրի կառուցումը", "75411278"], "d": ["Սելիմ II-ի փեսաներից կապուդան փաշա Փիյալե փաշան 1573 թ. գնեց համալիրի հողամասը և այն կառուցել տվեց ճարտարապետ Սինանին։ Համալիրը նախագծվեց որպես մզկիթից, մեդրեսեից, թեքքեից, դամբարանից, գերեզմանոցից, մանկական դպրոցից, աղբյուրից, շուկայից և բաղնիքից կազմված ընդարձակ համակարգ։", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["Դրինայի (Սոքոլլու Մեհմեդ փաշայի) կամրջի ավարտը", "1d668c73"], "d": ["Մեծ վեզիր Սոքոլլու Մեհմեդ փաշայի հովանավորությամբ ճարտարապետ Սինանի կառուցած կամուրջը, ըստ արձանագրության թվականի, ավարտվել է 1577-78 թվականներին. որոշ հետազոտողներ առաջ են քաշում, որ շինարարությունը սկսվել է 1571-72 թվականներին։ Կամուրջը Սոքոլլուի՝ իր ծննդավայր Վիշեգրադի հանդեպ կապվածության խորհրդանիշն է։", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["Ազապքափըի (Սոքոլլու Մեհմեդ փաշայի) մզկիթի կառուցումը", "f7b57feb"], "d": ["Ունքապանի կամրջի Շիշհանեի կողմի հենարանի մոտ գտնվող մզկիթը մեծ վեզիր Սոքոլլու Մեհմեդ փաշան կառուցել տվեց ճարտարապետ Սինանին։ Կառույցը Սոքոլլուի անունով կառուցված Սինանի երկու մզկիթներից մեկն է (մյուսը Կադըրղայի մզկիթն է)։", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["Մուրադ III-ը ֆիրման տվեց «Հյունեռնամե»-ի գրման համար", "b125710d"], "d": ["Մուրադ III-ը 1578 թ. հունվարի 2-ի ֆիրմանով Սեյիդ Լոկմանին հրամայեց գրել «Հյունեռնամե»-ն, որի նյութը Օսման Ղազիից մինչև իր օրերը փադիշահների կյանքն էր. երկի մանրանկարները պատրաստեցին Նաքքաշ Օսմանը և նրա խումբը։", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["Զալ Մահմուդ փաշայի մզկիթի ավարտը", "732f75bc"], "d": ["1574 թ. Զալ Մահմուդ փաշայի և Շահ սուլթանի ամուսնությունից հետո սկսված համալիրի շինարարության ընթացքում մզկիթի կառուցումն ավարտվեց 1580 թ.. մեդրեսեների աշխատանքը տևեց մինչև 1582 թ., իսկ աղբյուրինը՝ մինչև 1590 թ.։ Համալիրն ուշադրություն է գրավում Էյուբի լանջերին երկու համաչափ մինարեթներով իր ինքնատիպ հատակագծով։", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["«Հյունեռնամե»-ի II հատորի ավարտը", "70a1e741"], "d": ["«Հյունեռնամե»-ի երկրորդ հատորը ավարտվեց 1588 թ. հունվարին. 65 մանրանկարով այն դարձավ օսմանյան պատմագրության՝ փաստագրական առումով ամենաարժեքավոր երկերից մեկը։ Երկու հատորներն էլ նկարազարդվել են Նաքքաշ Օսմանի արհեստանոցում։", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["Դավուդ աղան դարձավ պալատական գլխավոր ճարտարապետ", "8cdc7f53"], "d": ["1588 թ. ճարտարապետ Սինանի մահվանը հաջորդած կարճ ընդմիջումից հետո Դավուդ աղան 1592 թվականից սկսած պաշտոնական փաստաթղթերում սկսեց հիշատակվել որպես պալատական գլխավոր ճարտարապետ։ Սելիմիյե համալիրի որոշ լրացուցիչ տարրերը և Ենի Ջամիի առաջին շինարարությունը ստանձնած Դավուդ աղան ժամանակաշրջանի ամենակարևոր ճարտարապետներից մեկն է։", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["Ենի Ջամիի (Էմինոնյու) հիմնադրումը", "d3cddc01"], "d": ["Մեհմեդ III-ի մոր՝ Սաֆիյե սուլթանի կառուցողական հովանավորությամբ մզկիթի հիմքը, գետնի ցցերով ամրացվելով, դրվեց քարե բլոկներով։ TDV-ի երկու տարբեր հոդվածները այս իրադարձության համար տարբեր թվականներ են տալիս («Ենի Ջամիի համալիր» հոդվածը՝ 1598 թ. ապրիլի 9, «Դավուդ աղա» հոդվածը՝ 1597 թ. օգոստոսի 23). այստեղ հիմք է ընդունվել շենքի հենց իրեն նվիրված հոդվածի թվականը։", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["Դավուդ աղայի մահը ժանտախտից և Ենի Ջամիի շինարարության կիսատ մնալը", "81f2cd04"], "d": ["Երբ Դավուդ աղան Ենի Ջամին դեռ գետնից ընդամենը մեկ զիրա բարձրացրած՝ 1598 թ. սեպտեմբերին մահացավ ժանտախտի համաճարակից, նրա փոխարեն գլխավոր ճարտարապետ նշանակվեց Դալգըչ Ահմեդ չավուշը։ TDV-ն նշում է, որ մահվան թվականը ժամանակագրական ոտանավորի վրա հիմնված այլընտրանքային վարկածում նաև 1599-1600 է, և ստույգ թվականը հնարավոր չի եղել որոշել։", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["Անկարայի սոֆի լայնածավալ արտահանումը Եվրոպա", "3f37018d"], "d": ["Անկարայում գործվող սոֆն ու շալը, բացի Ստամբուլի, Բուրսայի, Դամասկոսի, Հալեպի նման ներքին շուկաներից, արտահանվում էին Վենետիկ, Լեհաստան, Անգլիա և Ֆրանսիա։ TDV-ի բերած օրինակում 1599 թ. տասնութ վաճառական 5.700.000 ակչե արժողությամբ 162 բեռ սոֆ գնեցին և ուղարկեցին Հալեպ ու Վենետիկ։", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["Ենի Ջամիի շինարարության դադարը Մեհմեդ III-ի մահվան պատճառով", "5acef053"], "d": ["1603 թ. կառուցողուհի Սաֆիյե սուլթանի որդի Մեհմեդ III-ի մահից հետո Սաֆիյե սուլթանին ուղարկեցին Հին պալատ, և Ենի Ջամիի շինարարությունը կիսատ մնաց. կառույցն այս վիճակում մոտ վաթսուն տարի անավարտ սպասեց։", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["Քյաթիբ Չելեբին Հալեպում սկսեց «Քաշֆ ազ-զունուն»-ի համար հետազոտությունը", "094e6870"], "d": ["Հետագայում իր մատենագիտական գլուխգործոցը դարձած «Քաշֆ ազ-զունուն»-ի նյութը Քյաթիբ Չելեբին սկսեց հավաքել 1633 թ. Հալեպում։ Քսան տարի տևելիք այս աշխատանքի ընթացքում նա մեկ առ մեկ ուսումնասիրեց իր այցելած քաղաքների գրադարաններն ու գրախանութները։", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["Նեֆիին մահապատժի ենթարկեցին իր երգիծանքների պատճառով", "5e459c60"], "d": ["Իր երգիծանքներով հայտնի դիվանի բանաստեղծ Նեֆին «Սիհամ-ը Քազա» անունով երգիծական ժողովածուի պատճառով 1635 թ. մահապատժի ենթարկվեց Մուրադ IV-ի հրամանով։ Մեծ վեզիր Բայրամ փաշան նրան հանձնեց. Նեֆիին խեղդամահ արեցին պալատի փայտանոցում, և դիակը ծով նետեցին։", "e3b52153"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["Ընդգրկուն նարխի դեֆթերի կազմումը", "6c1e231b"], "d": ["Թեև նարխի (գների առաստաղ) կիրառումը Օսմանյան պետությունում շատ հին արմատներ ունի, մեր օրերը հասած ամենաընդգրկուն նարխի դեֆթերը 1640 թ. է. սնունդը, հագուստը, ծառայությունները, չափանիշներն ու հիգիենայի պայմաններն ընդգրկող այս դեֆթերը, TDV-ի ձևակերպմամբ, «գործել է ինչպես շուկայի կարգավորման լիարժեք օրենք»։", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["Քյաթիբ Չելեբին առաջին անգամ սկսեց գրել «Ջիհաննյումա»-ն", "554c6734"], "d": ["Արևմուտքի աշխարհագրական հայտնագործությունների առջև օսմանյան աշխարհագրական գիտելիքի բացը լրացնելու նպատակով Քյաթիբ Չելեբին 1648 թ. սկսեց «Ջիհաննյումա»-ի առաջին շարադրանքը։ Այս առաջին տարբերակը կիսատ մնաց, քանի որ եվրոպական որոշ երկրների մասին բավարար աղբյուրներ չգտնվեցին։", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["Իլթիզամի համակարգի հասունացումը՝ անցնելով ռազմական խավի մենաշնորհի տակ", "2c587934"], "d": ["Իլթիզամի կարգը (հարկահավաքությունը որոշակի գումարի դիմաց մասնավոր անձանց կապալով տալը) կիրառվում էր 15-րդ դարի երկրորդ կեսից, բայց 16-րդ դարի սկզբից արագորեն տարածվում էր։ Ըստ TDV-ի՝ ոլորտի լիովին ռազմական խավի անդամների մենաշնորհի տակ անցնելու ընթացքն ավարտվեց 1650 թ.. այսպիսով իլթիզամը դարձավ թիմարային համակարգին փոխարինած հիմնական ֆինանսական մեթոդը։", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["Քյաթիբ Չելեբին ձեռնամուխ եղավ «Ջիհաննյումա»-ն նորից գրելուն", "e9c68110"], "d": ["Առաջին շարադրանքը կիսատ թողած Քյաթիբ Չելեբին 1654 թ. վերջին ձեռնամուխ եղավ «Ջիհաննյումա»-ն նորովի գրելուն։ Այս երկրորդ տարբերակն էլ չավարտվեց. երբ երկը հասել էր Վանին, 1657 թ. հեղինակի մահով կիսատ մնաց և միայն 1732 թ. Իբրահիմ Մյութեֆերիկան այդ վիճակով տպագրեց այն։", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["Ենի Ջամիի ավարտը և բացումը աղոթքի համար", "d6d86c82"], "d": ["Ավելի քան վաթսուն տարի կիսատ մնացած Ենի Ջամիի շինարարությունն ավարտվեց Հաթիջե Թուրհան վալիդե սուլթանի 1661 թ. պաշտոնի կոչած գլխավոր ճարտարապետ Մերեմեթչի Մուստաֆա աղայի ղեկավարությամբ, և այն բացվեց աղոթքի համար 1665 թ. հոկտեմբերի 30-ի ուրբաթօրյա նամազով։", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["Մեհմեդ IV-ը Էդիրնեի թլփատության տոնակատարության ժամանակ օրեր շարունակ ջիրիդ խաղեր կազմակերպեց", "3638a5b6"], "d": ["Մեհմեդ IV-ը 1675 թ. Էդիրնեում կազմակերպած իր շահզադեների թլփատության տոնակատարությանը կազմակերպեց օրեր տևող ջիրիդի մրցումներ. TDV-ի «Ջիրիդ» հոդվածում դա հատուկ հիշատակվում է որպես օսմանյան արքունիքի՝ ջիրիդ խաղին ցուցաբերած աջակցության ամենաշքեղ օրինակներից մեկը։", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["Հաֆիզ Օսմանը մշակեց իր ինքնատիպ գեղագրական ոճը", "93081cb3"], "d": ["Շեյխ Համդուլլահի գծից եկող Հաֆիզ Օսմանը 1679 թ. աքլամ-ի սիթթեում մշակեց իր ինքնատիպ նոր ոճը, որը հետագայում կոչվելու էր «Հաֆիզ Օսմանի դպրոց»։ Այս ոճը երկու առանձին ճյուղերով շարունակվել է մինչև մեր օրերը։", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["Հաֆիզ Օսմանը նշանակվեց Մուստաֆա II-ի գեղագրության ուսուցիչ", "d976cda4"], "d": ["Ժամանակի ամենահմուտ գեղագիրը համարվող Հաֆիզ Օսմանը 1695 թ. նշանակվեց նոր գահ բարձրացած Մուստաֆա II-ի գեղագրության ուսուցիչ։ Իր կյանքի ընթացքում նա պատրաստել է մոտ հիսուն գեղագիր և ընդօրինակել Ղուրանի 25 օրինակ։", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["Իթրիի մահը", "62750526"], "d": ["Թուրքական երաժշտության մեծագույն կոմպոզիտորներից Բուհուրիզադե Մուստաֆա Իթրի էֆենդին, ըստ ժամանակաշրջանին մոտ աղբյուրների, մահացել է 1711 թ.։ Սեգյահ թեքբիրի և ռաստ նաաթի նման գործերով նա թողել է մզկիթային և թեքքեական երաժշտության գլուխգործոցներ։", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["Նեդիմի առաջ գալը որպես Լալեի դարաշրջանի պոեզիայի առաջամարտիկ", "d3c40dbb"], "d": ["1718-1730 թվականների Լալեի դարաշրջանի ընթացքում Նեդիմը մշակեց բանաստեղծական նոր ոճ, որն աչքի էր ընկնում արտահայտության կատարելությամբ, պարզության որոնումով և սրամիտ լեզվաոճով։ Նևշեհիրցի Դամադ Իբրահիմ փաշայի շուրջ զարգացած այս ոճը համարվում է դիվանի պոեզիայի տեղայնացման հոսանքի ամենամեծ ներկայացուցիչը։", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["Լևնին նկարազարդեց «Սուրնամե-ի Վեհբի»-ն", "8c127866"], "d": ["Պալատական նկարիչ Լևնին 137 մանրանկարով նկարազարդեց «Սուրնամե-ի Վեհբի»-ն, որը պատմում է Ահմեդ III-ի շահզադեների 1720 թ. թլփատության հարսանյաց տոնակատարությունը։ Նախորդ օրինակների հակառակ՝ տոնախմբությունները միայն Աթմեյդանիով չսահմանափակելով, այլ քաղաքի տարբեր անկյուններում պատկերելով՝ նա օսմանյան մանրանկարչության մեջ սկիզբ դրեց նոր ըմբռնման։", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["Գեդիքի համակարգի պաշտոնական հաստատումը որպես մենաշնորհի վրա հիմնված արհեստավորական կարգ", "cd0f79a7"], "d": ["Ըստ TDV-ի՝ համակարգված վերափոխումը, որով գեդիքի իրավունքը ձեռք բերեց «մենաշնորհի, արտոնության և մի տեսակ արտոնագրի» իմաստ, հետագծվում է 1727 թվականից. արհեստների մեջ որոշակի թվով անձանց աշխատելու իրավունք տվող այս կարգը արմատավորվեց «գեդիքի իրավունք» անունով՝ խանութներում, որոնց մեծ մասը վաքֆի սեփականություն էր։", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["Սադաբադի ավերումը Փաթրոնա Հալիլի ապստամբության ժամանակ", "8a30f9a0"], "d": ["1730 թ. սեպտեմբերի 25-ին բռնկված Փաթրոնա Հալիլի ապստամբության ժամանակ Սադաբադում ավերվեցին հարյուրավոր ամառանոցներ և շինություններ. Լալեի դարաշրջանի խորհրդանիշ այս համալիրն այլևս չվերագտավ իր նախկին շուքը։", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["Նեդիմի մահը Փաթրոնա Հալիլի ապստամբության ժամանակ", "06bf909e"], "d": ["Երբ բռնկվեց Փաթրոնա Հալիլի ապստամբությունը, Սեքբան Ալի փաշայի մեդրեսեի մուդարիս Նեդիմը մահացավ ապստամբությանը հաջորդած օրերին։ Մահվան օրը անհայտ է. սակայն, քանի որ նրա ժառանգության մասին ղասսամի վկայագիրը կազմվել է հիջ. 1143 թ. Ռաբի աս-սանի ամսի 15-ին (1730 թ. հոկտեմբերի 28), նա մահացել է այս թվականից առաջ։ Մահվան պատճառի մասին կան տարբեր վարկածներ. աղբյուրների մի մասը գրում է, որ նա մահացել է վախի հիվանդությունից (illet-i vehîme) կամ խմիչքի և ափիոնի պատճառով ձեռք բերած դողի հիվանդությունից, իսկ Մյուսթաքիմզադեն գրում է, որ խռովության ժամանակ վախից բարձրացել է իր տան տանիքը և այնտեղից ընկնելով մահացել։ Նրա մահով փաստացի ավարտվեց նաև Լալեի դարաշրջանի մշակութային փայլը։", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["Լևնիի մահը", "dd48b56e"], "d": ["Օսմանյան մանրանկարչության վերջին մեծ ներկայացուցիչը համարվող Լևնին մահացավ 1732 թ.։ Նրա գործերի մեծ մասը այսօր գտնվում է Թոփքափը պալատի թանգարանում։", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["Նուրուօսմանիյե մզկիթի և համալիրի հիմնադրումը", "397ec798"], "d": ["Նուրուօսմանիյե համալիրի հիմքը Մահմուդ I-ը դրեց 1749 թ. հունվարի 19-ին։ Այս կառույցը համարվում է օսմանյան ճարտարապետության մեջ եվրոպական բարոկկո ոճի առաջին խոշոր կիրառությունը և նկատելիորեն շեղվում է դասական համալիրի սխեմայից։", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["Նուրուօսմանիյե մզկիթի և համալիրի բացումը", "15d83731"], "d": ["Մահմուդ I-ի սկսած, բայց նրա կողմից ավարտված չտեսած համալիրը բացվեց նրա եղբոր՝ Օսման III-ի օրոք, 1755 թ. դեկտեմբերի 5-ին։ Մզկիթն անունն ստացավ «Օսմանի լույս» իմաստով՝ ի պատիվ բացումն իրականացրած Օսման III-ի։", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["Կայսերական ծովային ճարտարագիտական դպրոցի (Mühendishâne-i Bahrî-i Hümâyun) բացումը", "a2fab1cd"], "d": ["Օսմանյան առաջին արդիական ծովային ճարտարագիտական դպրոցը՝ Mühendishâne-i Bahrî-i Hümâyun-ը, ըստ ֆրանսիական արխիվային փաստաթղթերի, բացվել է 1775 թ. ապրիլի 29-ին Աբդուլհամիդ I-ի օրոք, մեծ վեզիր Դերվիշ Մեհմեդ փաշայի պաշտոնավարության ժամանակ։", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["Էսհամի համակարգի ներդրումը", "eabd8ece"], "d": ["Քյուչուք Քայնարջայի պայմանագրի բերած 7,5 միլիոն ղուրուշի ռազմատուգանքի բեռի առջև 1775 թ. ներդրվեց էսհամի համակարգը։ Մալիքյանեի սահմանները հաղթահարելու համար նախագծված այս եղանակով մուքաթաայի եկամուտը բաժանվում էր բաժնեմասերի, և, ի տարբերություն մալիքյանեի, բաժնետեր կարող էին դառնալ նաև կանայք, ոչ մուսուլմանները և հասարակ ժողովուրդը։", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["Համմամիզադե Իսմայիլ Դեդե էֆենդիի ծնունդը", "c033f039"], "d": ["Թուրքական երաժշտության ամենաբեղուն կոմպոզիտորներից Համմամիզադե Իսմայիլ Դեդե էֆենդին ծնվել է 1778 թ. հունվարի 9-ին Ստամբուլի Շեհզադեբաշը թաղամասում։ Իր կյանքի ընթացքում նա հորինել է ավելի քան 500 գործ, որոնցից մոտ 294-ը հասել են մեր օրերը։", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["Կայսերական ցամաքային ճարտարագիտական դպրոցի (Mühendishâne-i Berrî-i Hümâyun) շինարարության սկիզբը", "4f5d521a"], "d": ["Սելիմ III-ի Նիզամ-ը Ջեդիդ բարեփոխումների ամենակարևոր հաստատություններից Mühendishâne-i Berrî-i Hümâyun-ի շինարարությունը սկսվեց 1793 թ. հուլիսի 14-ին։ Շենքն ավարտվեց 1795 թ. սեպտեմբերին և բացվեց ուսուցման համար. հաստատությունը, որի համար օրինակ էին ծառայել եվրոպական ռազմական ակադեմիաները, օսմանյան երկրորդ ռազմաճարտարագիտական դպրոցն էր։", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["Սելիմ III-ը սկսեց վերացնել որոշ արհեստավորական համքարությունների մենաշնորհը", "008f4a7d"], "d": ["TDV-ի «Արհեստավորներ» հոդվածի համաձայն՝ հիմնադրումից ի վեր ահիական կազմակերպության հետ միահյուսված օսմանյան համքարական կարգում «ահի բաբա» և «շեյխ» կոչվող պաշտոնյաները մինչև 19-րդ դարի սկիզբը ղեկավարում էին համքարությունները. երբ 18-րդ դարում համքարությունների՝ մենաշնորհով գները նարխից (պետական սահմանված գին) վեր բարձրացնելը տնտեսական ճնշում ստեղծեց, Սելիմ III-ը 1794 թվականից սկսեց վերացնել հիմնական սննդամթերքի համքարությունների մենաշնորհը։", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["Դեդե էֆենդին պալատ ընդունվեց որպես musâhib-i şehriyârî", "0cb99ac3"], "d": ["Սելիմ III-ի օրոք մի բուսելիք ստեղծագործությամբ փադիշահի ուշադրությունը գրաված Դեդե էֆենդին 1812 թ. Մահմուդ II-ի կողմից ընդունվեց «musâhib-i şehriyârî» (փադիշահի մերձավոր խնջույքակիցներ) շարքը, իսկ կարճ ժամանակ անց բարձրացավ գլխավոր մուազզինի պաշտոնին։", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["Օսմանյան պետությունում առաջին կանոնավոր մարդահամարի անցկացումը", "4f004c6c"], "d": ["Զինակոչի ենթակա բնակչությունը որոշելու նպատակով Մահմուդ II-ը առաջին անգամ 1830 թ. վերջերին կանոնավոր մարդահամար անցկացնել տվեց. գրանցվեց միայն արական բնակչությունը, և Անատոլիայում ու Ռումելիայում հաշվվեց մոտ 7,5 միլիոն մարդ։ Էրզրումի և Վանի նման որոշ շրջաններում մարդահամարը հնարավոր եղավ ավարտել միայն 1836 թ.։", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["Ֆեսխանե-ի Ամիրեի հիմնումը", "971ab85a"], "d": ["1826 թ. Ենիչերիների օջախի վերացումից հետո ստեղծված Ասաքիր-ի Մանսուրե-ի Մուհամմեդիյե բանակի ֆեսի պահանջարկը բավարարելու համար 1,5 միլիոն ղուրուշ կապիտալով 1833 թ. Կադըրղայի Ջյունդի հրապարակում սկսվեց ֆեսի արտադրությունը։ Ձեռնարկությունները 1839 թ. տեղափոխվեցին Էյուբի Հաթիջե սուլթանի պալատ. Ֆեսխանեն դրեց օսմանյան տեքստիլ արդյունաբերության հիմքը։", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["Բժշկական դպրոցը ստացավ Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne անունը", "187d60f3"], "d": ["Ղալաթասարայի Էնդերունի աղաների դպրոցի շենք տեղափոխված բժշկական դպրոցը 1839 թ. մայիսի 14-ին Մահմուդ II-ի այցի առիթով ստացավ «Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne» անունը. այսպիսով հաստատությունը պաշտոնապես հաստատվեց որպես ռազմա-վարչական դպրոց։", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["Դեդե էֆենդիի մահը Մինայում՝ հաջի ժամանակ", "c3e613a2"], "d": ["Հաջի պարտականությունը կատարելու համար Մինա մեկնած Համմամիզադե Իսմայիլ Դեդե էֆենդին, վարակվելով խոլերայով, մահացավ 1846 թ. նոյեմբերի 29-ին։ 1824-1839 թվականներին յոթ տարբեր մևլևիական ային հորինած արվեստագետի մահով փակվեց դասական օսմանյան երաժշտության մի շրջան։", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["1850 թ. առևտրային օրենսգրքի ընդունումը", "8ac085fd"], "d": ["Թանզիմաթի շրջանի իրավական բարեփոխումների շրջանակում արևմտյան պետություններից թարգմանության և փոխառության ճանապարհով ընդունվեցին նոր օրենքներ. քրեական օրենքը ուժի մեջ մտավ 1840 թ., առևտրային օրենքը՝ 1850 թ., հողային օրենքը՝ 1857 թ.։ Առևտրային օրենսգիրքը օսմանյան առևտրային իրավունքի առաջին արդիական կոդիֆիկացիան էր։", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["Ղրիմի թաթարների և կովկասյան ժողովուրդների մեծ գաղթի ալիքի սկիզբը դեպի օսմանյան տարածքներ", "8832c06d"], "d": ["1859 թ. շեյխ Շամիլի՝ ռուսներին գերի ընկնելուց հետո Ղրիմի թաթարների հետ միասին Կովկասից մեծ թվով չերքեզ և նողայ մուհաջիրներ սկսեցին գաղթել օսմանյան տարածքներ։ Այս գաղթի ալիքը տարբեր ինտենսիվությամբ տևեց մինչև 1877-78 թթ. ռուս-թուրքական պատերազմից հետո ընկած ժամանակը։", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["Մուհաջիրների հանձնաժողովի հիմնումը", "9717e77e"], "d": ["Կովկասից աճող գաղթի ալիքը կառավարելու համար օսմանյան կառավարությունը 1860 թ. հունվարի 16-ին հիմնեց Մուհաջիրների հանձնաժողովը։ Հանձնաժողովը համակարգում էր վերաբնակեցման աշխատանքները Անատոլիայում, Բալկաններում և Սիրիայում և գործեց մինչև 1875 թ.։", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["Օսմանյան բանկի (Bank-ı Osmanî) վերակազմավորումը որպես Bank-ı Osmanî-i Şâhâne (Օսմանյան կայսերական բանկ)", "c3530456"], "d": ["1856 թ. Ղրիմի պատերազմից հետո արտաքին պարտքի վճարումները կառավարելու համար հիմնվել էր Լոնդոնում նստող, անգլիական կապիտալով Bank-ı Osmanî-ն։ 1863 թ. ֆրանս-անգլիական համատեղ խմբին թույլատրվեց հիմնել նոր բանկ՝ Bank-ı Osmanî-i Şâhâne (Օսմանյան բանկ) անունով. հաստատությունը հետագայում ստացավ նաև թղթադրամ թողարկելու իրավունք։", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["Cem'iyyet-i Tedrîsiyye-i İslâmiyye ընկերության հիմնումը", "77ad553a"], "d": ["Աղքատ մուսուլման աշկերտների կրթությունը ստանձնելու նպատակով 1864 թ. մարտի 30-ին հիմնվեց Cem'iyyet-i Tedrîsiyye-i İslâmiyye-ն. այս քաղաքացիական ընկերության նախաձեռնությունը առաջատար օրինակ է, ուր բարեգործական հաստատության ավանդույթը վերածվեց արդիական դպրոցի նախագծի։ Ընկերությունը ինը տարի անց բացելու էր Դարուշշաֆաքան։", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["1864 թ. Վիլայեթների կանոնադրությամբ մուխթարության և ավագանու համակարգի կարգավորումը", "1a2e8cf2"], "d": ["1864 թ. Վիլայեթների կանոնադրությամբ վերակազմավորվեց գյուղական կառավարումը. ընդունվեց, որ մուսուլմանների և ոչ մուսուլմանների համատեղ բնակվող գյուղերում յուրաքանչյուր համայնք ընտրի իր մուխթարն ու ավագների խորհուրդը։ Այսպիսով ավագների խորհուրդը առաջին անգամ պաշտոնական տեղ գրավեց գյուղի/թաղամասի կառավարման մեջ։", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["Չերքեզների մեծ աքսորի գագաթնակետը", "b2ab1874"], "d": ["1858-1878 թվականներին Ռուսաստանի կողմից Կովկասի գրավման ընթացքում, որն ամենաինտենսիվն էր 1861-1864 թվականներին, 1,2-1,5 միլիոն չերքեզ հարկադրաբար գաղթեցվեց օսմանյան տարածքներ։ Ըստ TDV-ի՝ բազմաթիվ հետազոտողներ այս իրադարձությունը բնութագրում են որպես «ժամանակակից պատմության առաջին էթնիկ զտման շարժումը»։", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["1869 թ. Հանրային կրթության կանոնադրության հրապարակումը", "787f6022"], "d": ["1869 թ. սեպտեմբերի 1-ին հրապարակված Հանրային կրթության կանոնադրությունը (Maârif-i Umûmiyye Nizamnâmesi) դարձավ գավառներում և կենտրոնում հանրային կրթությունը կարգավորող առաջին ընդգրկուն փաստաթուղթը։ Կանոնադրությամբ հիմնվեց Meclis-i Kebîr-i Maârif-ը. մանկական դպրոցները զուտ կրոնական կրթության փուլից դուրս բերելու և գրել-կարդալ սովորեցնելուն ուղղված վերակազմավորումը սկսվեց այս կարգավորմամբ։", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["Դարուշշաֆաքա դպրոցի ուսուցման սկիզբը", "525c457c"], "d": ["Cem'iyyet-i Tedrîsiyye-i İslâmiyye-ի հիմնած Դարուշշաֆաքան 1873 թ. հունիսի 28-ին փաստացի սկսեց ուսուցումը՝ որբ և աղքատ մուսուլման երեխաներին անվճար գիշերօթիկ կրթելու համար. ընդունելության առավելագույն տարիքը սահմանվեց տասը։", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["1894 թ. Ստամբուլի երկրաշարժը", "7ae7f648"], "d": ["1894 թ. հուլիսի 10-ին Իզմիթի ծոցի բաց ծովում տեղի ունեցած երկրաշարժը ծանր հարվածեց Ստամբուլին. վնասվեցին բազմաթիվ մզկիթներ և պատմական շինություններ, այդ թվում՝ Ստամբուլի պարիսպները։ TDV-ի «Երկրաշարժ» հոդվածն այս երկրաշարժը, 1509, 1719 և 1766 թվականների երկրաշարժերի հետ միասին, թվում է Մարմարայի տարածաշրջանում մարդկային և նյութական մեծ կորուստներ պատճառած երկրաշարժերի շարքում։", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["Դարուլաջեզեի բացումը", "a30baf31"], "d": ["Աբդուլհամիդ II-ի 1890 թվականից տված հրամանների հիման վրա պատրաստված Դարուլաջեզեն 1896 թ. փետրվարի 2-ին բացեց մեծ վեզիր Հալիլ Ռիֆաթ փաշան։ Անտեր երեխաներին, ծերերին և կարիքավորներին պատսպարող հաստատությունը 200 մահճակալանոց հիվանդանոցով, արհեստանոցներով և մզկիթ, եկեղեցի, ժողովարան ունեցող առանձին աղոթատներով իր ժամանակի սոցիալական օգնության ամենամեծ համալիրն էր։", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["Դարուլֆյունուն-ը Շահանեի վերահիմնումը որպես մշտական հաստատություն", "7d6d8fc4"], "d": ["Դարուլֆյունունը նախորդ երկու անհաջող փորձերից (1863 և 1870) հետո 1900 թ. օգոստոսի 31-ին վերահիմնվեց «Դարուլֆյունուն-ը Շահանե» անունով որպես մշտական հաստատություն. TDV-ն այս թվականը բնութագրում է որպես այսօրվա թուրքական համալսարանական համակարգի անմիջական հիմքը։", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["Սարբեդարները վերցրին Սաբզևարը. Խորասանում Իլխանությունից հետո առաջին պետությունը", "af997fec"], "d": ["Երբ Աբու Սաիդի մահով (1335 թ. նոյեմբերի 30) իլխանական կենտրոնական իշխանությունը փլուզվեց, Խորասանում հարկահավաքների դեմ կուտակված զայրույթը պայթեց Բաշթինում. Աբդուռազզաքը ապստամբեց 1337 թ. մարտի 13-ին և 1337 թ. սեպտեմբերի 9-ին (հիջ. 738 թ. Սաֆար 12) գրավեց Սաբզևարը։ «Սարբեդար»՝ «գլուխը կախաղանին» անունը նրանց իսկ խոսքն է, որ արտահայտում է, թե պարտվելու դեպքում պատրաստ են կախաղանի ելնել։", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["Մարաշի սեյիդները վերցրին Ամոլը. սեյիդների իշխանությունը Մազանդարանում", "c0e03266"], "d": ["Սեյիդ Քըվամեդդին Մարաշին, գնալով Խորասանում Սարբեդարների հարթած ճանապարհով, հիջ. 760 (1359) թ. գրավեց Ամոլը և Կասպից ծովի հարավային ափին հիմնեց սեյիդական պետություն։ Հարստությունը տարածվեց Սարիում, Բարֆուրուշում և շրջակայքում. այն ցնցվեց Լենկթեմուրի արշավանքներից և ցրվեց Սեֆյան Շահ Աբբաս I-ի օրոք։", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["Քարքիա հարստությունը հիմնվեց Գիլանում. Կասպյան ափի վերջին անկախ տիրակալները", "6e5f9db7"], "d": ["Ալի Քիան, իր ընտանիքի հետ վերադառնալով Գիլան, հիջ. 773 (1371-72) թ. հիմնեց Լահիջան կենտրոնով Քարքիաների իշխանությունը. հարստությունը ավելի քան երկու դար իր ձեռքում պահեց Կասպից ծովի հարավ-արևմտյան ափը և գոյատևեց մինչև 1592 թ.՝ Սեֆյան Շահ Աբբաս I-ի կողմից շրջանի բռնակցումը։", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["Դարֆուրում Դաջուների տիրապետությունն անցավ Թունջուրներին", "6eb22a2a"], "d": ["TDV İslâm Ansiklopedisi-ի «Դարֆուր» հոդվածի համաձայն՝ տարածաշրջանում առաջինը հաստատվածները և առաջին պետությունը հիմնողները Դաջու ցեղն են. 13-14-րդ դարերի ընթացքում այստեղ իշխած Դաջուները առևտրական գերիշխանությունը զիջեցին Թունջուրներին, և 15-րդ դարում, հատկապես կենտրոնական շրջանում, վիճակը լիովին շրջվեց հօգուտ Թունջուրների։", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["Իսպանիան վերագրավեց Բադիսի (Պենյոն դե Վելես) ժայռակղզին", "0dc52728"], "d": ["TDV-ի «Սաադյաններ» հոդվածը գրառում է, որ իսպանացիների կողմից Բադիսի գրավումը ծանր հարված էր Մաղրիբի ծովագնացությանը (1564)։ Մարոկկոյի հյուսիսային ափի այս ժայռոտ դիրքը հենարան էր ծովահենության և օսմանա-իսպանական մրցակցության համար Արևմտյան Միջերկրականում։", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["Ալ-Արաիշի (Լարաշ) զիջումը Իսպանիային", "7b8f6e27"], "d": ["Սաադյան հարստության մասնատման քաղաքացիական պատերազմի տարիներին Ատլանտյան ափի ալ-Արաիշ նավահանգիստը թողնվեց Իսպանիային։ TDV-ի «Սաադյաններ» հոդվածը գրառում է, որ այդ շրջանում երկիրը բաժանվել էր Մարաքեշի (հարավ) և Ֆեսի (հյուսիս) ամիրայությունների, և գահի համար կռվող կողմերը դրսից օգնություն էին որոնում։ Նավահանգիստը մոտ ութսուն տարի մնալու էր իսպանական ձեռքում. 1689 թ. այն հետ վերցնելու էր Մևլայ Իսմայիլը։", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["Մամուրայի (Մեհդիա) անցումը իսպանացիների ձեռքը", "c8fd494e"], "d": ["Սեբու գետի գետաբերանի Մամուրա (Մաամուրե / Մեհդիա) նավահանգիստը 1614 թ. վերցրին իսպանացիները և ամրացրին San Miguel de Ultramar անունով։ TDV-ի «Մևլայ Իսմայիլ» հոդվածը գրառում է, որ նավահանգիստը հիջ. 1092 (1681) թ. հանկարծակի հարձակմամբ հետ վերցվեց իսպանացիների ձեռքից. այսինքն՝ իսպանական տիրապետությունը տևել է վաթսունյոթ տարի։", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["Սաադյան հարստության վերջը. Մարոկկոյում սկսվում է Ալավյան (Ֆիլալի) դարաշրջանը", "b1afa579"], "d": ["TDV İslâm Ansiklopedisi-ի «Սաադյաններ» հոդվածը նրանց սահմանում է որպես «Մարոկկոյում իշխած իսլամական հարստություն (1511-1659)»։ 1549 թ. Վատասյանների իշխանությանը վերջ դրած և ամբողջ Մարոկկոն միավորած, 1578 թ. Վադի ալ-Մախազինի մոտ պորտուգալական բանակը ոչնչացրած և Օսմանյան պետությանը երբեք չենթարկված հարստությունը գահի համար երկարատև կռիվներից հետո ավարտվեց 1659 թ.։ Նրան փոխարինեցին Թաֆիլալթից եկած Ալավյան (Ֆիլալի) շերիֆները. Մևլայ Ռաշիդը 1666 թ. մտնելով Ֆես քաղաք՝ ամրապնդեց նոր հարստությունը, իսկ նրա եղբայր Մևլայ Իսմայիլը Ատլանտյան ափը մաքրեց եվրոպական դիրքերից։", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["Իսպանիան գրավեց ալ-Հոսեյմայի (Ալուսեմաս) կղզիները", "954ca998"], "d": ["Միջերկրական ծովի ափի ալ-Հոսեյմայի կղզիները 1673 թ. գրավեց իսպանական նավատորմը։ Բադիսի և Սեուտայի հետ միասին դրանք Մարոկկոյի հյուսիսային ափին Իսպանիայի պահած և մինչ այսօր նրա ձեռքին մնացած դիրքերից են։ Նույն տարում Մևլայ Իսմայիլի ավագ եղբայր Մևլայ Ռաշիդը մտել էր Մարաքեշ և ընդունել ժողովրդի հավատարմության երդումը, և Ֆիլալիների իշխանությունը ամրապնդվել էր հարավում. ափի այս կորուստը ցույց է տալիս, որ ներքին միավորումը դեռ համարժեք արտացոլում չուներ արտաքին ճակատում։", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["Մևլայ Իսմայիլը ալ-Արաիշը հետ վերցրեց իսպանացիներից", "a54bc6ee"], "d": ["TDV-ի «Մևլայ Իսմայիլ» հոդվածը պարզ է. «Հիջ. 1100-ին (1689) Արաիշը հետ վերցնելով իսպանացիներից՝ ձեռք գցեցին 200 թնդանոթ, իսկ երկու տարի անց հետ վերցրին նաև Ասիլան»։ Սա Ֆիլալի սուլթանի՝ ափի մաքրման շղթայի օղակներից մեկն է. Տանժերը հետ վերցվեց 1678 թ. անգլիացիներից, Մամուրան՝ 1681 թ., ալ-Արաիշը՝ 1689 թ., Ասիլան՝ 1691 թ.։ Ութսուն տարի առաջ Սաադյան քաղաքացիական պատերազմում լքված նավահանգիստն այսպիսով վերադարձավ Մարոկկոյին։", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["Դարֆուրի սուլթանության հիմնումը. Կեյրա հարստությունը և Սուլեյման Սոլոնջը", "0fc1c112"], "d": ["Ըստ TDV-ի՝ Դարֆուրի սուլթանության հիմնումը ընկնում է 17-րդ դարի վերջին՝ Բումու ալ-Կասիրի ներխուժմանը հաջորդած խառնակությունից հետո։ Ֆուրերը, Սուլեյման Սոլոնջի գլխավորած Քիրա (Կեյրա) տոհմի առաջնորդությամբ, իշխանությունը խլեցին Դաջուների և Թունջուրների ձեռքից և հաստատեցին ամուր կառավարում։ Սուլեյման Սոլոնջը իշխեց 1695-1715 թվականներին։ Դարֆուրի սուլթանները հետագա դարերում նամակագրություն ունեցան Բարձր Դռան հետ. Աբդուլմեջիդն ու Աբդուլազիզը հաստատեցին նրանց իշխանությունը։", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["Ֆրանսիայում Առաջին Հանրապետության հռչակումը. թագավորության վերջը", "d53d49b0"], "d": ["Ազգային կոնվենտի առաջին նիստում վերացվեց թագավորությունը, և հաջորդ օրը հռչակվեց Առաջին Հանրապետությունը. նոր օրացույցի առաջին տարին սկսվեց այս օրից։ Օսմանյան պետության համար զրուցակիցը չփոխվեց, բայց փոխվեց զրուցակցի տեսակը. Սելիմ III-ի Նիզամ-ը Ջեդիդի տարիներին Ֆրանսիան այլևս ոչ թե հարստություն էր, այլ վարչակարգ, և 1798 թ. Եգիպտոս ափ իջնելու էր նաև այդ վարչակարգի բանակը։", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["Մեծ Կաբիլիայի անկումը. Լալա Ֆաթմա Ն'Սումերի գերությունը", "0f61ff08"], "d": ["TDV-ի «Ալժիր» հոդվածը գրառում է, որ լեռնային Կաբիլիայի (Bilâdü'l-kabâil) շրջանը 1853, 1854 և 1857 թվականների արշավանքների արդյունքում գրավվելով՝ Ֆրանսիայի կողմից Ալժիրի գրավման շարժումը մեծ մասամբ ավարտվեց։ 1857 թ. արշավանքը կոտրեց Թիզի Ուզուի և Ակբուի գիծը. գերի ընկավ դիմադրության խորհրդանիշ Լալա Ֆաթմա Ն'Սումերը։ Այսպիսով մարեց 1847 թ. էմիր Աբդելքադերի հանձնվելուց հետո կանգուն մնացած դիմադրության վերջին մեծ օջախը։", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["Ֆրանսիացիները գրավեցին Այն Սալահը (Թիդիքելթ)", "1e28d1d0"], "d": ["Սահարայի կենտրոնում Թիդիքելթի օազիսների խմբի կենտրոն Այն Սալահը 1899 թ. դեկտեմբերի 29-ին վերցրին ֆրանսիական ուժերը։ Սա Ալժիրի ափից հարավ իջնող ֆրանսիական ընդարձակման՝ անապատ անցնող առաջին մեծ քայլն է. երկու տարվա ընթացքում Թուաթը և Գուրարան նույն ճանապարհին են հետևելու։", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["Թուաթ · Գուրարա · Թիդիքելթ օազիսների բռնակցումը Ֆրանսիային", "d412838b"], "d": ["Ալժիրի հարավ-արևմուտքի Թուաթ, Գուրարա և Թիդիքելթ օազիսների գոտին 1901 թ. փետրվարի 21-ին պաշտոնապես կապվեց Ֆրանսիային։ Քարավանային ճանապարհների այս հանգույցը, որի նկատմամբ Մարոկկոյի սուլթանը անվանական իրավունք էր հավակնում՝ ներառյալ Ադրարը, Տիմիմունը, Ռեգգանն ու Բենի Աբբասը, այսպիսով միացավ Ալժիրին. սա է Մարոկկոյի և ֆրանսիական Ալժիրի միջև սահմանային վեճի սկիզբը։", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["Բեշարում (Կոլոմբ-Բեշար) ֆրանսիական պահակակետի հիմնումը", "4d44d252"], "d": ["Մարոկկոյի սահմանի Բեշար օազիսը 1903 թ. նոյեմբերի 11-ին վերցրին ֆրանսիական ուժերը և Colomb-Béchar անունով դարձրին առաջավոր պահակակետ։ Թուաթի գոտու բռնակցումից երկու տարի անց արված այս քայլը Ալժիրից դեպի Մարոկկո Ֆրանսիայի առաջխաղացման վերջին օղակներից է. այն ճանապարհ է բացում դեպի 1912 թ. Մարոկկոյի վրա պրոտեկտորատի հաստատումը։", "bd1a7ae2"]},
"OLAYLAR_EK16:1283-01-01:0":{"b": ["Մոսկովյան իշխանության հիմնումը. Դանիիլ I", "49549309"], "d": ["Ալեքսանդր Նևսկու կրտսեր որդի Դանիիլը սկսեց Մոսկվան կառավարել որպես անկախ իշխանություն։ Այն ժամանակ Մոսկվան Վլադիմիր-Սուզդալի հողերի փոքր և աննշան կենտրոն էր. ռուսական պատմագրությունն այս թվականը համարում է հետագա վերելքի ելակետը։", "10cf92d1"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["Կարեսիի և Համիդօղուլների բեյությունների հիմնումը", "3905da93"], "d": ["TDV-ի «Կարեսիօղուլներ» հոդվածի համաձայն՝ Կարեսի բեյը, իր հոր՝ Քալեմ բեյի մահով քայքայված սելջուկյան սահմանային կազմակերպությունում հռչակելով անկախություն, հիջ. 696 (1296-97) թվականից կենտրոն դարձրեց Բալըքեսիրը և կարճ ժամանակում Բյուզանդիայից խլեց ողջ Միսիան՝ ներառյալ Էրդեքը, Բիգան, Էդրեմիդը, Պերգամոնը։ Նույն տարում (1297) Համիդ բեյը, Ուլուբորլուն դարձնելով կառավարության կենտրոն, հիմնեց Համիդօղուլների բեյությունը. Իսպարտան, Բուրդուրը, Էղիրդիրն ու Յալվաչը քայքայվող սելջուկյան սահմանային շրջանից միացան բեյության առաջին սահմաններին։ Երկու բեյություններն էլ Արևմտյան Անատոլիայում նույն փլուզման՝ սելջուկյան կենտրոնական իշխանության քայքայման արգասիքն են։", "7d297343"]},
"OLAYLAR_EK16:1301-01-01:0":{"b": ["Մոսկովյան իշխան Դանիիլը Կոլոմնան և Սերպուխովը միացրեց Մոսկվային", "6d82dccd"], "d": ["Դանիիլը Ռյազանի իշխանությունից վերցրեց Կոլոմնան (գերի ընկած Ռյազանի իշխանը ազատ արձակվելու համար հանձնեց բերդը) և Սերպուխովը. Մոսկվան հասավ Օկա գետին, և դա եղավ Մոսկովյան իշխանության առաջին տարածքային ընդարձակումը։", "f6b7a96c"]},
"OLAYLAR_EK16:1304-01-01:0":{"b": ["Մոժայսկը վերցվեց Սմոլենսկի իշխանությունից և միացվեց Մոսկվային", "462055a0"], "d": ["Մոսկովյան իշխանությունը, Սմոլենսկից վերցնելով Մոսկվա գետի վերին ավազանի Մոժայսկը, իր արևմտյան սահմանը մոտեցրեց Լիտվային։", "3002aa5d"]},
"OLAYLAR_EK16:1307-01-01:0":{"b": ["Պոլոցկի իշխանությունը անցավ Լիտվայի Մեծ դքսությանը", "04a26a6f"], "d": ["Պոլոցկը, Վիտեբսկը և շրջակայքը մինչև 1307 թ. մնացին ռուս իշխանական հարստության ներսում. նախագեդիմինյան Լիտվայի դեպի արևելք ընդարձակումը ակնհայտ դարձավ այս անցմամբ (ատլասում պետության քարտի թվականը 1307 է. Վիտեբսկի փաստացի անցումը՝ ≈1320, վիճելի է)։", "52bf8042"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["Այդընօղուլների բեյության հիմնումը. Իզմիրի, Այասուլուքի, Թիրեի գրավումը", "69a021ae"], "d": ["TDV-ի «Այդընօղուլներ» հոդվածի համաձայն՝ Մուբարիզեդդին Ղազի Մեհմեդ բեյը, այս շրջանը վերցնելով Գերմիյանօղուլների սահմանապահ բեյ Սասա բեյից, 1308 թ. տիրեց Այդըն-իլին. Իզմիրի մուսուլմանական հատվածը գրավեց Այասուլուքի (Սելչուկ), Թիրեի և Բոդեմիայի հետ միասին։ Այասուլուքը դարձրեց նավատորմի հենակետ և իր գրաված հողերը բաժանեց հինգ որդիների միջև. հաջորդ տասնամյակներում, հատկապես նրա որդի Ումուր բեյի օրոք, բեյությունը դառնալու էր վճռորոշ ուժ Էգեյան ծովագնացության մեջ։", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["Անատոլիական Սելջուկյան պետության փաստացի վերջը. Իլխանության ուղղակի կառավարումը", "00f85ecb"], "d": ["TDV-ի «Մեսուդ II» հոդվածի համաձայն՝ երկարատև հիվանդությունից հետո հիջ. 708 (1308) թ. Կեսարիայում մահացած Գիյասեդդին Մեսուդ II-ը, ընդհանուր ընդունված տեսակետով, Անատոլիական Սելջուկյան պետության վերջին տիրակալն է. նրա մահից հետո գահին բազմեցրած թեկնածուները չարժանացան ո՛չ ներքին ատյանների, ո՛չ էլ Իլխանության ճանաչմանը։ Շրջանն արդեն Մեսուդի թագավորության ողջ ընթացքում փաստացի կառավարվում էր իլխանական պաշտոնյաների կողմից. նրա մահով այս ուղղակի կառավարումը Կոնիայի, Նիղդեի և Ակսարայի նման կենտրոններում կորցրեց նաև իր ձևական քողը։", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["Ջանդարօղուլների բեյության տարածումը Կաստամոնու-Չանքըրը-Բարթըն-Սաֆրանբոլու", "64e39ad0"], "d": ["TDV-ի «Ջանդարօղուլներ» հոդվածի համաձայն՝ բեյությունը 14-րդ դարի սկզբին Կաստամոնու-Սինոպ շրջակայքում հիմնեց Շեմսեդդին Յաման Ջանդարը, որին իլխանական տիրակալ Գեյխաթուն իբրև իքթա էր տվել Էֆլանին և շրջակայքը. աղբյուրների անբավարարության պատճառով հիմնադրման ստույգ թվականը հայտնի չէ։ Ջանդարի հաջորդ Սուլեյման բեյը հիշատակվում է որպես Չոբանօղուլների բեյությանը փոխարինած տիրակալ. այսինքն՝ Կաստամոնուի և Չանքըրըի շրջակայքը Չոբանօղուլներից, իսկ Բարթըն-Սաֆրանբոլու-Էֆլանի գիծը իլխանական ուղղակի կառավարումից անցել են Ջանդարօղուլներին։", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["Սուրբ Հովհաննեսի (հոսպիտալյան) ասպետները գրավեցին Հռոդոսը և Տասներկու կղզիները", "67885b4b"], "d": ["TDV-ի «Հռոդոս» հոդվածը գրառում է, որ կղզին 1309 թ. անցավ Սուրբ Հովհաննեսի (հոսպիտալյաններ/Իսբիթարիյե) ասպետների ձեռքը. հոսպիտալյանների ընդունված պատմությունը (տե՛ս J. Riley-Smith, The Knights Hospitaller) մանրամասնում է, որ պաշարումը սկսվել է 1306 թ. ամռանը, իսկ բյուզանդական համալրումներով երկար ժամանակ դիմադրած Հռոդոս քաղաքը Գրան Մագիստրոս Ֆուլք դե Վիլարեի ուժերի ձեռքով ընկել է միայն 1310 թ. օգոստոսի 15-ին։ Այս թվականից մինչև 1522 թ. օսմանյան գրավումը կղզին լինելու էր ասպետների կենտրոնը, իսկ շրջակա Տասներկու կղզիները նույն ընթացքում Բյուզանդիայից անցել են հոսպիտալյան տիրապետության տակ։", "c1422e2c"]},
"OLAYLAR_EK16:1313-01-01:0":{"b": ["Լիվոնյան ասպետները Լիտվայից հետ վերցրին Դյունաբուրգի բերդը", "92119516"], "d": ["Մոտ 1281 թ. լիտվացիները, վերցնելով Երսիկան, փոխանակել էին այն օրդենի Դյունաբուրգ բերդի հետ։ Բերդը 1313 թ. կրկին անցավ Լիվոնյան ասպետների ձեռքը և մնաց որպես օրդենի կոմտուրության կենտրոն։", "0cdd86e0"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["Սուրբ Հովհաննեսի ասպետները վերցրին Կոսը", "445666f7"], "d": ["TDV-ի «Իսթանքյոյ» (Կոս) հոդվածի համաձայն՝ Սուրբ Հովհաննեսի ասպետները, Հռոդոսում հաստատվելուց հետո վերցնելով նաև Կոսը (1315), նոր բերդեր կառուցեցին։ Այսպիսով կղզին անցավ ասպետական տիրապետության տակ, որը տևեց մինչև 1523 թ.. 1310 թ. Հռոդոս քաղաքի անկումից հետո Կոսը ում կառավարման տակ էր, TDV-ում մանրամասնված չէ։", "145d1bad"]},
"OLAYLAR_EK16:1325-01-01:0":{"b": ["Մետրոպոլիտի աթոռը տեղափոխվեց Մոսկվա", "d20099f8"], "d": ["Ռուս ուղղափառ եկեղեցու գլուխ մետրոպոլիտ Պյոտրը իր կրոնական կենտրոնը տեղափոխեց Մոսկվա։ Սա Մոսկվայի՝ ոչ միայն քաղաքական, այլև կրոնական կենտրոն դառնալու վերելքի սկիզբն էր և ամրապնդեց իշխանության օրինականությունը։", "4e31c42f"]},
"OLAYLAR_EK16:1330-01-01:0":{"b": ["Լիվոնյան օրդենը դարձավ Ռիգա քաղաքի սյուզերենը", "21453047"], "d": ["Լիտվայի մեծ իշխաններ Վիտենիսի և Գեդիմինասի աջակցությամբ օրդենի դեմ կռվող Ռիգայի արքեպիսկոպոսությունն ու քաղաքը 1330 թ. պարտվեցին. Լիվոնյան օրդենը դարձավ քաղաքի սյուզերենը։ 1452 թ. Սալասպիլսի պայմանագրով Ռիգան անցավ օրդենի և արքեպիսկոպոսի համատեղ սյուզերենության տակ։", "28788282"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["Էրեթնայի բեյության հիմնումը. Կենտրոնական Անատոլիան Իլխանությունից հետո", "a67bacd9"], "d": ["TDV-ի «Էրեթնաօղուլներ» հոդվածի համաձայն՝ ծագումով ույղուր իլխանական պաշտոնյա Ալաեդդին Էրեթնան, իլխանական տիրակալ Աբու Սաիդ Բահադուր խանի 1335 թ. մահից հետո, Անատոլիայում իլխանական փոխարքայությունը փաստացի վերածեց անկախ կառավարման. սկզբում հանդես գալով որպես մամլուք սուլթանի փոխանորդ՝ 1340 թ. խուտբայից հանեց մամլուքի անունը և մոտ 1341 թ. հռչակեց լիակատար անկախություն։ Բեյությունը, որի կենտրոնը նախ Սեբաստիան էր, ապա Կեսարիան, մինչև նրա մահը (1352) ստեղծեց Ամասիան, Թոքաթը, Չորումը, Նիղդեն, Ակսարայը և Երզնկան ընդգրկող ընդարձակ կենտրոնաանատոլիական իշխանություն, որին 1381 թ. վերջ դրեց Կադի Բուրհանեդդինը։", "04978a80"]},
"OLAYLAR_EK16:1335-05-01:0":{"b": ["Հաբսբուրգները տիրեցին Կրայնային և Կարինթիային (Լյուբլյանա)", "039918d3"], "d": ["1335 թ. ապրիլի 2-ին Կարինթիայի դուքս և Տիրոլի կոմս Հայնրիխ VI-ի՝ Տիրոլի ամրոցում անժառանգ մահանալով, 1330 թ. նոյեմբերի 23-ին Լյուդվիգ Բավարացու հետ գաղտնի կնքված համաձայնության հիման վրա Հաբսբուրգ եղբայրներ Ալբրեխտ II-ը և Օտտո IV-ը կայսերական հրովարտակով ստացան Կարինթիայի դքսությունը և նրան կապված Կրայնան (այսօրվա Լյուբլյանան ներառող շրջանը). Տիրոլը, սակայն, Հայնրիխի դստեր միջոցով առանձին մնաց։ Սա Ալպյան շրջանում Հաբսբուրգների ընդարձակման առաջին խոշոր քայլերից էր, և Կրայնան մինչև 1918 թ. (ընդհատումներով) մնալու էր Հաբսբուրգների/Ավստրիայի ձեռքին։", "4dbed85a"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["Ջելայիրյան պետության հիմնումը. Ատրպատականն Իլխանությունից հետո", "a13ada90"], "d": ["TDV-ի «Ջելայիրյաններ» հոդվածի համաձայն՝ իլխանական էմիր Նոյանի թոռ Հասան Բուզուրգը, օգտվելով իլխանական տիրակալ Աբու Սաիդ Բահադուր խանի մահով բռնկված գահի կռիվներից, 1340 թ. հիմնեց Թավրիզ կենտրոնով անկախ պետություն։ Այսպիսով Ջելայիրյանները դարձան Իլխանությունից հետո Ատրպատականում և շրջակայքում առաջացած դատարկությունը լրացրած առաջին խոշոր հարստությունը. նրա հաջորդ Ուվեյսի օրոք (1356-1374) նրա տարածքները ընդարձակվելու էին մինչև Մոսուլ և Դիարբեքիր։", "224cbb81"]},
"OLAYLAR_EK16:1341-01-01:0":{"b": ["Հիմնվեց Նիժնի Նովգորոդ-Սուզդալի մեծ իշխանությունը. խանը յառլիկ տվեց Կոնստանտին Վասիլևիչին", "c69f5198"], "d": ["Ոսկե Հորդայի խան Ուզբեկը (պետության քարտում՝ Ուզբեկ/Ջանիբեկ) Սուզդալի իշխան Կոնստանտին Վասիլևիչին տվեց Նիժնի Նովգորոդ-Գորոդեցի իշխանությունը. իշխանությունը դարձավ Մոսկվայի մրցակիցը և 1392 թ. Վասիլի I-ի կողմից միացվեց Մոսկվային։", "4b281b04"]},
"OLAYLAR_EK16:1346-01-01:0":{"b": ["Դանիան Հյուսիսային Էստլանդիան (Ռևելը և Նարվան) վաճառեց Լիվոնյան օրդենին", "6861ba55"], "d": ["Դանիական թագավորությունը Լիվոնյան օրդենին վաճառեց Հյուսիսային Էստլանդիայի իր հողերը՝ Ռևելի և Նարվայի հետ միասին։ Շրջանը մինչև Լիվոնյան պատերազմը մնաց օրդենի ձեռքին։", "0723514c"]},
"OLAYLAR_EK16:1348-01-01:0":{"b": ["Բոլոտովոյի պայմանագիրը. Նովգորոդը ճանաչեց Պսկովի անկախությունը", "08eca44d"], "d": ["Նովգորոդը Պսկովին ճանաչեց որպես «կրտսեր եղբայր». Պսկովը իր վեչեով և պոսադնիկներով ապրեց որպես անկախ քաղաք-հանրապետություն, մինչև 1510 թ. միացավ Մոսկվային։", "12f9ce2f"]},
"OLAYLAR_EK16:1392-01-01:0":{"b": ["Վասիլի I-ը Նիժնի Նովգորոդ-Սուզդալի իշխանությունը միացրեց Մոսկվային", "5ecf441b"], "d": ["Թոխթամիշ խանից ստացած յառլիկով Վասիլի I-ը Նիժնի Նովգորոդը, Գորոդեցը և Սուզդալը կապեց Մոսկվային. սկսվեց Մոսկվայի ելքը Վոլգայի և Օկայի ավազան։", "ac83ac55"]},
"OLAYLAR_EK16:1404-01-01:0":{"b": ["Վիտաուտասը վերցրեց Սմոլենսկը. Սմոլենսկի իշխանությունը միացավ Լիտվային", "1a68300c"], "d": ["Վիտաուտասը գրավեց Սմոլենսկը. քաղաքը մնաց Լիտվայի Մեծ դքսության կազմում, մինչև 1514 թ. անցավ Մոսկվային։", "3ed5ce14"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["Բաղդադի անցումը Կարա Կոյունլուների ձեռքը. Ջելայիրյան սուլթան Ահմեդի պարտությունը", "a42ebe92"], "d": ["TDV-ի «Կարա Կոյունլուներ» հոդվածի համաձայն՝ Կարա Յուսուֆը հիջ. 813 թ. Ռաբի աս-սանի ամսի 28-ին (1410 թ. օգոստոսի 30) Թավրիզի մոտ ծանր պարտության մատնեց Ջելայիրյան սուլթան Ահմեդին. սուլթան Ահմեդի մահից հետո, հիջ. 814 (1411) թ., իր որդի Փիր Բուդաղին Թավրիզում սուլթան հռչակեց, և նույն տարում նրա ավագ որդի Շահ Մեհմեդը գրավեց Բաղդադը։ Այսպիսով, մոտ մեկ դար Ջելայիրյանների մայրաքաղաք եղած Բաղդադը, շրջակա Բասրա-Մոսուլ-Քիրքուք գծի հետ միասին, անցավ Կարա Կոյունլուների տիրապետության տակ։", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["Երզնկան և Կամախը անցան Ակ Կոյունլուներին. Կարայուլուք Օսման բեյ", "122460d4"], "d": ["Կարա Յուսուֆի մահից հետո, Երզնկայի բնակչության խնդրանքով, Մութահհարթենի թոռ Յար Ալին դարձել էր քաղաքի կուսակալը։ Նրա օրոք Ակ Կոյունլու բեյ Կարայուլուք Օսմանը վերցրեց Երզնկան և միացրեց Ակ Կոյունլուների հողերին։ Այս թվականից հետո Երզնկան դարձավ մի վայր, որ ձեռքից ձեռք էր անցնում մերթ Ակ Կոյունլուների և Կարա Կոյունլուների, մերթ Ակ Կոյունլու շահզադեների միջև։", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["Կազանի խանության հիմնումը. Ուլուղ Մուհամմեդ խանի հեռանալը Ոսկե Հորդայից", "335a7408"], "d": ["TDV-ի «Կազանի խանություն» հոդվածի համաձայն՝ Ոսկե Հորդայի մայրաքաղաք Սարայում գահը կորցրած Ուլուղ Մուհամմեդ խանը իր ընտանիքով և մոտ 3000 զինվորով նախ քաշվեց Բելյով, 1437-1438 թվականներին կռվեց ռուսական իշխան Վասիլի II-ի դեմ, ապա հաստատվեց Կազան քաղաքում. տեղի բնակչության աջակցությամբ այստեղ դրեց նոր խանության հիմքերը։ TDV-ն նշում է, որ հիմնադրման ընթացքն ավարտվեց 1437-1445 թվականներին, և 1445-ից խանությունը ձեռք բերեց լիակատար անկախ կարգավիճակ. քարտեզը որպես հիմք է ընդունում այս ընթացքի սկիզբը՝ 1438 թ., երբ Ուլուղ Մուհամմեդը հաստատվեց Կազանում։", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["Ղրիմի խանության հիմնումը. Հաջի Գիրեյի անկախացումը Ոսկե Հորդայից", "5728223e"], "d": ["TDV-ի «Ղրիմ» հոդվածի համաձայն՝ Ղրիմի խանությունը երևան եկավ որպես 14-րդ դարի երկրորդ կեսին Ոսկե Հորդայի՝ գահի կռիվներով մասնատման արգասիք. խանության իրական հիմնադիր Հաջի Գիրեյի հատած ամենահին դրամը կրում է հիջ. 845 (1441-42) թվականը, և դա համարվում է խանության պաշտոնական հիմնադրման թվականը։ Նույն տարում Հաջի Գիրեյը, բարեկամություն հաստատելով Մոսկվայի հետ, ամրապնդեց իր դիրքը Ղրիմում, և տեղական բեյական ընտանիքները, հատկապես Շիրին ցեղախումբը, անցան նրա կողմը։", "dbd052d0"]},
"OLAYLAR_EK16:1450-01-01:0":{"b": ["Ջահան Շահը վերցրեց Երզնկան. Կարա Կոյունլուների տիրապետությունը", "0c928cc4"], "d": ["Կարա Կոյունլու տիրակալ Ջահան Շահը հիջ. 854 (1450) թ. բանակ ուղարկեց Երզնկա և քաղաքը վերցրեց Ակ Կոյունլուներից։ Այս կորուստը պատճառ դարձավ, որ Ակ Կոյունլու բեյ Ջհանգիր Միրզայի և նրա եղբոր՝ Հասան բեյի (Ուզուն Հասան) միջև գժտություն առաջանա։", "203c5c2e"]},
"OLAYLAR_EK16:1452-01-01:0":{"b": ["Կարա Կոյունլու Ջահան Շահի կողմից թեմուրյան Իրանի (Ռեյ, Սպահան, Ֆարս, Քերման) գրավումը", "c6fbb3f5"], "d": ["TDV-ի «Կարա Կոյունլուներ» հոդվածի համաձայն՝ Կարա Կոյունլու տիրակալ Ջահան Շահը, օգտվելով թեմուրյան արքայազների միջև գահի պայքարից, հիջ. 856-857 (1452-1453) թվականներին իր կառավարման տակ առավ Ռեյ, Սպահան, Ֆարս և Քերման նահանգները. սա Շահռուխ Միրզայի 1447 թ. մահից հետո սկսված և Սուլթանիե-Ղազվինի բռնակցմամբ բացված ընդարձակման ընթացքի գագաթնակետն է։ Այսպիսով թեմուրյանների հարավային-կենտրոնական Իրանի հողերն անցան Կարա Կոյունլուներին. Ջահան Շահի իշխանությունը 1466 թ. հասնելու էր այնպիսի ընդարձակության, որ ընդգրկելու էր Ատրպատականը, Առանը, Իրաք-ի Աջեմը, Իրաք-ի Արաբը, Ֆարսը, Քերմանը և Արևելյան Անատոլիան։", "3f6a6c37"]},
"OLAYLAR_EK16:1452-10-23:0":{"b": ["Անգլիան հետ վերցրեց Բորդոն. Ջոն Թալբոտի Գասկոնյան վերջին արշավանքը", "01b2b7be"], "d": ["1451 թ. ֆրանսիացիներին կորցրած Բորդոն, բնակչության՝ ֆրանսիական կայազորի դեմ ապստամբելով և դարպասները բացելով, 1452 թ. հոկտեմբերի 22-23-ի գիշերը հանձնվեց տարեց հրամանատար Ջոն Թալբոտի գլխավորած անգլիական բանակին. սա Հարյուրամյա պատերազմում Գասկոնիայում Անգլիայի վերջին և կարճատև հաղթանակն էր։ Բորդոն մեկ տարի անց՝ Կաստիյոնի ճակատամարտից հետո, ընդմիշտ վերադառնալու էր Ֆրանսիային։", "f6945d27"]},
"OLAYLAR_EK16:1453-10-19:0":{"b": ["Բորդոյի վերջնական վերադարձը Ֆրանսիային. Հարյուրամյա պատերազմի փաստացի վերջը", "b0a86f6c"], "d": ["1453 թ. հուլիսի 17-ին Կաստիյոնի ճակատամարտում Ջոն Թալբոտի մահով և նրա բանակի ոչնչացմամբ Գասկոնիայում անգլիական դիմադրությունը փլուզվեց. պաշարված Բորդոն 1453 թ. հոկտեմբերի 19-ին հանձնվեց ֆրանսիական ուժերին։ Այս հանձնումը համարվում է 116 տարի տևած Հարյուրամյա պատերազմի փաստացի ավարտի պահը (պաշտոնական խաղաղության պայմանագիր երբեք չստորագրվեց) և մայրցամաքային Եվրոպայում Անգլիայի տիրապետությունը նեղացրեց մինչև Կալե։", "1c632d46"]},
"OLAYLAR_EK16:1457-01-01:0":{"b": ["Ուզուն Հասանը հետ վերցրեց Երզնկան. կրկին Ակ Կոյունլու", "550d010a"], "d": ["Ուզուն Հասանը, հաղթելով Կարա Կոյունլուներին, Երզնկան կրկին վերցրեց Ակ Կոյունլուների տիրապետության տակ։ Քաղաքը 1473 թ. Օթլուքբելիի ճակատամարտից հետո էլ մնաց Ակ Կոյունլուների սահմաններում։", "d778fa85"]},
"OLAYLAR_EK16:1466-10-19:0":{"b": ["Տորունի երկրորդ պայմանագիրը. Դանցիգը (Գդանսկ) և Արևմտյան Պրուսիան կապվեցին Լեհաստանին", "e2152dae"], "d": ["1454 թ. Պրուսական կոնֆեդերացիայի՝ Տևտոնական օրդենի կառավարման դեմ ապստամբությամբ սկսված Տասներեքամյա պատերազմին վերջ դրած Տորունի (Thorn) երկրորդ պայմանագիրը ստորագրվեց 1466 թ. հոկտեմբերի 19-ին. ասպետները Լեհաստանի թագավորությանը թողեցին Դանցիգը (Գդանսկ) ներառող Արևելյան Պոմերանիան, Էլբլոնգը (Elbing) ներառող Վիստուլայի գետաբերանը և Կուլմի շրջանը. այս հողերը ստացան «Արքայական Պրուսիա» անունը։ Իսկ Արևելյան Պրուսիան մինչև 1525 թ. մնալու էր ասպետներին։", "831685a9"]},
"OLAYLAR_EK16:1474-01-01:0":{"b": ["Իվան III-ը գնեց Ռոստովի իշխանության մնացած կեսը", "5203244f"], "d": ["Ռոստովի իշխանների ձեռքի կեսը փոխանցվեց Մոսկվային. 1332 թ. Մոսկվային անցած մյուս կեսի հետ միասին Ռոստովի երկիրը լիովին կապվեց Մոսկվային։", "ab0eeae6"]},
"OLAYLAR_EK16:1485-09-12:0":{"b": ["Տվերի մեծ իշխանությունը միացավ Մոսկվային. Իվան III-ը վերցրեց քաղաքը", "fa3f924e"], "d": ["Մոսկովյան բանակի պաշարման դեմ Տվերի վերջին մեծ իշխան Միխայիլ Բորիսովիչը փախավ Լիտվա, և Տվերը հանձնվեց Իվան III-ին. այսպիսով վերացավ Մոսկվայի ամենաուժեղ մրցակիցը։", "b9942526"]},
"OLAYLAR_EK16:1489-02-26:0":{"b": ["Թագուհի Կատերինա Կորնարոն Կիպրոսը հանձնեց Վենետիկին. խաչակրաց պետության վերջը", "e24d3f3a"], "d": ["1473 թ. ամուսնու՝ Ժակ II թագավորի մահից հետո որպես թագուհի-խնամակալ Կիպրոսը կառավարող վենետիկուհի Կատերինա Կորնարոն, ժառանգ չունենալու պատճառով Վենետիկի կառավարության ճնշման տակ, 1489 թ. փետրվարի 26-ին հրաժարվեց գահից և կղզու նկատմամբ իր տիրակալական իրավունքները փոխանցեց դոժին և Վենետիկի Հանրապետությանը. փոխարենը պահպանեց թագուհու տիտղոսը և ստացավ Ասոլոյի կոմսությունը Տերրաֆերմայում։ Այս հանձնմամբ ավարտվեց 1192 թվականից տևող Լուսինյան հարստության իշխանությունը և վերջին խաչակրաց պետությունը. կղզին մինչև 1570-71 թթ. օսմանյան գրավումը մնաց վենետիկյան կառավարման տակ։", "7f769951"]},
"OLAYLAR_EK16:1492-01-02:0":{"b": ["Գրանադայի անկումը. Պիրենեյան թերակղզու վերջին մուսուլմանական պետության վերջը", "46e5201b"], "d": ["Տասը տարի տևած փուլային պաշարումից և ներքին պառակտումներից թուլացած Գրանադայի Նասրյան ամիրայության վերջին տիրակալ Աբու Աբդալլահը (Բոաբդիլ), 1491 թ. նոյեմբերին ստորագրված առատաձեռն հանձնման պայմանների (Գրանադայի կապիտուլյացիաներ) համաձայն, 1492 թ. հունվարի 2-ին քաղաքի բանալիները հանձնեց կաթոլիկ միապետներ Ֆերնանդոյին և Իզաբելային. Ալհամբրայից հեռացած Բոաբդիլից հետո ավարտվեց Պիրենեյան թերակղզու վերջին մուսուլմանական պետությունը, և Ռեկոնկիստան ամբողջացավ։ Նույն տարում հետևելու էին հրեաների արտաքսումը (մարտ) և Քրիստափոր Կոլումբոսի ճամփորդությունը (օգոստոս)։", "5dc28ef8"]},
"OLAYLAR_EK16:1500-07-14:0":{"b": ["Վեդրոշայի ճակատամարտը. Մոսկվան ջախջախեց Լիտվայի բանակը. Բրյանսկի և Սևերսկի հողերը մնացին Մոսկվային", "d3f61400"], "d": ["1500-1503 թթ. մոսկովա-լիտվական պատերազմում Դանիիլ Շչենյայի հրամանատարությամբ մոսկովյան բանակը Դորոգոբուժի մոտ Վեդրոշա գետի վրա ջախջախեց հեթման Կոնստանտին Օստրոժսկու բանակը և գերեց հեթմանին։ Նույն տարվա գարնանը վերցված Բրյանսկն ու Սևերսկի քաղաքները մնացին Մոսկվայի ձեռքին. պատերազմի վերջում Լիտվայի հողերի մոտ մեկ երրորդը անցել էր Մոսկվային։", "e5879803"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["Շեյբանի խանը Թեմուրյաններից վերցրեց Հերաթն ու Խորասանը", "a81d8575"], "d": ["TDV-ի «Շեյբանի խան» հոդվածի համաձայն՝ ուզբեկ տիրակալ Շեյբանի խանը, 1503-1505 թվականներին վերցնելով Անդիժանը, Ֆերղանան, Հիսարը, Ղունդուզը և Բալխը, հիջ. 913 (1507) թ. գրավեց նաև Թեմուրյանների մայրաքաղաք Հերաթը. Encyclopaedia Iranica-ի «Խորասան» հոդվածը տալիս է այս նվաճման ճշգրիտ թվականը. քաղաքն ընկավ հիջ. 913 թ. Մուհառամ ամսի 8-ին (1507 թ. մայիսի 20), իսկ մեկ շաբաթ անց՝ Մուհառամի 15-ին (մայիսի 27), Շեյբանի խանի անունով խուտբա կարդացվեց, և նվաճումը պաշտոնականացավ։ Ողջ Խորասանը, ներառյալ Մաշհադը, նույն տարում Թեմուրյաններից անցավ Շեյբանյաններին. սա նշանակում էր, որ Թեմուրյան հարստությունը, Մավերաննահրից հետո, կորցրեց նաև Իրանում իր վերջին մեծ ամրոցը։", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["Օրանի անկումը Իսպանիայի ձեռքը. կարդինալ Սիսներոսի հյուսիսաֆրիկյան արշավանքը", "86ed8ac1"], "d": ["Արևմտյան Միջերկրականի ծովային ճանապարհը վերահսկող և Թլեմսենի նավահանգիստ Վահրանը (Օրան) աճել էր 1492 թ. Գրանադայից փախած անդալուզիացի մուսուլմանների և հրեաների ապաստանմամբ։ 16-րդ դարի սկզբին Մաղրիբի ափի նավահանգստային քաղաքները մեկ առ մեկ վերցրած Կաստիլիայի թագավորությունը 1509 թ. մայիսի 17-ին գրավեց Վահրանը. բնակչության մեծ մասը կոտորվեց, մնացածները գերի ընկան, և քաղաքում մուսուլման ու հրեա բնակչություն չմնաց։ Իսպանացիները ընդարձակեցին պարիսպներն ու բերդերը. Վահրանը մինչև 1708 թ. մնաց Իսպանիայի ձեռքին։", "be7b3b1b"]},
"OLAYLAR_EK16:1514-08-01:0":{"b": ["Սմոլենսկը հանձնվեց Մոսկվային. Վասիլի III-ը մտավ քաղաք", "46c61446"], "d": ["1512-1522 թթ. մոսկովա-լիտվական պատերազմի երրորդ պաշարման ժամանակ լիտվական կայազորը անձնատուր եղավ հուլիսի 31-ին. մոսկովյան բանակը օգոստոսի 1-ին հանդիսավոր մտավ քաղաք, և բնակչությունը հավատարմության երդում տվեց Վասիլի III-ին։ Սմոլենսկը Վասիլիի ամենամեծ ձեռքբերումն է արևմուտքում. մի քանի շաբաթ անց Օրշայում կրած պարտությունը քաղաքը հետ չվերադարձրեց։", "803c9255"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["Ստորին Երկրների կապումը Իսպանիայի թագին. Ֆերդինանդի մահը, Կարլոս V-ի գահակալումը", "fbe0dbd2"], "d": ["1516 թ. հունվարի 23-ին Արագոնի թագավոր Ֆերդինանդ II-ի մահով նրա թոռ Կարլոս V-ը, որը 1506 թվականից իբրև Բուրգունդիայի դուքս արդեն կառավարում էր Ստորին Երկրները (այսօրվա Բելգիա-Նիդերլանդներ-Լյուքսեմբուրգ և հյուսիսային Ֆրանսիայի մի մասը), դարձավ նաև Կաստիլիայի և Արագոնի գահերի ժառանգորդը և 1516 թ. մարտի 14-ին Բրյուսելում հռչակվեց Իսպանիայի թագավոր։ Այսպիսով այս հողերը, անձնական ունիայի միջոցով, սկսեցին համարվել ոչ թե Հաբսբուրգների գերմանա-ավստրիական ճյուղին, այլ ուղղակի Իսպանիայի թագին կապված. 1519 թ., երբ Կարլոս V-ը ընտրվեց Սրբազան Հռոմեական կայսր, այս երկու ինքնությունները (Իսպանիայի թագավոր և գերմանա-հռոմեական կայսր) միավորվելու էին մեկ անձի մեջ, իսկ շրջանի կապվածությունը Իսպանիային տևելու էր մինչև 1556 թ., երբ Կարլոս V-ը գահից հրաժարվեց և ժառանգությունը թողեց որդուն՝ Ֆիլիպ II-ին։", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["Դեմաքի սուլթանությունը տապալեց Մաջապահիթը և տիրեց Ճավայի ափին", "7da602b5"], "d": ["TDV-ի «Դեմաք» հոդվածի համաձայն՝ Ճավայի առաջին անկախ մուսուլմանական պետությունը՝ Դեմաքի սուլթանությունը, 15-րդ դարի վերջին քառորդում հիմնեց Ռադեն Պաթահը. ըստ ճավայական աղբյուրների՝ փլուզվող հինդու-բուդդայական Մաջապահիթ թագավորությունը վերացավ Դեմաքի հարձակումներով։ 1527 թ. Դեմաքը գրավեց Թուբանը, որը չինական աղբյուրները 11-րդ դարից հիշատակում էին որպես Մաջապահիթի տիրակալների կարևոր նավահանգիստ. սա այն տարին է, երբ Մաջապահիթի վերջին մնացորդներն էլ կապվեցին Դեմաքին, և Ճավայի մեծ մասի իսլամացման ընթացքի շրջադարձային կետն է։", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["Նորվեգիայի իջեցումը Դանիայի թագին ենթակա նահանգի", "8e2f274e"], "d": ["Դանիայի թագավոր Քրիստիան III-ը 1536 թ. թագադրման կանոնագրում (håndfæstning) հայտարարեց, որ Նորվեգիան այլևս առանձին թագավորություն չի համարվելու, կառավարվելու է որպես Դանիայի նահանգ, և Նորվեգիայի Պետական խորհուրդը (riksråd) լուծարվում է. այս որոշումը փաստացի դարձավ 1537 թ.՝ Դանիայի եկեղեցական կանոնագիրքը Նորվեգիայում էլ կիրառելով, և կոտրվեց արքեպիսկոպոս Օլավ Էնգելբրիկտսոնի դիմադրությունը։ Թեև Նորվեգիան գործնականում որոշ ժամանակ դեռ պահպանեց իր օրենքներն ու հաստատությունները, նրա քաղաքական կարգավիճակն այլևս ոչ թե անկախ թագավորություն էր, այլ Դանիայի թագին ենթակա նահանգ. այս վիճակը տևելու էր մինչև 1814 թ.։", "a8c9dee7"]},
"OLAYLAR_EK16:1558-05-01:0":{"b": ["Ռուսները վերցրին Նարվան. Լիվոնյան պատերազմի առաջին խոշոր քաղաքը", "c21130d7"], "d": ["Իվան IV-ի բանակները վերցրին Նարվան. Ռուսաստանը ելք ստացավ դեպի Բալթյան ափ։ Նարվան մնաց ռուսական ձեռքին, մինչև 1581 թ. անցավ Շվեդիային։", "8057148b"]},
"OLAYLAR_EK16:1558-07-01:0":{"b": ["Ռուսները վերցրին Դորպատը (Տարտու)", "f941a504"], "d": ["Ռուսական բանակները 1558 թ. ամառային արշավանքում վերցրին Դորպատը (Տարտու) և շրջակա բերդերը. քաղաքը մնաց ռուսական կառավարման տակ մինչև 1582 թ. Յամ Զապոլսկու զինադադարը։", "35503ef9"]},
"OLAYLAR_EK16:1561-06-01:0":{"b": ["Ռևելը (Տալլին) անցավ Շվեդիայի հովանու ներքո. Հյուսիսային Էստլանդիան անցավ Շվեդիային", "3c183267"], "d": ["Լիվոնյան կոնֆեդերացիայի ցրման ժամանակ Ռևելի քաղաքային խորհուրդը 1561 թ. հավատարմություն հայտնեց Շվեդիայի թագավոր Էրիկ XIV-ին. Հյուսիսային Էստլանդիան մնաց Շվեդիայում մինչև Հյուսիսային մեծ պատերազմը (1721)։", "cb752659"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["Վիլնյուսի պայմանագիրը. Լիվոնյան կոնֆեդերացիան ցրվեց, Կուրլանդիան և Լիվոնիան կապվեցին Լեհաստան-Լիտվային (բացի Ռիգա քաղաքից)", "d1ceaad5"], "d": ["Լիվոնյան պատերազմի ժամանակ ռուսական ճնշման տակ ցրվող Լիվոնյան կոնֆեդերացիայի վերջին մեծ մագիստրոս Գոթհարդ Կետլերը 1561 թ. նոյեմբերի 28-ին Վիլնյուսում ստորագրված պայմանագրով (Pacta Subiectionis) անցավ Լիտվայի մեծ իշխան և Լեհաստանի թագավոր Սիգիզմունդ II Օգոստոսի հովանու ներքո. Լիվոնիայի մեծ մասը, բացի Ռիգա քաղաքից, կապվեց Լեհաստան-Լիտվային, իսկ Կետլերը դարձավ Կուրլանդիայի դքսության առաջին դուքսը։ Սա Լիվոնյան ասպետական օրդենի՝ միջնադարից նոր ժամանակներ անցման վերջին արարն էր։", "bcd4efe9"]},
"OLAYLAR_EK16:1581-01-01:0":{"b": ["Շվեդիան Նարվան վերցրեց Ռուսաստանից", "5a7f7a6a"], "d": ["Լիվոնյան պատերազմի վերջին տարիներին շվեդական ուժերը վերցրին 1558 թվականից ռուսական ձեռքում գտնվող Նարվան. քաղաքը մինչև 1704 թ. մնաց Շվեդիայում։", "5fee4227"]},
"OLAYLAR_EK16:1581-01-01:1":{"b": ["Ազատ քաղաք Ռիգան կապվեց Լեհաստան-Լիտվային", "77dba329"], "d": ["Լիվոնյան պատերազմի ամբողջ ընթացքում ազատ քաղաք մնացած Ռիգան 1581 թ. կապվեց Լեհաստան-Լիտվա միությանը. քաղաքը մնաց միության կազմում, մինչև 1621 թ. անցավ Շվեդիային։", "ecdf652d"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["Հրաժարման ակտ (Plakkaat van Verlatinghe). Հոլանդիան հռչակեց իր անկախությունը Իսպանիայից", "a632aaee"], "d": ["Ութսունամյա պատերազմի ընթացքում Ուտրեխտի միությանը կապված հոլանդական նահանգների Գեներալ շտատները (Staten-Generaal) 1581 թ. հուլիսի 26-ին ընդունած Հրաժարման ակտով Իսպանիայի թագավոր Ֆիլիպ II-ին հայտարարեցին «բռնակալ» և մերժեցին հավատարմությունը նրան. այս փաստաթուղթը փաստացի համարվում է անկախ Միացյալ նահանգների (Հոլանդական Հանրապետության) հիմնադրման հռչակագիրը։ Իսպանիայի վերջնական ճանաչումը պետք է սպասեր 1648 թ. Վեստֆալիային, բայց փաստացի խզումը այս օրն է։", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["Սմոլենսկի անկումը Լեհաստան-Լիտվայի ձեռքը. 20-ամսյա պաշարման ավարտը", "4e9678e3"], "d": ["Խառնակության շրջանում (Սմուտա) Լեհաստանի թագավոր Սիգիզմունդ III-ի բանակը, 1609 թ. սեպտեմբերից պաշարելով Սմոլենսկը, 1611 թ. հունիսի 13-ին մեկ ական պայթեցնելով ճեղք բացեց պարիսպներում և գրավեց քաղաքը. 20-ամսյա դիմադրությունն ավարտվեց։ Սմոլենսկը մինչև 1654 թ. մնաց Լեհաստան-Լիտվայի կազմում, և այս անկումը հող նախապատրաստեց յոթ տարի անց կնքվելիք Դեուլինոյի զինադադարի (1618) համար։", "25d6488d"]},
"OLAYLAR_EK16:1611-07-16:0":{"b": ["Շվեդական բանակը վերցրեց Նովգորոդը. Խառնակության շրջանում հյուսիս-արևմտյան Ռուսաստանը անցավ շվեդական վերահսկողության տակ", "a8ab28bb"], "d": ["Յակոբ Դե լա Գարդիի շվեդական բանակը վերցրեց Նովգորոդը. քաղաքը մինչև 1617 թ. շվեդական հովանու ներքո գտնվող «Նովգորոդյան պետության» մայրաքաղաքն էր, ցարի թեկնածու առաջադրվեց Կարլ Ֆիլիպը։", "281592c2"]},
"OLAYLAR_EK16:1617-03-09:0":{"b": ["Ստոլբովոյի պայմանագիրը. Ռուսաստանը Բալթյան ափը (Ինգրիա) զիջեց Շվեդիային", "175dc175"], "d": ["Ինգրիական պատերազմին վերջ դրած Ստոլբովոյի պայմանագիրը ստորագրվեց 1617 թ. փետրվարի 27-ին Լադոգա լճի հարավում գտնվող Ստոլբովո գյուղում. Ռուսաստանը հետ ստացավ Նովգորոդը և հյուսիսային այլ հողերը, իսկ Շվեդիան իր ձեռքում պահեց Կարելիան և Ինգրիան (Էստլանդիայի և Ֆինլանդիայի միջև, ներառյալ Իվանգորոդ, Յամ, Կոպորյե, Օրեշեկ բերդերը), և Ռուսաստանի անմիջական ելքը դեպի Բալթիկ կտրվեց։ Այս կտրվածքը տևելու էր մինչև 1703 թ., երբ Պետրոս Մեծը նույն շրջանում հիմնեց Սանկտ Պետերբուրգը։", "7e70e3e6"]},
"OLAYLAR_EK16:1617-03-09:1":{"b": ["Ստոլբովոյի պայմանագիրը. Ռուսաստանը Ինգերմանլանդիան թողեց Շվեդիային, Նովգորոդը վերադարձվեց", "e0bcbc7a"], "d": ["Ռուսաստանը Շվեդիային թողեց Նևայի շրջանը և Կարելիայի մի մասը (Յամ, Կոպորյե, Իվանգորոդ, Օրեշեկ) և կտրվեց Բալթյան ափից. Շվեդիան վերադարձրեց Նովգորոդը։ Այս վիճակը տևեց մինչև Պետրոս I-ի Հյուսիսային մեծ պատերազմը։", "bf517525"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["Դեուլինոյի զինադադարը. Սմոլենսկը, Չերնիգովը և Նովգորոդ-Սևերսկը թողնվեցին Լեհաստանին", "6880d2c1"], "d": ["1609-1618 թթ. լեհ-ռուսական պատերազմին վերջ դրած Դեուլինոյի զինադադարը ստորագրվեց 1618 թ. դեկտեմբերի 11-ին և ապահովեց 14,5-ամյա զինադադար. Ռուսաստանը ստիպված էր Լեհաստան-Լիտվա միությանը թողնել Սմոլենսկը (բացի Վյազմայից) և Չերնիգովի ու Նովգորոդ-Սևերսկի շրջանների 29 քաղաքները. դա Խառնակության շրջանի (Սմուտա) ամենածանր տարածքային կորուստն էր։ Շրջանը մինչև 1667 թ. Անդրուսովոյի զինադադարը մնալու էր Լեհաստանում։", "5c52de5a"]},
"OLAYLAR_EK16:1625-01-01:0":{"b": ["Շվեդիան Տարտուն (Դորպատ) վերցրեց Լեհաստանից. Լիվոնյան արշավանքի երկրորդ փուլը", "46b7c86a"], "d": ["Գուստավ II Ադոլֆը 1625 թ. արշավանքում նվաճեց Հարավային Էստլանդիան և Հյուսիսային Լիվոնիան. Տարտուն դարձավ շվեդական քաղաք, ուր 1632 թ. հիմնվելու էր Գուստավ Ադոլֆի ակադեմիան։", "b58d9bd1"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["Պերեյասլավի ռադան. Զապորոժյան կազակները հավատարմության երդում տվեցին ռուս ցարին", "bcd8f8ef"], "d": ["1648 թվականից Լեհաստան-Լիտվայի դեմ ապստամբած Զապորոժյան կազակների հեթման Բոհդան Խմելնիցկին 1654 թ. հունվարի 18-ի (հուլյան հունվարի 8) Պերեյասլավի ռադայում, որին մասնակցեց Մոսկվայից Վասիլի Բուտուրլինի գլխավորությամբ ժամանած պատվիրակությունը, հավատարմության երդում տվեց ցար Ալեքսեյ I Միխայլովիչին. սա համարվում է Ուկրաինական կազակական հեթմանության՝ Ռուսաստանի հովանու ներքո անցնելու սկիզբը և Չերնիգով-Սևերսկ շրջանի փաստացի վերահսկողությունը Լեհաստանից տեղափոխեց Ռուսաստան. պաշտոնական սահմանը, սակայն, գծվելու էր 1667 թ. Անդրուսովոյի զինադադարով։", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["Ռուսաստանը հետ վերցրեց Սմոլենսկը", "bf0eca92"], "d": ["1654 թ. սկսված լեհ-ռուսական պատերազմի ժամանակ ռուսական բանակը, հուլիսից պաշարած Սմոլենսկը, 1654 թ. հոկտեմբերի 3-ին լեհական կայազորի անձնատուր լինելով հետ վերցրեց. 1611 թ. Լեհաստանին կորցրած քաղաքը 43 տարի անց վերադարձավ Ռուսաստանին։ Սա Խառնակության շրջանի կորուստները շրջելու ռուսական ընթացքի ամենակարևոր քայլերից մեկն էր և կայունացավ 1667 թ. Անդրուսովոյի զինադադարով։", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["Անդրուսովոյի զինադադարը. Կիևը և Ձախափնյա Ուկրաինան անցան Ռուսաստանին", "799be067"], "d": ["1654-1667 թթ. լեհ-ռուսական պատերազմին վերջ դրած Անդրուսովոյի զինադադարը ապահովեց 13,5-ամյա զինադադար. Ռուսաստանը ստացավ Սմոլենսկը, Չերնիգով-Սևերսկ շրջանը, Դնեպրի ձախ ափի Ուկրաինան և — սկզբում երկու տարով, իսկ փաստացի ընդմիշտ — Կիև քաղաքը։ Այս պայմանագիրը դրեց Դնեպրի երկայնքով ուկրաինական հողերի՝ Լեհաստանի և Ռուսաստանի միջև բաժանման (և Կիևի՝ Ռուսաստանում մնալու) իրավական հիմքը։", "94445e3a"]},
"OLAYLAR_EK16:1702-10-22:0":{"b": ["Ռուսաստանը Նյոտեբորգը (Օրեշեկ) վերցրեց Շվեդիայից. Հյուսիսային մեծ պատերազմի առաջին Նևայի բերդը", "28d180eb"], "d": ["Պետրոս I-ի բանակները, պաշարելով Լադոգայի ելքի Նյոտեբորգը (ռուսերեն Օրեշեկ), վերցրին այն և անվանեցին Շլիսելբուրգ («Բանալի բերդ»). դա բացեց ճանապարհը դեպի Նևա և 1703 թ. Սանկտ Պետերբուրգի հիմնումը։", "3017c2be"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["Սանկտ Պետերբուրգի հիմնումը. Ռուսաստանի՝ Արևմուտք բացվող լուսամուտը", "ba196be0"], "d": ["Հյուսիսային մեծ պատերազմի ժամանակ Շվեդիայից նոր հետ վերցրած Նևայի դելտայի Նապաստակների կղզում Պետրոս Մեծը 1703 թ. մայիսի 16/27-ին դրեց Պետրոպավլովսկի բերդի (Պետրոս-Պողոս բերդ) հիմքը. այս օրը ընդունված է Սանկտ Պետերբուրգ քաղաքի հիմնադրման օր։ Պետրոսը ճահճոտ դելտան մտածեց որպես Արևմուտք բացվող «լուսամուտ», և քաղաքը 1712 թ. դարձավ Ռուսաստանի նոր մայրաքաղաքը. շրջանը պաշտոնապես կապվելու էր Ռուսաստանին 1721 թ. Նիշտադտի պայմանագրով։", "24c24aaf"]},
"OLAYLAR_EK16:1708-09-29:0":{"b": ["Անգլո-հոլանդական ուժերը գրավեցին Մինորկան", "3ca66a83"], "d": ["Իսպանական ժառանգության պատերազմի ժամանակ ավստրիական էրցհերցոգ Կարլ VI-ի դաշնակից անգլո-հոլանդական ուժերը գեներալ Ջեյմս Ստենհոուփի հրամանատարությամբ 1708 թ. սեպտեմբերի 14-ին ափ իջան կղզում և սեպտեմբերի 28-29-ին, փլուզելով իսպանական պաշտպանությունը, վերցրին Մինորկայի վերահսկողությունը (գլխավոր բերդ Ֆորտ Սեն Ֆիլիպի պաշտոնական հանձնումը ձգվեց մինչև նոյեմբերի 24-ը)։ Մինորկայի ռազմավարական նավահանգիստ Մաոնը հաջորդ մեկ դարի ընթացքում լինելու էր անգլո-ֆրանս-իսպանական պայքարի կիզակետը։", "9188937e"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["Ռաշտատի պայմանագիրը. Իսպանական ժառանգության պատերազմն ավարտվեց, Իսպանական Նիդերլանդներն ու Միլանը անցան Ավստրիային", "3c0e086f"], "d": ["Իսպանական ժառանգության պատերազմը Ֆրանսիայի և Ավստրիայի միջև ավարտած Ռաշտատի պայմանագիրը ստորագրվեց 1714 թ. մարտի 7-ին (Ուտրեխտը 1713 թ. կարգավորել էր Անգլիա-Ֆրանսիա հարաբերությունը). պայմանագրով ավստրիական Հաբսբուրգները ստացան Իսպանական Նիդերլանդները (այսօրվա Բելգիա) և Իտալիայում Նեապոլը, Միլանն ու Սարդինիան։ Սա Ավստրիայի պատմության ամենալայն տարածքային ընդարձակումն էր և Հաբսբուրգների հարստության կենտրոնաեվրոպական կշռին ավելացրեց նոր ճակատ Արևմտյան և Հարավային Եվրոպայում։", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["Նիշտադտի պայմանագիրը. Հյուսիսային մեծ պատերազմն ավարտվեց, Բալթյան ափերը անցան Ռուսաստանին", "068ffd06"], "d": ["21 տարի տևած Հյուսիսային մեծ պատերազմին վերջ դրած Նիշտադտի պայմանագիրը ստորագրվեց 1721 թ. սեպտեմբերի 10-ին (հուլյան օգոստոսի 30) Ֆինլանդիայում. Շվեդիան Ռուսաստանին թողեց Էստլանդիան, Լիվոնիան (ներառյալ Ռիգան), Ինգերմանլանդիան և հարավ-արևելյան Ֆինլանդիայի (Կարելիա) մի մասը, փոխարենը հետ ստացավ Ֆինլանդիայի մնացած մասը և փոխհատուցում վճարվեց։ Պայմանագիրը համարվում է Շվեդիայի մեծ տերության կարգավիճակի վերջի և Ռուսաստանի՝ որպես եվրոպական կայսրության վերելքի պաշտոնական ամրագրումը. Պետրոս I-ը այս հաղթանակից հետո ստացավ «կայսր» տիտղոսը։", "f0c4fc4a"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["Լեհաստանի երկրորդ բաժանումը. տարածքային կորուստ հօգուտ Ռուսաստանի և Պրուսիայի", "31750484"], "d": ["1791 թ. սահմանադրական բարեփոխումները անհանգստացրին Ռուսաստանին և Պրուսիային, և երկու պետությունները 1793 թ. հունվարի 23-ին Սանկտ Պետերբուրգում ստորագրած պայմանագրով կրկին բաժանեցին Լեհաստանը. Ռուսաստանը վերցրեց Լիտվա-Բելառուսի մեծ մասը և արևմտյան Ուկրաինան (ներառյալ Կամյանեցը, Բարը, Մինսկը), իսկ Պրուսիան բռնակցեց Մեծ Լեհաստանը՝ Գդանսկով և Պոզնանով. ընդամենը 307.000 քառ. կմ։ Ճնշման տակ գտնվող Լեհական Սեյմը ստիպված էր նույն տարում վավերացնել պայմանագիրը. սա կարճատև բաժանում էր, որը երկու տարով հետաձգեց Լեհաստանի լիակատար բռնակցումը։ Այս օրը (1793 թ. հունվարի 23) Լեհաստանի երկրորդ բաժանմամբ Բերդիչևը, Ֆաստովը, Ժիտոմիրը, Կանևը, Կոնստանտինովը, Ումանը և Չերկասին ներառյալ Աջափնյա Ուկրաինան անցավ Ռուսաստանին։", "656e71c2"]},
"OLAYLAR_EK16:1795-03-28:0":{"b": ["Կուրլանդիայի և Սեմիգալիայի դքսությունը միացավ Ռուսաստանին. վերջին դուքս Պետեր ֆոն Բիրոնը հրաժարվեց", "8d0e410f"], "d": ["Լեհաստանի III բաժանման ընթացքում կուրլանդացի ազնվականները հավատարմություն հայտնեցին Եկատերինային, դուքս Պետեր ֆոն Բիրոնը հրաժարվեց գահից. Կուրլանդիան դարձավ Ռուսաստանի նահանգ (գուբերնիա) (աղբյուրներում հանդիպում է նաև 1795 թ. հոկտեմբերի 24-ը)։", "4682774b"]},
"OLAYLAR_EK16:1797-06-14:0":{"b": ["Ջենովայի Հանրապետության վերջը. Նապոլեոնը հիմնեց Լիգուրյան Հանրապետությունը", "3d3e59ee"], "d": ["Իտալական արշավանքի մեջ գտնվող Նապոլեոնի ճնշմամբ 1797 թ. հունիսի սկզբին ժամանակավոր վարչակարգին հանձնված Ջենովայի Հանրապետության փոխարեն 1797 թ. հունիսի 14-ին ֆրանսիական օրինակով սահմանադրությամբ հռչակվեց «Լիգուրյան Հանրապետությունը». դարավոր Ջենովայի դքսությունը փաստացի վերածվեց Ֆրանսիայի արբանյակ պետություններից մեկի։ Հանրապետությունը 1805 թ. ուղղակի բռնակցվելու էր Ֆրանսիային, իսկ 1815 թ. Վիեննայի վեհաժողովով թողնվելու էր Սարդինիա-Պիեմոնտի թագավորությանը։", "38af1e4b"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["Կամպո Ֆորմիոյի պայմանագիրը. Վենետիկի բաժանումը Ավստրիայի և Ֆրանսիայի միջև", "9f29678c"], "d": ["Նապոլեոն Բոնապարտի և Ավստրիայի ներկայացուցիչ կոմս Կոբենցլի միջև 1797 թ. հոկտեմբերի 17-ին ստորագրված Կամպո Ֆորմիոյի պայմանագիրը պաշտոնապես վերացրեց հազարամյա Վենետիկի Հանրապետությունը և բաժանեց նրա հողերը. Ադիջե գետից արևելք ընկած մասը, Իստրիան և Դալմաթիայի ափը (ներառյալ Սպլիտը, Զադարը, Շիբենիկը, Կոտորը) մնացին Ավստրիային, իսկ Հոնիական կղզիները (ներառյալ Կորֆուն, Կեֆալոնիան, Զակինթոսը, Լեֆկադան, ինչպես նաև Վենետիկի հենակետերը Ալբանիայի-Մորեայի ափին՝ Պրևեզան և Պարգան) անցան Ֆրանսիային։ Բացի այդ, Ավստրիան Ֆրանսիային զիջեց Ստորին Երկրների (այսօրվա Բելգիա) իր տարածքները։", "296ee82f"]},
"OLAYLAR_EK16:1800-09-05:0":{"b": ["Մալթայի հանձնումը Անգլիային. երկամյա ֆրանսիական պաշարման վերջը", "fedc2867"], "d": ["1798 թ. Եգիպտոսի արշավանքի ճանապարհին Նապոլեոնի գրաված Մալթան կարճ ժամանակ անց, կղզու բնակչության ապստամբությամբ, ընկավ անգլիական նավատորմի ծովային շրջափակման մեջ. երկու տարի տևած պաշարման և սովի վերջում ֆրանսիական հրամանատար գեներալ Վոբուան 1800 թ. սեպտեմբերի 5-ին անձնատուր եղավ անգլիական գեներալ Պիգոտին։ Այսպիսով Մալթան Ֆրանսիական Հանրապետությունից անցավ անգլիական հովանու ներքո և 1814 թ. Փարիզի պայմանագրով պաշտոնապես կապվելու էր անգլիական թագին. այն դարձավ Միջերկրական ծովի ամենակարևոր անգլիական ռազմածովային հենակետը։", "6f406ae3"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["Ամիենի պայմանագիրը. Մինորկան վերադարձվեց Իսպանիային", "f341e4b8"], "d": ["Ֆրանսիայի, Իսպանիայի, Հոլանդիայի և Անգլիայի միջև ստորագրված Ամիենի պայմանագիրը (1802 թ. մարտի 25) ժամանակավորապես վերջ դրեց Երկրորդ կոալիցիայի պատերազմին. Անգլիան վերադարձրեց պատերազմի ընթացքում գրաված գրեթե բոլոր տարածքները (բացի Ցեյլոնից և Տրինիդադից), որոնցից մեկն էլ 1798 թ. Իսպանիայից վերցրած Մինորկան էր։ Խաղաղությունը տևեց ընդամենը մեկ տարի, 1803 թ. մայիսին պատերազմը նորից բռնկվեց, բայց Մինորկան այս պայմանագրից հետո այլևս չանցավ անգլիական ձեռք։", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["Ֆրեդրիկսհամնի (Համինայի) պայմանագիրը. Շվեդիան Ֆինլանդիան զիջում է Ռուսաստանին", "c0d407bc"], "d": ["1808-1809 թթ. ռուս-շվեդական պատերազմին վերջ դրած Ֆրեդրիկսհամնի (այսօր՝ Համինա) պայմանագիրը ստորագրվեց 1809 թ. սեպտեմբերի 17-ին. Շվեդիան Ռուսաստանին թողեց ողջ Ֆինլանդիան՝ ներառյալ Օլանդյան կղզիները։ Ֆինլանդիան ստացավ Ռուսական կայսրությանը կապված, լայն ինքնավարությամբ Մեծ դքսության կարգավիճակ և պահպանեց լյութերական հավատն ու շվեդական իրավունքը։ Դա փաստացի նշանակում էր Բալթյան ծովում Շվեդիայի մեծ տերության կարգավիճակի վերջը։ Այս պայմանագրով Ֆինլանդիայի վեց նահանգները և Վեստերբոթենը մինչև Տորնե գետը (Կոկկոլա, Յոենսու, Սավոնլիննա, Տորնիո, Ռովանիեմի, Ինարի և այլն) անցան Ռուսաստանին կապված Ֆինլանդիայի Մեծ դքսությանը։", "fb46c9a1"]},
"OLAYLAR_EK16:1810-03-04:0":{"b": ["Իմերեթիի թագավորության բռնակցումը. թագավոր Սողոմոն II-ին գահընկեց արին", "5ad36bff"], "d": ["1804 թ. Էլազնաուրիի պայմանագրով ռուսական վասալությունն ընդունելու ստիպված արևմտավրացական Իմերեթիի թագավորության վերջին թագավոր Սողոմոն II-ը շարունակեց դիմադրել ռուսական աճող ճնշմանը. 1810 թ. փետրվարի 20-ին ռուսական զորքերը գրավեցին մայրաքաղաք Քութաիսին, գահընկեց արին Սողոմոնին և տեղի ազնվականներին ստիպեցին հավատարմության երդում տալ Ալեքսանդր I ցարին. Իմերեթիի թագավորությունը այսպիսով փաստացի վերացավ և կապվեց ուղղակի ռուսական կառավարմանը։ Սողոմոնը, փախչելով օսմանյան տարածք, մահացավ աքսորում (1815)։", "fdccc40f"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["Կիլի պայմանագիրը. Դանիան Նորվեգիան զիջում է Շվեդիային", "59ab1601"], "d": ["Լայպցիգում Նապոլեոնի պարտությունից հետո հարավից Դանիայի վրա հարձակված Շվեդիան 1814 թ. հունվարի 14-ին ստորագրված Կիլի պայմանագրով ստացավ Նորվեգիան (բացի Իսլանդիայից, Ֆարերյան կղզիներից և Գրենլանդիայից). 1380 թվականից տևող դանիա-նորվեգական միությունն այսպիսով պաշտոնապես ավարտվեց։ Փոխարենը Շվեդիան Դանիային թողեց Պոմերանիայի իր տարածքները. Դանիան, բացի այդ, Հելգոլանդը հանձնեց Անգլիային։ Նորվեգիան զենքով դիմադրեց պայմանագրին և հռչակեց իր սահմանադրությունը, և Շվեդիան ստիպված էր ճանաչել այն. արդյունքը եղավ անձնական միություն (real union), որը տևելու էր մինչև 1905 թ.։ Շվեդիան փաստացի չկարողացավ ստանձնել Նորվեգիան. պայմանագիրը Նորվեգիայում չընդունվեց, և կառավարումը մնաց Քրիստիան Ֆրեդերիկին. շվեդական բանակը Նորվեգիա մտավ միայն 1814 թ. հուլիսի 26-ին։", "223aed9a"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["Վիեննայի վեհաժողովի եզրափակիչ ակտը. նապոլեոնյան դարաշրջանից հետո Եվրոպայի քարտեզը նորովի գծվեց", "fca1c676"], "d": ["Նապոլեոնյան պատերազմներին վերջ դրած մեծ տերությունների (Ավստրիա, Ռուսաստան, Պրուսիա, Անգլիա, Ֆրանսիա) միջև ստորագրված Վիեննայի վեհաժողովի եզրափակիչ ակտը ընդունվեց 1815 թ. հունիսի 9-ին (Վաթեռլոյից 9 օր առաջ) և միանգամից նորովի գծեց մայրցամաքի քարտեզը. նախկին Իսպանական/Ավստրիական Նիդերլանդներն ու Միացյալ նահանգները միավորվեցին «Միացյալ Նիդերլանդների թագավորության» ներքո, Ջենովայի Հանրապետությունը միացավ Սարդինիա-Պիեմոնտի թագավորությանը, Վարշավայի դքսության մեծ մասը «Կոնգրեսային Լեհաստան» անունով կապվեց Ռուսաստանին, իսկ Շվեդական Պոմերանիան (Շտրալզունդ) անցավ Պրուսիային։ Այս մեկ օրը համարվում է հետպատերազմյան եվրոպական հավասարակշռության (Concert of Europe) պաշտոնական սկիզբը։ Այս ակտով Լոձը, Չենստոխովան, Կիելցեն, Ռադոմը, Լյուբլինը, Խելմը և Զամոշչը (Վարշավայի դքսություն) անցան Ռուսաստանին կապված Լեհաստանի թագավորությանը, Պոզնանը (Պոզենի Մեծ դքսություն)՝ Պրուսիային, Մաստրիխտն ու Ռուրմոնդը՝ Նիդերլանդների թագավորությանը։", "b0c34466"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["Ծովային ընդհանուր պայմանագիր. Կավասիմները և Ծոցի մյուս շեյխությունները պայմանագրով կապվեցին Անգլիային", "fc499e19"], "d": ["1819 թ. Ռաս ալ-Խայման ռմբակոծելուց և «ծովահեն» Կասիմի նավատորմը ցրելուց հետո Անգլիան պարտադրեց Ծովային ընդհանուր պայմանագիրը, որը սկսվեց 1820 թ. հունվարի 8-ին և, շրջանի շեյխությունների հետ մեկ առ մեկ ստորագրվելով, ավարտվեց մինչև մարտ. պայմանագիրը արգելում էր ծովահենությունն ու ստրկությունը և պարտադիր էր դարձնում, որ նավերը կրեն անգլիական դրոշին նման կարմիր-սպիտակ դրոշ։ Այս պայմանագրով «Ծովահենների ափը» ժամանակի ընթացքում վերածվեց «Զինադադարի ափի» (Trucial Coast). սա 1853 թ. մշտական ծովային զինադադարով և 1892 թ. բացառիկ պայմանագրերով խորացող անգլիական գերիշխանության հարաբերության սկիզբն էր, որը տևելու էր մինչև 1971 թ.։", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["Գաետայի պաշարման ավարտը. Երկու Սիցիլիաների թագավորության փլուզումը", "121ae580"], "d": ["1860 թ. մայիսին Գարիբալդիի՝ Սիցիլիա ափ իջնելով սկսված փլուզումից հետո Նեապոլից փախած Բուրբոն թագավոր Ֆրանչեսկո II-ը իր վերջին բերդ Գաետայում պաշարվեց 1860 թ. նոյեմբերի 3-ից. 1861 թ. հունվարին ֆրանսիական նավատորմի հեռանալուց հետո իտալական ծովային շրջափակումը խստացավ, և 1861 թ. փետրվարի 13-ին Գաետան հանձնվեց։ Ֆրանչեսկո II-ը, թողնելով գահը, գնաց աքսոր. Երկու Սիցիլիաների թագավորության վերջին դիմադրության կետը՝ Չիվիտելլա դել Տրոնտոն, ընկնելու էր միայն 1861 թ. մարտի 20-ին։ Թագավորության փլուզմամբ Սիցիլիայի (Պալերմո, Մեսինա, Սիրակուզա, Տրապանի, Միզիլմերի) և Կամպանիայի (ներառյալ Նոլան) հողերն այլևս Բուրբոնների կառավարման տակ չէին։", "bb89dfd9"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["Իտալիայի թագավորության հռչակումը. Սարդինիայի, Տոսկանայի և հարավային Իտալիայի միավորումը", "12e52f70"], "d": ["1861 թ. մարտի 17-ին Թուրինում իտալական խորհրդարանի առաջին նիստում պաշտոնապես հռչակվեց Իտալիայի թագավորությունը, և Սարդինիա-Պիեմոնտի թագավոր Վիտտորիո Էմանուելե II-ը դարձավ միացյալ Իտալիայի առաջին թագավորը։ Նոր թագավորությունը Սարդինիայի թագավորության հետ միավորում էր նախորդ տարում ժողովրդական քվեարկություններով միացած Տոսկանայի, Էմիլիա-Ռոմանիայի, Նեապոլի և Սիցիլիայի (Երկու Սիցիլիաների) հողերը. Հռոմը (Պապական պետություն) և Վենետիկը (Ավստրիա) դեռ դուրս էին մնում. դրանք միանալու էին համապատասխանաբար 1870 և 1866 թվականներին։", "d044a9c0"]},
"OLAYLAR_EK16:1866-10-18:0":{"b": ["Ջիզախի անկումը Ռուսաստանի ձեռքը. Բուխարայի ամիրայության վերջին բերդը Սիր Դարիայի գծում", "21205a6e"], "d": ["Կենտրոնական Ասիայում Ռուսաստանի առաջխաղացման ժամանակ, գեներալ Չեռնյաևի 1866 թ. փետրվարի անհաջող փորձից հետո, նրան փոխարինած գեներալ Դմիտրի Ռոմանովսկու հրամանատարությամբ ռուսական ուժերը 1866 թ. հոկտեմբերին յոթօրյա պաշարումով և կատաղի գրոհով գրավեցին Բուխարայի ամիրայության վերջին խոշոր բերդը Սիր Դարիայի հովտում՝ Ջիզախը. այս անկումը փաստացի վերջ դրեց շրջանում բուխարական դիմադրությանը և ռուսական բանակի համար բացեց Սամարղանդ տանող ճանապարհը։", "b95ba993"]},
"OLAYLAR_EK16:1868-05-14:0":{"b": ["Ռուսական բանակը գրավեց Սամարղանդը. քաղաքը Բուխարայի ամիրայությունից անցավ Թուրքեստանի գեներալ-նահանգապետությանը", "321473be"], "d": ["Ռուսական ուժերը գրավեցին Բուխարայի ամիրայության ձեռքում գտնվող Սամարղանդը և քաղաքը միացրին Թուրքեստանի գլխավոր կառավարման շրջանին։ Սամարղանդը ուզբեկ խաների օրոք Բուխարայի ստվերում մնացած քաղաք էր. ռուսական կառավարմամբ այն դարձավ Կենտրոնական Ասիայում ռուսական առաջխաղացման նոր կանգառ։", "3bc56bbe"]},
"OLAYLAR_EK16:1870-09-28:0":{"b": ["Ստրասբուրգի հանձնումը. գերմանական զորքերը գրավեցին քաղաքը", "ef3281f3"], "d": ["Վեցշաբաթյա պաշարումից և ռմբակոծությունից հետո գեներալ Ուրիխը գիշերը Քյոնիգսհոֆենում ստորագրեց կապիտուլյացիան. առավոտյան դարպասներն ու բերդը հանձնվեցին պրուսական և բադենյան զորամասերին։ Քաղաքը մինչև Ֆրանկֆուրտի պայմանագիրը (1871 թ. մայիսի 10) մնաց ռազմական օկուպացիայի տակ։", "38c8361d"]},
"OLAYLAR_EK16:1870-10-29:0":{"b": ["Մեցի հանձնումը. Բազենի բանակը վայր դրեց զենքը, գերմանական զորքերը վերցրին բերդը", "8dd66f58"], "d": ["Պաշարված Հռենոսյան բանակի կապիտուլյացիայի արձանագրությունը ստորագրվեց հոկտեմբերի 27-ի երեկոյան. հոկտեմբերի 29-ի առավոտյան բաստիոններին բարձրացվեցին պրուսական դրոշները, և ֆրանսիական զորքերը լքեցին բերդը։ Մեցը մինչև Ֆրանկֆուրտի պայմանագիրը (1871 թ. մայիսի 10) մնաց ռազմական օկուպացիայի տակ։", "112e1a60"]},
"OLAYLAR_EK16:1882-03-10:0":{"b": ["Ասաբը անցավ իտալական պետության սեփականությանը. Իտալիայի առաջին գաղութի հիմքը", "15ab8732"], "d": ["Կարմիր ծովի ափի Ասաբ նավահանգիստը 1869 թ. իտալական մասնավոր նավատիրական ընկերությունը (Ռուբատտինո) գնել էր տեղի աֆարական առաջնորդներից. Անգլիայի հավանությամբ իտալական կառավարությունը 1882 թ. մարտի 10-ին ստանձնեց նավահանգստի ուղղակի պետական սեփականությունը և հուլիսին ընդունած օրենքով Ասաբը պաշտոնապես հռչակեց Իտալիայի առաջին գաղութը։ Սա Իտալիայի՝ հետագայում Էրիթրեա գաղութի (1890) վերածվելիք Կարմիր ծովի ափամերձ ընդարձակման ելակետն էր։", "ba606490"]},
"OLAYLAR_EK16:1884-02-08:0":{"b": ["Սինկատի կայազորի ոչնչացումը. Սինկատն անցավ Մահդիի ուժերին", "e175a94e"], "d": ["Ամիսներ շարունակ Օսման Դիգնայի ուժերի կողմից պաշարված և պաշարը սպառած Սինկատի կայազորը իր հրամանատար Թևֆիք բեյի հետ փորձեց ճեղքել պաշարումը և հասնել Սուաքին. 1884 թ. փետրվարի 8-ին այն ոչնչացվեց բերդից դուրս, և Սինկատն անցավ Մահդիի ուժերի ձեռքը։ Լուրը Սուաքին հասավ փետրվարի 12-ին։", "abf8611c"]},
"OLAYLAR_EK16:1884-02-09:0":{"b": ["Ռազմական դրություն Սուաքինում. քաղաքն անցավ անգլիական հրամանատարության ներքո", "801f6a81"], "d": ["Փետրվարի 4-ին Էլ-Թեբում Թոկարը փրկելու Բեյքերի ուժերի ջախջախումից հետո ծովակալ Հյուիթը փետրվարի 6-ին Սուաքին ծովային հետևակ իջեցրեց։ 1884 թ. փետրվարի 9-ին քաղաքում հայտարարվեց ռազմական դրություն, և անգլիական սպաներին տրվեց քաղաքի նկատմամբ լիակատար ռազմական և քաղաքացիական իշխանություն. հաջորդ օրը քաղաքի պատասխանատվությունը պաշտոնապես Բեյքերից փոխանցվեց Հյուիթին։", "92798eb8"]},
"OLAYLAR_EK16:1884-02-20:0":{"b": ["Թոկարի հանձնումը Մահդիի ուժերին", "0e21fd24"], "d": ["Պաշարված Թոկարի կայազորը 1884 թ. փետրվարի 19-ին բանակցությունների մեջ մտավ Մահդիի ուժերի հետ և հաջորդ օրը՝ փետրվարի 20-ին, հանձնեց քաղաքը։ Լուրը փետրվարի 24-ին հասավ Թրինկիտաթի անգլիական ուժին. Գրեհեմի փրկարար արշավանքն ուշացել էր։", "0ebad590"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["Բրիտանիան պրոտեկտորատ հաստատեց Սոմալիի հյուսիսային ափին. Սոմալիլենդի սկիզբը", "f301ea94"], "d": ["TDV-ի «Սոմալի» հոդվածի համաձայն՝ Զեյլան, Բերբերան և Թաջուրան 1884 թ. անգլիացիների կողմից գաղութացվեցին Սոմալիլենդ անունով. ընդունված ակադեմիական աղբյուրի համաձայն՝ այս ընթացքը սկսվեց Բերբերայում Հաբար Ավալ ցեղախմբի հետ հիջ. 1301 թ. Ռամադան ամսի 21-ին (1884 թ. հուլիսի 14) ստորագրված պայմանագրով և ընդարձակվեց 1884-1886 թվականներին Գադաբուրսի, Հաբար Թոլջաալա, Հաբար Ջերհաջիս, Իսսա և Վարսանգելի ցեղախմբերի հետ ստորագրված նմանատիպ պայմանագրերով. Անգլիան փոխարենը խոստացավ ռազմական պաշտպանություն։ Պայմանագրերի այս շղթան հող նախապատրաստեց 1887 թ. Բրիտանական Սոմալիլենդի պաշտոնական պրոտեկտորատի հռչակման համար։", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["Մուլայդայի ճակատամարտը. Սաուդյան երկրորդ պետության վերջը, Նեջդն անցավ Ռաշիդներին", "1cd3b213"], "d": ["Զաքաթի վերաբերյալ տարաձայնության և Ռաշիդյան մի դեսպանի ձերբակալության պատճառով խզված հարաբերությունների արդյունքում Ջաբալ Շամմարի էմիր Մուհամմեդ բին Ռաշիդի բանակը 1891 թ. հունվարի 21-ին Կասիմի շրջանի Մուլայդայում ծանր պարտության մատնեց Աբդուռահման բին Ֆայսալի գլխավորած սաուդյան ուժերին և նրանց դաշնակիցներին. սա դարձավ Սաուդյան երկրորդ պետության փաստացի վերջը, Ալ Սաուդ ընտանիքը աքսորվեց Քուվեյթ, և ամբողջ Նեջդն անցավ Ռաշիդյան տիրապետության տակ. դրա մեջ էին նաև հարավի Դիլամ (Խարջ), Հաուտա (Հաուտաթ Բանի Թամիմ) և Լեյլա (Աֆլաջ) շրջանները։ Այդ տիրապետությունը տևելու էր մինչև 1902 թ., երբ երիտասարդ Աբդուլազիզ բին Սաուդը հետ վերցրեց Ռիադը (Ռիադի հարձակումը, 1902 թ. հունվարի 16)։", "b77d8161"]},
"OLAYLAR_EK16:1891-02-19:0":{"b": ["Անգլո-եգիպտական ուժերը հետ վերցրեցին Թոկարը. Օսման Դիգնայի նահանջը", "80a2c26a"], "d": ["1884 թվականից Մահդիական շարժման տեղական հրամանատար Օսման Դիգնայի ձեռքում գտնվող Կարմիր ծովի ափի Թոկարը 1891 թ. փետրվարին հետ վերցվեց անգլո-եգիպտական ուժերի գործողությամբ. Օսման Դիգնան ստիպված էր նահանջել լեռները։ Սա մեծ հարված էր Մահդիական պետության ներկայությանը Կարմիր ծովի ափին, և շրջանն անցավ անգլո-եգիպտական համատեղ կառավարման տակ։", "07bd31cf"]},
"OLAYLAR_EK16:1891-03-03:0":{"b": ["Գրենֆելի զորասյան անցումը Սինկատով. Սինկատը դուրս եկավ Մահդիի կառավարումից և վերադարձավ անգլո-եգիպտական կառավարման", "b7539a44"], "d": ["1891 թ. փետրվարին Թոկարը հետ վերցնելուց հետո Գրենֆելի հրամանատարությամբ անգլո-եգիպտական զորասյունը 1891 թ. մարտի 3-ին Աֆաֆիթից Սինկատի վրայով ճանապարհ ընկավ և մարտի 7-ին հասավ Սուաքին. զորասյունը գտավ, որ 1884 թվականից բոլորովին ներթափանցել չկարողացված շրջանը թշնամուց լիովին դատարկվել է։ Մարտի 8-ին Սուաքինում հավաքված շեյխերին խեդիվի անունից ընդհանուր ներում հայտարարվեց, և Սինկատը կրկին կապվեց անգլո-եգիպտական կառավարմանը։", "5e77e2d3"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["Իտալական Սոմալիի անցումը պետական ուղղակի կառավարման. Բենադիրի ընկերության լուծարումը", "8c7d085b"], "d": ["TDV-ի «Սոմալի» հոդվածի համաձայն՝ Իտալիան իր տիրապետությունը Սոմալիի հարավային ափին (Բենադիր) հաստատել էր 1889-1891 թվականներին Զանզիբարի սուլթանության և Անգլիայի հետ կնքած համաձայնագրերով, իսկ կառավարումը սկզբում թողել էր արտոնյալ առևտրական ընկերության (Benadir Company). ընդունված ակադեմիական աղբյուրի համաձայն՝ այս ընկերության արտոնությունը 1905 թ. հունվարի 24-ին ավարտվեց, և իտալական պետությունը, գնելով Բենադիրի ափի (ներառյալ Մոգադիշոն, Մերկան, Բարավեն) ուղղակի ինքնիշխանությունը, հաստատեց պաշտոնական գաղութային վարչակարգ։ Գաղութի փաստացի ընդարձակումը դեպի ներքին շրջաններ (Բարդերա, Բայդաբո) ավարտվելու էր 1908 թ. հիմնադիր հրամանագրով և հաջորդ տարիներին։", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["Նորվեգա-շվեդական միության լուծարումը. Ստորտինգի միակողմանի անկախության հռչակումը", "aaba2935"], "d": ["Երբ Օսկար II թագավորը վետո դրեց Նորվեգիայի կառավարության՝ առանձին հյուպատոսություններ հիմնելու պահանջի վրա և հայտարարեց, որ չի կարող նոր կառավարություն կազմել, Նորվեգիայի Ստորտինգը (խորհրդարան) 1905 թ. հունիսի 7-ին միաձայն որոշեց, որ թագավորն այլևս փաստացի չի կատարում Նորվեգիայի թագավորի պաշտոնը, և 1814 թ. Կիլի պայմանագրից ի վեր տևող միությունը լուծարված է։ 1905 թ. օգոստոսի 13-ի ժողովրդական քվեարկությամբ ընտրողների գրեթե բոլորը (371.000 ձայն՝ ընդդեմ 184-ի) հաստատեցին լուծարումը. Կարլստադի բանակցություններից հետո Շվեդիան 1905 թ. հոկտեմբերի 26-ին պաշտոնապես ճանաչեց անկախությունը։", "94eda38c"]},
"OLAYLAR_EK16:1915-05-08:0":{"b": ["Գերմանական ուժերը վերցրին Լիբաուն (Լիեպայա). սկսվեց Կուրլանդիայի օկուպացիան", "fdb10548"], "d": ["Գերմանիան իր 1915 թ. ամառային հարձակման ժամանակ մտավ Կուրլանդիա. Լիբաուն Բալթյան ափի ռուսական ռազմածովային հենակետն էր։ Կուրլանդիայի մեծ մասն անցավ Ober Ost հրամանատարության ներքո (մինչև 1918 թ. վերջը)։", "98e7ef58"]},
"OLAYLAR_EK16:1915-08-01:0":{"b": ["Գերմանական ուժերը վերցրին Միտաուն (Ելգավա)", "eb491281"], "d": ["Կուրլանդիայի նախկին դքսական մայրաքաղաք Միտաուն անցավ գերմանական վերահսկողության տակ. Ռիգայի ռազմաճակատը սառեց Դաուգավայի գծում և մնաց անշարժ մինչև 1917 թ.։", "05882415"]},
"OLAYLAR_EK16:1915-08-18:0":{"b": ["Գերմանացիները վերցրին Կովնոյի (Կաունաս) բերդը. Լիտվան անցավ օկուպացիայի տակ", "9849405b"], "d": ["Գերմանական 10-րդ բանակը վերցրեց Նեմանի վրա Ռուսաստանի ամենամեծ բերդը. Լիտվական շրջանը անցավ Ober Ost-ի կառավարման ներքո, և 1918 թ. Տարիբան անկախությունը հռչակեց այս օկուպացիայի ներքո։", "1f9a43bc"]},
"OLAYLAR_EK16:1915-09-18:0":{"b": ["Գերմանական ուժերը վերցրին Վիլնան (Վիլնյուս)", "2781858b"], "d": ["Մեծ նահանջի ժամանակ Վիլնան անցավ գերմանական ուժերին և կապվեց Ober Ost-ի Լիտվական շրջանին. քաղաքը մինչև 1919 թ. ձեռքից ձեռք անցավ գերմանական, խորհրդային և լեհական ուժերի միջև։", "d9dddcbb"]},
"OLAYLAR_EK16:1916-11-03:0":{"b": ["Անգլո-կատարյան պայմանագիր. Կատարը անցավ անգլիական հովանու ներքո", "f61c4e49"], "d": ["Առաջին համաշխարհային պատերազմի ընթացքում Պարսից ծոցում անգլիական քաղաքական ներկայացուցիչ մայոր Պերսի Քոքսի և Կատարի շեյխ Աբդալլահ բին Ջասիմ Ալ Թանիի միջև 1916 թ. նոյեմբերի 3-ին ստորագրված պայմանագրով Կատարը համաձայնեց իր արտաքին հարաբերությունները կախման մեջ դնել Անգլիայի հավանությունից և փոխարենը ստացավ անգլիական պաշտպանության երաշխիք ծովային հարձակումների դեմ. այս պայմանագիրը կազմեց Կատարի՝ մինչև 1971 թ. տևելիք անգլիական պրոտեկտորատային հարաբերության իրավական հիմքը և պաշտոնապես վավերացվեց 1918 թ.։", "abf30185"]},
"OLAYLAR_EK16:1917-09-03:0":{"b": ["Գերմանական 8-րդ բանակը վերցրեց Ռիգան", "df95df19"], "d": ["Գերմանական ուժերը, անցնելով Դաուգավան, վերցրին Ռիգան. քաղաքը մինչև 1918 թ. նոյեմբերը մնաց գերմանական վերահսկողության տակ, Լատվիայի անկախությունը հռչակվեց այս օկուպացիայի ներքո (1918 թ. նոյեմբերի 18)։", "e0339705"]},
"OLAYLAR_EK16:1918-11-18:0":{"b": ["Լատվիայի Ժողովրդական խորհուրդը հռչակեց անկախությունը", "fc72a7f7"], "d": ["Ռիգայի Ազգային թատրոնում հավաքված Լատվիայի Ժողովրդական խորհուրդը հռչակեց Ռուսական կայսրությունից անկախ Լատվիայի Հանրապետությունը. Կառլիս Ուլմանիսի գլխավորությամբ կազմվեց ժամանակավոր կառավարություն։ Մի քանի շաբաթ անց (1918 թ. դեկտեմբեր) հարձակվեց Խորհրդային Ռուսաստանը, և սկսվեց Անկախության պատերազմը։ Այս հռչակումով Ռիգան, Ելգավան, Լիեպայան, Վենտսպիլսը, Ցեսիսը, Դաուգավպիլսը և Ռեզեկնեն համարվեցին Լատվիայի Հանրապետության տարածք։", "615adeb0"]},
"OLAYLAR_EK16:1919-01-05:0":{"b": ["Կարմիր բանակը մտավ Վիլնյուս. Լիտվայի կառավարությունը դատարկեց քաղաքը", "889a97b3"], "d": ["Կարմիր բանակի մոտենալուն զուգընթաց Լիտվայի կառավարությունը լքեց Վիլնյուսը. խորհրդային ուժերը մտան քաղաք, և 1919 թ. փետրվարին այստեղից հռչակվեց Լիտվա-Բելառուսական Խորհրդային Հանրապետությունը (Լիտբել)։ Քաղաքը 1919 թ. ապրիլին վերցնելու էին լեհական ուժերը։", "c3a0c216"]},
"OLAYLAR_EK16:1919-04-21:0":{"b": ["Լեհական ուժերը Վիլնյուսը (Վիլնո) վերցրին խորհրդայիններից", "32d36c4a"], "d": ["Յուզեֆ Պիլսուդսկու զորամասերը 1919 թ. ապրիլին Վիլնոն վերցրին Կարմիր բանակից. Լիտվան շարունակեց հավակնել քաղաքին, և Վիլնյուսի հարցը թունավորեց երկու պատերազմների միջև լիտվա-լեհական հարաբերությունները։", "85e7c434"]},
"OLAYLAR_EK16:1922-02-28:0":{"b": ["Անգլիան վերացրեց Եգիպտոսի նկատմամբ պրոտեկտորատը և Եգիպտոսը հռչակեց անկախ", "f8faab66"], "d": ["Անգլիան 1922 թ. փետրվարի 28-ի հայտարարությամբ միակողմանիորեն վերջ դրեց 1914 թվականից տևող պրոտեկտորատին և Եգիպտոսը հռչակեց անկախ պետություն. պաշտպանության, հաղորդակցության ուղիների և Սուդանի նման հարցերը վերապահվեցին Անգլիային։ Հայտարարությունից երկու շաբաթ անց (1922 թ. մարտի 15) սուլթան Ահմեդ Ֆուադը ստացավ թագավորի տիտղոսը։ Քարտեզում Եգիպտոսի քաղաքների անգլիական օկուպացիայի շերտը ավարտվում է այս օրը։", "8cde4005"]},
"OLAYLAR_EK16:1939-03-22:0":{"b": ["Լիտվան ընդունեց գերմանական վերջնագիրը. Մեմելի շրջանը հանձնվեց Գերմանիային", "149fb0b2"], "d": ["Ռիբենտրոպի վերջնագրի պատճառով Լիտվան Կլայպեդայի (Մեմել) շրջանը թողեց Գերմանիային. Հիտլերը մարտի 23-ին մտավ Մեմել։ Շրջանը Կարմիր բանակը վերցրեց 1945 թ. հունվարի 28-ին։", "75afd979"]},
"OLAYLAR_EK16:1941-06-23:0":{"b": ["Գերմանիան օկուպացրեց Գրոդնոն", "b7ca9378"], "d": ["Արևելյան ռազմաճակատ. 1941 թ. «Բարբարոսա» և 1944 թ. «Բագրատիոն»։", "c6101096"]},
"OLAYLAR_EK16:1941-06-23:1":{"b": ["Գերմանիան օկուպացրեց Բրեստ-Լիտովսկը", "25898c65"], "d": ["Արևելյան ռազմաճակատ. 1941 թ. «Բարբարոսա» և 1944 թ. «Բագրատիոն»։", "c6101096"]},
"OLAYLAR_EK16:1941-07-09:0":{"b": ["Գերմանական բանակը վերցրեց Պսկովը. սկսվեց ռուսական հողերի օկուպացիան", "d9822e30"], "d": ["«Բարբարոսա» գործողության երրորդ շաբաթում Վերմախտը մտավ Պսկով. քաղաքը մինչև 1944 թ. հուլիսի 23-ը մնաց գերմանական ռազմական կառավարման տակ։ Աղբյուր՝ Պսկով քաղաքի ժամանակագրություն, memorialmuseums.org «Memorials in Pskov» — որոնման ամփոփում [ամփոփում]։", "c875c7b2"]},
"OLAYLAR_EK16:1941-07-11:0":{"b": ["Գերմանական բանակը վերցրեց Վիտեբսկը", "e1e4d7d0"], "d": ["Կենտրոն բանակային խումբը Վիտեբսկը վերցրեց «Բարբարոսա» գործողության առաջին շաբաթներին. քաղաքը մինչև 1944 թ. հունիսը մնաց գերմանական ռազմական կառավարման տակ, բնակչության մեծ մասը ոչնչացվեց։", "aeb95ab0"]},
"OLAYLAR_EK16:1941-07-16:0":{"b": ["Գերմանական բանակը վերցրեց Սմոլենսկը", "5a7f4e2a"], "d": ["Կենտրոն բանակային խումբը վերցրեց Սմոլենսկը. Մոսկվա տանող ճանապարհի վրա գտնվող այս քաղաքը մինչև 1943 թ. սեպտեմբերի 25-ը 26 ամիս մնաց օկուպացիայի տակ և մեծ ավերածություն կրեց։", "1cff2f04"]},
"OLAYLAR_EK16:1941-07-26:0":{"b": ["Գերմանական բանակը վերցրեց Մոգիլյովը", "4362b7a1"], "d": ["23 օր տևած պաշտպանությունից հետո Մոգիլյովն անցավ Վերմախտի ձեռքը. քաղաքը մինչև 1944 թ. հունիսի 28-ը մնաց օկուպացիայի տակ։", "082ca73b"]},
"OLAYLAR_EK16:1941-07-28:0":{"b": ["Հիմնվեց Reichskommissariat Ostland-ը. Մերձբալթյան երկրներն ու Բելառուսը անցան գերմանական քաղաքացիական կառավարման", "052d4c08"], "d": ["Հիտլերի 1941 թ. հուլիսի 17-ի որոշմամբ Արևելքի օկուպացված հողերը հանձնվեցին քաղաքացիական կառավարմանը. Հինրիխ Լոզեի գլխավորած Օստլանդը ընդգրկում էր Էստոնիան, Լատվիան, Լիտվան և Բելառուսը (կենտրոն՝ Ռիգա)։ Էստոնիայում քաղաքացիական կառավարումը՝ 1941 թ. դեկտեմբերի 5-ին, Բելառուսի արևելքը մնաց ռազմական կառավարման տակ։", "83f60be8"]},
"OLAYLAR_EK16:1941-08-17:0":{"b": ["Գերմանա-էստոնական ուժերը վերցրին Նարվան", "60fc2b6a"], "d": ["Ամառային պատերազմում էստոնացի կամավորներն ու Վերմախտը վերցրին Նարվան. քաղաքը ներառվեց Օստլանդի մեջ և մինչև 1944 թ. հուլիսի 26-ը մնաց գերմանական կառավարման տակ։", "0f32445c"]},
"OLAYLAR_EK16:1941-08-19:0":{"b": ["Գերմանական բանակը վերցրեց Նովգորոդը", "4f599b62"], "d": ["Հյուսիս բանակային խումբը վերցրեց Նովգորոդը. Ռուսաստանի ամենահին քաղաքներից մեկը մինչև 1944 թ. հունվարը մնաց օկուպացիայի տակ և մեծ մասամբ ավերվեց։", "ac0d4ff0"]},
"OLAYLAR_EK16:1941-08-19:1":{"b": ["Գերմանական բանակը վերցրեց Գոմելը", "9d78eb92"], "d": ["Վերմախտի՝ Գոմելի վրա հարձակումից երեք օր անց Կարմիր բանակը լիովին դուրս եկավ քաղաքից. այն մինչև 1943 թ. նոյեմբերի 26-ը մնաց օկուպացիայի տակ։", "56a11e36"]},
"OLAYLAR_EK16:1941-08-28:0":{"b": ["Գերմանական 18-րդ բանակը վերցրեց Տալլինը", "a855ad0d"], "d": ["Խորհրդային Բալթյան նավատորմի արյունոտ տարհանումով դեպի Կրոնշտադտ Տալլինն ընկավ. Էստոնիան Օստլանդի ներսում դարձավ Generalbezirk Estland (1941 թ. դեկտեմբերի 5-ին՝ քաղաքացիական կառավարում)։", "859cfaf1"]},
"OLAYLAR_EK16:1941-10-03:0":{"b": ["Գերմանական բանակը վերցրեց Օրյոլը", "3127f454"], "d": ["Բրյանսկ-Վյազմայի գործողության ժամանակ գերմանական 2-րդ տանկային բանակը վերցրեց Օրյոլը. քաղաքը մինչև 1943 թ. օգոստոսի 5-ը մնաց օկուպացիայի տակ։", "f5465227"]},
"OLAYLAR_EK16:1941-10-06:0":{"b": ["Գերմանական բանակը վերցրեց Բրյանսկը", "20fa93f8"], "d": ["Բրյանսկի ճակատամարտի վերջում գերմանական ուժերը մտան քաղաք. այն մինչև 1943 թ. սեպտեմբերի 17-ը մնաց օկուպացիայի տակ։", "f4a24f91"]},
"OLAYLAR_EK16:1941-11-03:0":{"b": ["Գերմանական բանակը վերցրեց Կուրսկը", "a723a00a"], "d": ["Խորհրդային հրամանատարության հրամանով Կուրսկը դատարկվեց, և գերմանական 2-րդ բանակը մտավ քաղաք. այն մինչև 1943 թ. փետրվարի 8-ը մնաց օկուպացիայի տակ։", "0d07184e"]},
"OLAYLAR_EK16:1943-02-08:0":{"b": ["Կարմիր բանակը ազատագրեց Կուրսկը", "1ac03fba"], "d": ["Խորհրդային ձմեռային հարձակման (Վորոնեժ-Կաստորնոյեի գործողությանը հաջորդած Կուրսկ-Խարկով ուղղություն) վերջում Կուրսկը հետ վերցվեց. նույն տարվա հուլիսին քաղաքի անունը տրվեց Կուրսկի ճակատամարտին։", "68d51be4"]},
"OLAYLAR_EK16:1943-08-05:0":{"b": ["Կարմիր բանակը հետ վերցրեց Օրյոլը. Կուրսկից հետո առաջին խորհրդային սալյուտը", "80bfc68d"], "d": ["Օրյոլի ելուստի գրավումը և Բելգորոդի հետ միասին Մոսկվայում առաջին հրետանային սալյուտի արձակումը։", "5714054b"]},
"OLAYLAR_EK16:1943-09-17:0":{"b": ["Կարմիր բանակը հետ վերցրեց Բրյանսկը", "d0f2a35f"], "d": ["Բրյանսկի գործողությամբ քաղաքը հետ վերցվեց 1943 թ. սեպտեմբերի 17-ին։", "e6b7799d"]},
"OLAYLAR_EK16:1943-09-25:0":{"b": ["Կարմիր բանակը ազատագրեց Սմոլենսկը", "6516d85a"], "d": ["1943 թ. օգոստոսի 7-ից հոկտեմբերի 2-ը տևած Սմոլենսկի գործողության գագաթնակետին քաղաքը հետ վերցվեց. Սմոլենսկը 1985 թ. ստացավ «հերոս քաղաք» կոչումը։", "e355d898"]},
"OLAYLAR_EK16:1943-11-26:0":{"b": ["Կարմիր բանակը ազատագրեց Գոմելը", "280268c2"], "d": ["Բելառուսական ռազմաճակատը Գոմել-Ռեչիցայի գործողությամբ հետ վերցրեց քաղաքը. սա Բելառուսի առաջին խոշոր քաղաքների ազատագրումներից մեկն է։", "3402c1b4"]},
"OLAYLAR_EK16:1944-01-20:0":{"b": ["Կարմիր բանակը ազատագրեց Նովգորոդը", "52962012"], "d": ["Լենինգրադ-Նովգորոդյան գործողության ժամանակ Վելիկի Նովգորոդը հետ վերցվեց 1944 թ. հունվարի 20-ին։", "75ea1a61"]},
"OLAYLAR_EK16:1944-06-26:0":{"b": ["Կարմիր բանակը ազատագրեց Վիտեբսկը. «Բագրատիոն» գործողությունը", "b06be69c"], "d": ["1-ին մերձբալթյան և 3-րդ բելառուսական ռազմաճակատները շրջապատեցին և վերցրին Վիտեբսկը. սա «Բագրատիոն» գործողության առաջին խոշոր քաղաքի ազատագրումն էր։", "9b4d6042"]},
"OLAYLAR_EK16:1944-06-28:0":{"b": ["Կարմիր բանակը ազատագրեց Մոգիլյովը. «Բագրատիոն» գործողությունը", "52fa985d"], "d": ["2-րդ բելառուսական ռազմաճակատը վերցրեց Մոգիլյովը և հատեց Դնեպրի գիծը։", "22c05c20"]},
"OLAYLAR_EK16:1944-07-03:0":{"b": ["Կարմիր բանակը հետ վերցրեց Մինսկը. «Բագրատիոն» գործողությունը", "87dc1fb5"], "d": ["Հունիսի 22-ին սկսված «Բագրատիոն» գործողության ընթացքում բելառուսական ռազմաճակատները, ճեղքելով Կենտրոն բանակային խումբը, շրջապատեցին Մինսկը. քաղաքը հետ վերցվեց հուլիսի 3-ին, և արևելքում մոտ 50 հազար գերմանացի զինվոր մնաց շրջապատման մեջ։ Բելառուսում գերմանական քաղաքացիական կառավարումը (Generalbezirk Weißruthenien) փլուզվեց։", "1c35549f"]},
"OLAYLAR_EK16:1944-07-13:0":{"b": ["Կարմիր բանակը վերցրեց Վիլնյուսը", "0172450e"], "d": ["Հուլիսի 5-13-ի Վիլնյուսի գործողության ժամանակ 3-րդ բելառուսական ռազմաճակատը, շրջապատելով գերմանական կայազորը, վերցրեց քաղաքը (Լեհական Ներքին բանակի «Օստրա Բրամա» գործողությունը ընթացավ միաժամանակ)։ Վիլնյուսը դարձավ Լիտվական ԽՍՀ մայրաքաղաքը։", "aaf124b7"]},
"OLAYLAR_EK16:1944-07-16:0":{"b": ["Կարմիր բանակը Գրոդնոն ազատագրեց գերմանական օկուպացիայից", "1d134151"], "d": ["Արևելյան ռազմաճակատ. 1941 թ. «Բարբարոսա» և 1944 թ. «Բագրատիոն»։", "c6101096"]},
"OLAYLAR_EK16:1944-07-23:0":{"b": ["Կարմիր բանակը հետ վերցրեց Պսկովը", "f18103aa"], "d": ["Ավելի քան երեք տարի տևած գերմանական օկուպացիայից հետո Կարմիր բանակը հետ վերցրեց Պսկովը։", "b6fb3c84"]},
"OLAYLAR_EK16:1944-07-26:0":{"b": ["Կարմիր բանակը վերցրեց Նարվան", "64854ae3"], "d": ["1944 թ. փետրվարից ռազմաճակատի գծում ավերակ դարձած Նարվան խորհրդային ուժերը վերցրին 1944 թ. հուլիսի Նարվայի գործողության ժամանակ. Էստոնիայի հյուսիս-արևելքը դուրս եկավ գերմանական քաղաքացիական կառավարումից (Generalbezirk Estland)։", "74009a05"]},
"OLAYLAR_EK16:1944-07-27:0":{"b": ["Կարմիր բանակը վերցրեց Ռեզեկնեն. Լատվիայի արևելքը ազատագրվեց", "e9efd12d"], "d": ["2-րդ մերձբալթյան ռազմաճակատը վերցրեց Ռեզեկնեն. Լատվիայի Լատգալե շրջանը դուրս եկավ գերմանական կառավարումից։", "eac95aa6"]},
"OLAYLAR_EK16:1944-07-27:1":{"b": ["Կարմիր բանակը ազատագրեց Դաուգավպիլսը", "b4ee6622"], "d": ["2-րդ մերձբալթյան ռազմաճակատի 360-րդ հետևակային դիվիզիան վերցրեց Դաուգավպիլսը (Դյունաբուրգ). Լատգալեի երկրորդ խոշոր քաղաքը դուրս եկավ գերմանական կառավարումից։", "b8a7bd0d"]},
"OLAYLAR_EK16:1944-07-27:2":{"b": ["Կարմիր բանակը վերցրեց Շյաուլյայը. Շյաուլյայի գործողությունը", "ccb20729"], "d": ["1-ին մերձբալթյան ռազմաճակատը վերցրեց Լիտվայի հյուսիսի երկաթուղային հանգույց Շյաուլյայը. գործողությունը տևեց 1944 թ. հուլիսի 5-ից օգոստոսի 29-ը, և զորքերը հասան Ռիգայի ծոցին։", "444f3101"]},
"OLAYLAR_EK16:1944-07-28:0":{"b": ["Կարմիր բանակը Բրեստ-Լիտովսկը ազատագրեց գերմանական օկուպացիայից", "6d5a837a"], "d": ["Արևելյան ռազմաճակատ. 1941 թ. «Բարբարոսա» և 1944 թ. «Բագրատիոն»։", "c6101096"]},
"OLAYLAR_EK16:1944-08-01:0":{"b": ["Կարմիր բանակը վերցրեց Կաունասը. Լիտվայի ժամանակավոր մայրաքաղաքը դուրս եկավ գերմանական կառավարումից", "5c2b2c16"], "d": ["3-րդ բելառուսական ռազմաճակատը վերցրեց Կաունասը. Ստալինի օգոստոսի 1-ի օրվա հրամանը ազդարարեց գրավումը։ Քաղաքը 1919-1939 թվականներին Լիտվայի ժամանակավոր մայրաքաղաքն էր։", "795fab27"]},
"OLAYLAR_EK16:1944-08-25:0":{"b": ["Կարմիր բանակը վերցրեց Տարտուն. Տարտուի գործողությունը", "cc8069ab"], "d": ["3-րդ մերձբալթյան ռազմաճակատը, ճեղքելով գերմանական 18-րդ բանակի պաշտպանությունը, վերցրեց Տարտուն. քաղաքը մի քանի շաբաթ մնաց ռազմաճակատի գծում, և Տարտուի գործողությունն ավարտվեց 1944 թ. սեպտեմբերի 6-ին։", "3e9ef2ba"]},
"OLAYLAR_EK16:1944-09-22:0":{"b": ["Կարմիր բանակը մտավ Տալլին. գերմանական ուժերը լքեցին քաղաքը", "41ae1ec5"], "d": ["Տալլինի գործողության ժամանակ գերմանացիները լքեցին քաղաքը. սեպտեմբերի 18-ին կառավարական շենքերը վերցրած Էստոնիայի Ազգային կոմիտեի կառավարությունը չկարողացավ պահել իշխանությունը, երբ Կարմիր բանակը մտնում էր քաղաք։ Էստոնիան կրկին անցավ խորհրդային կառավարման տակ։", "a229e09c"]},
"OLAYLAR_EK16:1945-01-28:0":{"b": ["Կարմիր բանակը վերցրեց Մեմելը (Կլայպեդա)", "d01ad3dc"], "d": ["Արևելյան Պրուսիա և Բալթյան ափ ուղղված խորհրդային գործողության ժամանակ Մեմել (Կլայպեդա) նավահանգիստը խլվեց Գերմանիայի ձեռքից և կապվեց Լիտվական ԽՍՀ-ին։ 1939 թ. Գերմանիային հանձնված շրջանն այսպիսով դուրս եկավ գերմանական կառավարումից։", "65cf6a00"]},
"OLAYLAR_EK16:1945-05-08:0":{"b": ["Կուրլանդիայի գրպանը անձնատուր եղավ. Courland Army Group-ը Գովորովին ստորագրեց հանձնումը", "3c88889b"], "d": ["1944 թ. հոկտեմբերից Լիեպայա-Վենտսպիլս շրջակայքում պաշարված գերմանական Կուրլանդիայի բանակային խումբը անձնատուր եղավ. Լատվիայի արևմուտքը անցավ խորհրդային վերահսկողության տակ։", "a7bfcc52"]},
"OLAYLAR_EK16:1955-12-01:0":{"b": ["Օմանի սուլթանի ուժերը մտան ներքին Օմանի հիմնական կենտրոնները. Իբադական իմամությունը փաստացի վերացավ", "9a9962a5"], "d": ["1955 թ. դեկտեմբերին Օմանի սուլթանը գործի անցավ իր իշխանությունը վերականգնելու համար, և նրա ուժերը մտան ներքին Օմանի հիմնական բնակավայրերը (Բահլա, Իզկի, Նիզվա). Իբադական իմամության կառավարումը ներքին Օմանի նկատմամբ փաստացի վերացավ։ Աղբյուրը տալիս է միայն ամիսը. քարտեզում ցույց է տրվում 1955 թ. դեկտեմբերի 1-ը։", "31f8761e"]},
"OLAYLAR_EK16:1961-06-19:0":{"b": ["Քուվեյթը, դուրս գալով անգլիական հովանուց, ձեռք բերեց լիակատար անկախություն", "e9a86d04"], "d": ["Քուվեյթի և Միացյալ Թագավորության միջև 1961 թ. հունիսի 19-ին փոխանակված նոտաներով ավարտվեց 1899 թ. համաձայնագրից ի վեր տևող անգլիական հովանավորությունը, և Քուվեյթը դարձավ լիովին անկախ։ Քարտեզում Քուվեյթի անգլիական շերտը ավարտվում է այս օրը։", "eb64fb65"]},
"OLAYLAR_EK16:1971-09-03:0":{"b": ["Կատարը Անգլիայի հետ պայմանագրերի ավարտով հռչակեց իր անկախությունը", "8f288cc6"], "d": ["Մեծ Բրիտանիայի հետ կնքված պրոտեկտորատի պայմանագրերի ավարտի օրվանից հետո Կատարը 1971 թ. սեպտեմբերի 3-ին հռչակեց իր անկախությունը։ Քարտեզում Դոհայի անգլիական շերտը ավարտվում է այս օրը։", "997a4b35"]},
"OLAYLAR_EK17:1369-01-01:0":{"b": ["Իստրանջայի բերդերը. Փընարհիսարի, Քըրքքիլիսեի (Քըրքլարելի) և Վիզեի գրավումը", "c6b1a9c1"], "d": ["1369 թ. ձմեռն Էդիրնեի պալատում անցկացրած Մուրադ I-ը գարնանը կրկին գործի անցավ Բյուզանդիայի դեմ և գրավեց Իստրանջայի լեռների ստորոտի Փընարհիսար, Քըրքքիլիսե և Վիզե բերդերը։ Այս նվաճումները խուճապ առաջացրին Կոստանդնուպոլսում, և Հովհաննես V կայսրը որոշեց գնալ պապի մոտ՝ օգնություն խնդրելու։", "61aac0e3"]},
"OLAYLAR_EK17:1485-01-01:0":{"b": ["Տաշքենդն անցավ Մողուլիստանի խան Յունուս խանի կառավարման", "a37ee010"], "d": ["Թեմուրյան արքայազների միջև գահի պայքարի ժամանակ Տաշքենդն ու շրջակայքը անցան Արևելյան Չաղաթայի (Մողուլիստան) խան Յունուս խանի ձեռքը։ Երկու տարի անց Յունուս խանի մահից հետո նրան հաջորդեց որդին՝ Մահմուդ խանը. քաղաքը մողուլ խաների ձեռքին մնաց, մինչև 1503 թ. Շեյբանի խանի ուզբեկները վերցրին այն։", "07459832"]},
"OLAYLAR_EK17:1504-01-01:0":{"b": ["Բաբուրը Ֆերղանան թողեց ուզբեկներին և գնաց Քաբուլ", "69df593c"], "d": ["Օմար Շեյխ Միրզայի որդի Թեմուրյան Բաբուրը, 1494 թվականից իր իշխած Ֆերղանան Մուհամմեդ Շեյբանի խանի հետ մղած պատերազմներից հետո թողեց ուզբեկներին և, անցնելով Հինդուքուշը, հաստատվեց Քաբուլում։", "21d1ed8c"]},
"OLAYLAR_EK17:1513-01-01:0":{"b": ["Փիրի ռեիսը գծեց մեր օրերը հասած ամենահին աշխարհի քարտեզը", "6ef941f5"], "d": ["Փիրի ռեիսը Գելիբոլուում գծեց հիջ. 919 (1513) թվագրված աշխարհի քարտեզը. ըստ TDV İslâm Ansiklopedisi-ի՝ քարտեզի աղբյուրների թվում են «Արևելքի և Արևմուտքի աշխարհից իրեն հասած հին քարտեզները և Քրիստափոր Կոլումբոսի քարտեզը», այսինքն՝ ենթադրվում է, որ այն կրում է Կոլումբոսի՝ այն ժամանակ կորած համարվող բնագիր նավարկային քարտեզի հետքերը։ Քարտեզը հիջ. 923 (1517) թ. Կահիրեում նա մատուցեց Յավուզ Սուլթան Սելիմին։ Մեր օրերը հասել է միայն արևմտյան/ատլանտյան ափերը (Իսպանիա, Պորտուգալիա, Արևմտյան Աֆրիկա, Հարավային Ամերիկայի արևելյան ափ) ցույց տվող մի հատված. այդ հատվածը 1929 թ. կրկին լույս աշխարհ հանվեց Թոփքափը պալատում և գտնվում է ՅՈՒՆԵՍԿՕ-ի «Աշխարհի հիշողություն» ցուցակում։", "78561b0b"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["Կարսի շրջակայքի ամբողջացումը. Շուրագյալը, Արփաչայը և Դիգորը անցան օսմանյան կառավարման", "10f16b5c"], "d": ["Իրաքեյնի արշավանքի ժամանակ Պասենի, Շուրագյալի և Օլթիի բերդերը անցան օսմանցիների ձեռքը. մեծ հավանականությամբ Կարսի բերդն էլ այդ ժամանակ է կապվել։ Կարսից հյուսիս և արևելք ընկած Արփաչայի և Դիգորի շրջանը նույն գործողությամբ անցավ օսմանյան վերահսկողության տակ։", "f8a4288a"]},
"OLAYLAR_EK17:1538-10-01:0":{"b": ["Շիրվանշահների վերջը. Ալքաս Միրզան գերեց Շահռուխին, Շիրվանը դարձավ սեֆյան նահանգ", "e6d64114"], "d": ["Շահ Թահմասպի ուղարկած Ալքաս Միրզան թալանեց Շիրվանը, գրավեց Բայկուրդի բերդը և, գերելով տասնհինգամյա Շիրվանշահ Շահռուխին, տարավ Թավրիզ։ Այսպիսով ավարտվեց շրջանում երկար ժամանակ իր տիրապետությունը պահպանած Շիրվանշահների կառավարումը. Շիրվանը դարձավ Սեֆյան պետության նահանգ։", "47532c27"]},
"OLAYLAR_EK17:1552-01-01:0":{"b": ["Ալժիրի օջախի ընդարձակումը դեպի Սահարա. Թուգուրթ-Ուարգլան խարաջի կապվեցին, Թլեմսենը վերջնականապես գրավվեց", "705ec920"], "d": ["TDV-ի «Թլեմսեն» հոդվածի համաձայն՝ հիջ. 960 (1553) թ. Ալժիրից ուղարկված մեծ բանակը Սալիհ ռեիսի հրամանատարությամբ վերջնականապես գրավեց քաղաքը և վերջ դրեց երեքդարյա Զայյանյան հարստությանը։ Նույն շրջանում (1552) Սալիհ ռեիսը արշավանք կազմակերպեց անկախ սուլթանություններ Թուգուրթի և Վարգլայի դեմ. օսմանյան ուժերը վերցրին Թուգուրթը, առաջացան դեպի Վարգլա, երկու սուլթանությունները խարաջի կապվեցին. ճանապարհի Բիսկրայում թողնվեց մշտական օսմանյան կայազոր։ Այսպիսով Ալժիրի օջախի սահմանը առաջին անգամ անցավ Թել Ատլասը և հասավ Սահարայի եզրին։ Մոստագանեմի մոտ մեծ ճակատամարտը, սակայն, տեղի ունեցավ ոչ թե այս տարի, այլ 1558 թ.. Հասան փաշան այնտեղ հաղթեց իսպանական կոմս Ալկաուդետեին և վերջ դրեց Հյուսիսային Աֆրիկայում իսպանական հարձակումներին։", "da55aa7d"]},
"OLAYLAR_EK17:1557-01-01:0":{"b": ["Հաբեշի էյալեթի հիմնումը. Կարմիր ծովի ափի անցումը օսմանյան կառավարման", "7dd470ec"], "d": ["Պորտուգալիայի՝ Եթովպիայի վրայով Կարմիր ծով ներթափանցումը կանխելու համար հիմնված էյալեթը, ըստ TDV-ի «Հաբեշի էյալեթ» հոդվածի, պաշտոնապես հիմնվեց հիջ. 962 թ. Շաաբան ամսի 15-ին (1555 թ. հուլիսի 5), սանջակի կենտրոնը Սուաքինն էր։ Օզդեմիր փաշան 1555 թ. աշնանը սկսեց գործողությունը. գրավեց Մասավվա նավահանգիստը վերահսկող Դահլակի կղզիները և 1557 թ. ապրիլի 2-ին վերցրեց Մասավվա քաղաքը, ապա՝ Արքիքոն։ Գրավումը շարունակվեց Տիգրե նահանգի՝ 1558 թ. և Դեբարվայի՝ 1559 թ. օսմանյան տիրապետության տակ անցնելով։", "7bb5b28b"]},
"OLAYLAR_EK17:1606-10-11:0":{"b": ["Սեդեֆքյար Մեհմեդ աղան նշանակվեց գլխավոր ճարտարապետ. Սուլթանահմեդ մզկիթի ճարտարապետը", "27b66fce"], "d": ["Ալբանիայի Էլբասան ավանից 1562-63 թվականներին դևշիրմեով պալատ վերցված Մեհմեդ աղան, կրթվելով ճարտարապետ Սինանի մոտ, 1606 թ. հոկտեմբերի 11-ին նշանակվեց օսմանյան գլխավոր ճարտարապետ։ TDV İslâm Ansiklopedisi-ն հաղորդում է, որ ժամանակակից մի աղբյուր նրան նկարագրում է որպես «մեղմաբարո, համեստ, խոսքի տեր, բարեպաշտ և խելացի»։ Երեք տարի անց Ահմեդ I-ի հրամանով Սուլթանահմեդ մզկիթի շինարարությանը ձեռնամուխ եղած Մեհմեդ աղան իր ստորագրությունը դրեց լայն ժառանգության տակ՝ Քաաբայի վերանորոգումներից մինչև Ստամբուլի և Էդիրնեի բազմաթիվ աղբյուրներ ու մզկիթներ։ Այն, որ վեց մինարեթը Մեքքայի Քաաբայի հետ «հավասարության» վեճի տեղիք է տվել, տարածված ժողովրդական պատում է. հանրագիտարանային աղբյուրները դա չեն հաստատում, լուծումը բնութագրում են միայն որպես «մինչ այդ չփորձված»։", "a4c538fd"]},
"OLAYLAR_EK17:1617-11-22:0":{"b": ["Նոր փադիշահ Մուստաֆա I. գահին՝ գունատ դեմքով, մտացիր հայացքով «վանդակի» կալանավորը", "c487b0d1"], "d": ["Ահմեդ I-ի մահով գահ բարձրացած Մուստաֆա I-ը, լինելով եղբոր ողջ թողած առաջին շահզադեն, տարիներ շարունակ խիստ հսկողության տակ փակված էր ապրել պալատում. TDV İslâm Ansiklopedisi-ն նրան նկարագրում է որպես «գունատ դեմքով, նոսր մորուքով, խոշոր սև աչքերով, սառած հայացքով» և արձանագրում, որ երկարատև այս բանտարկությունը ծանրացրել էր նրա հոգեկան վիճակը։ Իննսունվեց օր տևած այս առաջին թագավորության ընթացքում նա չկարողացավ վարել պետական գործերը. փոխարենը, ըստ ավանդության, հաճախ որսի էր գնում, շրջում նավաշինարանում, անգամ ոսկի էր նետում ջուրը և դիտում ձկներին։ Ենիչերիները, օջախը և ուլեման, նրան թագավորելու անպիտան համարելով, 1618 թ. փետրվարի 26-ին գահընկեց արին և նրա փոխարեն բազմեցրին տասնչորսամյա եղբորորդուն՝ Օսման II-ին։", "f2d36b20"]},
"OLAYLAR_EK17:1630-08-19:0":{"b": ["Էվլիյա Չելեբիի ճամփորդության երազը. «շեֆաաթ» ասելու փոխարեն «սեյահաթ» ասելը", "2d863e22"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի՝ Էվլիյա Չելեբին իր քառասուն տարի տևելիք ճամփորդական կյանքի սկիզբը կապում է հիջ. 1040 թ. Մուհառամի աշուրայի գիշերը (1630 թ. օգոստոսի 19) տեսած երազի հետ. երազում Ստամբուլի Ահի Չելեբի մզկիթում բազմամարդ համայնքի հետ տեսնում է Մարգարեին և հուզմունքից «շեֆաաթ, ո՛վ Աստծո առաքյալ» (բարեխոսություն) ասելու փոխարեն ասում է «սեյահաթ, ո՛վ Աստծո առաքյալ» (ճամփորդություն)։ Ըստ ավանդության՝ Մարգարեն, ժպտալով այս լեզվի սայթաքմանը, նրան ավետում է և՛ բարեխոսություն, և՛ ճամփորդություն, և՛ ուխտագնացություն։ Նա երբեք չամուսնացավ և կյանքը նվիրեց «ճամփորդության» այս խոստմանը։", "ede1feb4"]},
"OLAYLAR_EK17:1632-01-01:0":{"b": ["Մուրադ IV-ի հակասությունները. խմիչքի սիրահար փադիշահի խմիչքի արգելքը, ըմբիշի դաստակ, կոմպոզիտորի ականջ", "3d2ea5e0"], "d": ["Տասնմեկ տարեկանում գահ բարձրացած Մուրադ IV-ի առաջին տարիներին վճռորոշ էր նրա մոր՝ Քյոսեմ սուլթանի ազդեցությունը. TDV İslâm Ansiklopedisi-ն հաղորդում է, որ Քյոսեմը, զգուշանալով որդու՝ իշխանության հակումից, նրան «մղում էր զվարճանքի, զբաղեցնում էր նվերներով և տոնախմբություններով»։ Երբ մոտ քսան տարեկանում նա փաստացի իր ձեռքն առավ կառավարումը, բարձրահասակ, լայնաթիկունք, վեհաշուք տիրակալ էր. ըստ ավանդության՝ մի ուժեղ մարդու գոտուց բռնելով բարձրացրել և Հաս Օդայում մի քանի անգամ ման է ածել։ TDV-ի արձանագրած ապշեցուցիչ հակասությունը սա է. ասվում է, որ փադիշահը ատում էր ծխախոտն ու ափիոնը, բայց չափից ավելի հակված էր խմիչքի. չնայած դրան, արշավանքից առաջ արգելեց սուրճը, ծխախոտը, ապա և խմիչքը. միաժամանակ նա երաժշտական գիտելիք ուներ այնքան, որ կարող էր մակամի ավանդույթին համապատասխան երաժշտություն հորինել։", "f2aba572"]},
"OLAYLAR_EK17:1632-01-01:1":{"b": ["Լագարի Հասան Չելեբիի թռիչքը հրթիռով. ավանդություն, որի միակ աղբյուրը Էվլիյա Չելեբին է", "1f02e3f2"], "d": ["Ըստ Էվլիյա Չելեբիի «Սեյահաթնամե»-ի՝ Լագարի Հասան Չելեբին Մուրադ IV-ի ներկայությամբ Սարայբուրնուում հիսուն օքա վառոդով պատրաստեց յոթթևանի հրթիռային սարք և ասելով՝ «Փադիշա՛հ իմ, քեզ Աստծուն եմ հանձնում, գնում եմ Հիսուս մարգարեի հետ զրուցելու», նստեց հրթիռին։ Ըստ ավանդության՝ մոտ 250 մետր բարձրացած Հասան Չելեբին բազեի թևերի նման սարքերով սահելով իջավ ծով, լողալով վերադարձավ փադիշահի մոտ և փոխարենը ստացավ յոթանասուն ակչե օրավարձով սիպահիության պաշտոն։", "ef620ef6"]},
"OLAYLAR_EK17:1638-12-24:0":{"b": ["Քեմանքեշ Կարա Մուստաֆա փաշան դարձավ մեծ վեզիր. սկսվեց ֆինանսական բարեփոխումների շրջանը", "583846a4"], "d": ["Բաղդադի արշավանքում Թայյար Մեհմեդ փաշայի նահատակությունից հետո հիջ. 1048 թ. Շաաբան ամսի 17-ին (1638 թ. դեկտեմբերի 24) մեծ վեզիր դարձած Քեմանքեշ Կարա Մուստաֆա փաշան սուլթան Իբրահիմի օրոք կիրառեց խիստ ֆինանսական կարգապահություն. ենիչերիների և սիպահիների թիվը իջեցրեց մեկ երրորդի, բարելավեց դրամի հարգը, խստացրեց նարխի համակարգը։ TDV-ի բերած թվով՝ այս խնայողությունը տարեկան հասավ 6000 քսակի. բայց այս խիստ վերահսկողությունը նրան թշնամիներ վաստակեց պալատական շրջանակներում։", "2de299c2"]},
"OLAYLAR_EK17:1639-01-20:0":{"b": ["Մուստաֆա I-ը մահացավ տասնհինգամյա մոռացությունից հետո", "b4c872cd"], "d": ["1623 թ. սեպտեմբերի 10-ին երկրորդ անգամ գահընկեց արված Մուստաֆա I-ը մինչև մահը անցած տասնհինգ տարիներն ապրեց մի սենյակում, ուր նրան փակ էին պահում. աղբյուրներում այդ տարիների մասին ոչ մի տեղեկություն չկա։ Նա մահացավ հիջ. 1048 թ. Ռամադան ամսի 15-ին (1639 թ. հունվարի 20). աղբյուրների մի մասը դա համարում է բնական մահ, իսկ մի մասը պնդում է, որ դրանում Մուրադ IV-ի ձեռքը կա։", "f153eced"]},
"OLAYLAR_EK17:1644-01-01:0":{"b": ["«Խելագար Իբրահի՞մ», թե՞ ալիքաձև ընթացող հիվանդություն", "2abc230f"], "d": ["TDV İslâm Ansiklopedisi-ն բացահայտ մերժում է 20-րդ դարում տարածված «Խելագար Իբրահիմ» մակդիրը. հաղորդում է, որ փադիշահն իր իսկ նամակներում գանգատվում է ցավերից, ախորժակի կորստից, ոտքերի թուլությունից, գլխում մշուշի զգացումից, կրծքի սեղմումից և ուշագնացության նոպաներից։ Մինչդեռ գահազրկման ընթացքում նրա հետևողական և ողջամիտ պատասխանները հակասում են մշտական անհավասարակշռության պնդմանը. հոդվածը եզրակացնում է, որ նրա վիճակը «կայուն չէր, այլ փոփոխական սրությամբ» էր ընթանում։ Այդ շրջանում Քյոսեմ սուլթանի պատասխանատվությունները գնալով մեծացան, իսկ պալատ կանչված Ջինջի խոջայի՝ «ազդեցիկ աղոթքներով» փադիշահին հոգևոր մխիթարություն մատուցելը ուժեղացրեց նրա՝ քաղաքականությանը միջամտելու կարողությունը։", "f3705d31"]},
"OLAYLAR_EK17:1647-01-01:0":{"b": ["Սամուրի դեպքը. մեծ վեզիր Ահմեդ փաշայի մորթու հարկը նախապատրաստեց Իբրահիմի վախճանը", "a2a47d62"], "d": ["Մինչ պալատում սուլթան Իբրահիմի սամուրե մուշտակի և սաթի հանդեպ կիրքը գնալով աճում էր, մեծ վեզիր Ահմեդ փաշան մոտ 1647-1648 թվականներին ներմուծեց մի կիրառություն, որով պետական այրերից բռնի հավաքվում էր սամուրե մուշտակի գինը. TDV İslâm Ansiklopedisi-ն արձանագրում է, որ պաշտոնյաները դա դիտում էին որպես բացահայտ «խարաջ»։ Երբ ենիչերիական սպաները միասնաբար մերժեցին վճարել, այս դիմադրությունը դարձավ փադիշահի գահընկեցության հանգեցրած ընթացքի անմիջական կայծը. 1648 թ. օգոստոսի 7-ի առավոտյան հավաքված պաշտոնյաները նախ սպանեցին Ահմեդ փաշային, հաջորդ օրը գահընկեց արին Իբրահիմին։", "596c6d08"]},
"OLAYLAR_EK17:1648-05-01:0":{"b": ["«Պետությունը կանայք են կառավարում». Վարվար Ալի փաշայի ապստամբությունը Սեբաստիայից", "5b027357"], "d": ["Սեբաստիայի բեյլերբեյ Վարվար Ալի փաշան, ասելով՝ «Սեբաստիայի տարեկան եկամուտը այս գումարը չի ծածկում», հրաժարվեց վճարել Ստամբուլի՝ «բայրամիյե» անունով պահանջած 30.000 ղուրուշը. ըստ TDV İslâm Ansiklopedisi-ի՝ նրա ապստամբության հիմնավորումն այն պնդումն էր, որ փադիշահի հիվանդության պատճառով պետական գործերն անցել են կանանց ձեռքը, և դա կուսակալների հաճախակի փոփոխություններով անկայունություն է ծնում։ 1648 թ. մայիսին թեև սկզբում ռազմական հաջողություն ունեցավ, պարտվեց Իփշիր Մուստաֆա փաշային, 1648 թ. մայիսի 20-ին մահապատժի ենթարկվեց, և նրա գլուխն ուղարկվեց Ստամբուլ։", "e45166db"]},
"OLAYLAR_EK17:1686-08-30:0":{"b": ["Վենետիկին կորցրած Նաֆպլիոնը. Մորեայի պատերազմի շրջադարձային կետը", "9d400557"], "d": ["TDV-ի «Անաբոլու» հոդվածի համաձայն՝ պաշարման ընթացքում քաղաքի մուսուլման բնակչությունից ողջ մնացածները փախան շրջակա կղզիներ և Անատոլիա (1686)։ Ընդունված ակադեմիական աղբյուրի համաձայն (Setton, Venice, Austria, and the Turks in the Seventeenth Century)՝ Քյոնիգսմարկի ուժերը երկու շաբաթ ետ մղեցին օսմանյան օգնական բանակի հարձակումները. երբ օգոստոսի 29-ին Իսմայիլ փաշայի գրոհն ավարտվեց ծանր պարտությամբ, բերդը մի քանի օրում հանձնվեց։ Նաֆպլիոնը 1540 թ. պայմանագրով ստացված օսմանյան հող էր. նրա կորստով արագացավ Մորեայի թերակղզու անցումը Վենետիկին։", "592908a0"]},
"OLAYLAR_EK17:1687-08-01:0":{"b": ["Մեհմեդ IV-ը հրաժարվեց որսից. վերջին ջանքը գահազրկման նախօրեին", "7daa904b"], "d": ["Մոհաչի պարտությունից (1687 թ. օգոստոս) հետո ռոճիկ չստացած բանակը ապստամբեց և շարժվեց Ստամբուլի վրա։ Մեհմեդ IV-ը մահապատժի ենթարկել տվեց մեծ վեզիրի կնիքը տարած Սուլեյման փաշային, նրա գլուխը ցույց տվեց զորքին և, որսի պարագաներն ու բարակները ցրելով, հայտարարեց, թե ապաշխարում է. բայց այդ քայլը բավական չեղավ գահը փրկելու համար, և մի քանի ամիս անց նրան գահազրկեցին։", "3f079bcd"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["Մունկաչի (Մուկաչևո) բերդի հանձնումը Ավստրիային եռամյա պաշարումից հետո", "ca2efc3d"], "d": ["1685 թ. վերջին կայսերական ուժերի կողմից պաշարված Մունկաչի բերդը Թյոքյոլի Իմրեի կնոջ՝ Իլոնա Զրինիի ղեկավարությամբ երեք տարի դիմադրեց. ըստ բազմաթիվ հրատարակված տեղեկատու աշխատությունների՝ բերդը 1688 թ. հունվարի 17-ին հանձնվեց գեներալ Անտոնիո Կարաֆային։ Սա օսմանա-հաբսբուրգյան ճակատում Հունգարիայում օսմանամետ դիմադրության վերջին խոշոր բերդերից մեկի անկումն էր։", "d72ac109"]},
"OLAYLAR_EK17:1711-07-21:0":{"b": ["Բալթաջի Մեհմեդ փաշայի և Եկատերինա թագուհու ավանդությունը", "c1b739f1"], "d": ["Դարեր շարունակ կրկնվել է ժողովրդական այն պատումը, որը Պրուտում պաշարված ռուսական բանակի փրկությունը կապում է Եկատերինա I-ի՝ Բալթաջի Մեհմեդ փաշային ուղարկած նվերների/կաշառքի հետ։", "f28badd1"]},
"OLAYLAR_EK17:1711-07-21:1":{"b": ["Վեճը Պրուտում «բաց թողնված հնարավորության» մասին. երկու տեսակետ", "61ee699c"], "d": ["Այն, որ օսմանյան բանակը, ռուսական բանակը լիովին շրջապատած լինելով, բավարարվեց խաղաղությամբ, պայմանագրից անմիջապես հետո դարձավ պատմաբանների վեճի առարկա. TDV-ի իսկ ձևակերպմամբ՝ «հասկացվել է, որ մեծ հնարավորություն է բաց թողնվել, և այս թեզը հակառակ կարծիքի տեր անձինք ինտենսիվ մշակել են»։ Ըստ քննադատողների՝ ցարը կարող էր գերվել, ռուսական բանակի զենքերը՝ հանձնվել. իսկ պաշտպանողների կարծիքով՝ Հյուսիսային Եվրոպայում Շվեդիայի հզորացումը կանխելու համար Ռուսաստանը սահմանափակ ձևով թուլացնելը ավելի «խելացի քաղաքականություն» էր։ TDV-ն փոխանցում է երկու տեսակետն էլ՝ կողմ չբռնելով։", "d9f3213c"]},
"OLAYLAR_EK17:1725-01-01:0":{"b": ["Հիմնվեց երեսուներկու հոգանոց գիտական/թարգմանչական հանձնախումբ", "0e3a713c"], "d": ["Դամադ Իբրահիմ փաշայի մեծ վեզիրության օրոք Ստամբուլում հիմնվեց երեսուներկու հոգանոց գիտնական-գրագիրների հանձնախումբ, որը, TDV-ի ձևակերպմամբ, «կարող է համարվել ժամանակի ակադեմիան»։ Հանձնախումբը արաբերենից, պարսկերենից, հունարենից և լատիներենից թուրքերեն թարգմանեց պատմության, փիլիսոփայության և աշխարհագրության երկեր. դրանց թվում էին Յանյայից Էսադ էֆենդիի՝ քսանհինգ հոգանոց խմբով Արիստոտելի «Ֆիզիկա»-ն թարգմանելը և բանաստեղծ Նեդիմի՝ պատմական թարգմանության հանձնախմբի նախագահությունը։ Օրը TDV-ում նշված չէ, հայտարարված է տարին։", "69ac19ac"]},
"OLAYLAR_EK17:1730-11-25:0":{"b": ["Մահմուդ I-ը Փաթրոնա Հալիլին պալատ հրավիրելով ծուղակը գցեց", "6147059f"], "d": ["Գահ բարձրանալուց յոթ շաբաթ անց Մահմուդ I-ը իր վստահելի մարդկանց՝ պալատում Հաջի Բեշիր աղայի, դրսում Ղրիմի խան Կապլան Գիրեյ I-ի միջոցով զինվորական առաջնորդներին իր կողմը քաշեց և կոտրեց Փաթրոնա Հալիլի ազդեցությունը։ 1730 թ. նոյեմբերի 25-ին Թոփքափը պալատի Թլփատության սենյակում տեղի ունեցող ժողովի կանչված Փաթրոնա Հալիլին, Մուսլու Բեշեին և Քել Մեհմեդ աղային ներս ընդունեցին. մեծ վեզիր Սիլահդար Մեհմեդ փաշայի նշանով նախօրոք թաքցված երեսուներկու զինված մարդ դուրս եկավ և սպանեց երեքին էլ։ Այսպիսով Մահմուդ I-ը ապստամբության վերահսկողությունը լիովին վերցրեց իր ձեռքը։", "e3d9bb3d"]},
"OLAYLAR_EK17:1731-01-01:0":{"b": ["Հումբարաջի Ահմեդ փաշան (Բոնվալ) նշանակվեց Հումբարաջիների օջախի ղեկավար", "27b0b1d7"], "d": ["Իսկական անունով Կլոդ-Ալեքսանդր կոմս դը Բոնվալ ֆրանսիացի սպան, նախ ծառայելով ֆրանսիական և ավստրիական բանակներում, Սարաևոյում ընդունեց իսլամը, վերցրեց Ահմեդ անունը և 1729 թ. ապաստանեց Օսմանյան պետությունում։ Մահմուդ I-ի օրոք 1731 թ. Հումբարաջիների օջախի ղեկավար նշանակված Ահմեդ փաշան Ուսկյուդարի Այազմայում հիմնել տված զորանոցում վարժեցրեց Բոսնիայից բերված մոտ 300 զինվորի. նրանց թիվը կարճ ժամանակում անցավ 600-ը, և նա ինքը նաև մաթեմատիկայի դասեր էր տալիս։ Ֆրանսիայի օգտին Ռակոցիի հետ Հունգարիայում ձեռնարկած ապստամբության փորձը խարխլեց նրա ազդեցությունը, և 1738 թ. նա աքսորվեց Կաստամոնու։ 1747 թ. մայիսի 23-ին մահացավ Ստամբուլում. գերեզմանը Ղալաթա Մևլևիների վանքի գերեզմանոցում է։", "5bfbc961"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["Սմեդերևոյի վերագրավումը Հաբսբուրգների (Հունգարիայի թագավորության թագի) ձեռքից. 1737-39 թթ. պատերազմը", "63dcf604"], "d": ["TDV-ի «Սմեդերևո» հոդվածի համաձայն՝ 1717 թ. Պոժարևացով Ավստրիային թողնված բերդը հետ վերցվեց 1737 թ. սկսված օսմանա-ավստրիական պատերազմի Դանուբ-Սավա ճակատում օսմանյան առաջխաղացմամբ. Հաբսբուրգյան (Հունգարիայի թագավորության թագի) ուժերը շրջանում կարողացան դիմանալ մինչև 1738 թ. օգոստոս, այս ամսաթվից հետո Սմեդերևոն կրկին անցավ օսմանյան կառավարման։ Մեկ տարի անց ստորագրված Բելգրադի պայմանագիրը (1739-09-18) ամրագրելու էր այս ձեռքբերումը՝ Բելգրադի և հյուսիսային Սերբիայի հետ միասին։", "9ca857ec"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["Մորավայի հովտի վերադարձը օսմանյան կառավարման. Յագոդինա, Կրագուևաց և Չաչակ", "b219d3c9"], "d": ["1738 թ. օգոստոսին Սմեդերևոն հետ վերցնելով՝ Սմեդերևոյի և օսմանյան հիմնական մարմնի միջև մնացած Մորավայի հովիտն էլ վերադարձավ օսմանյան կառավարման. Յագոդինան, Կրագուևացը և Չաչակը այս ամսաթվից համարվում են օսմանյան։ Աղբյուրները այս երեք վայրերի վերադարձը առանձին ամսաթվով չեն հիշատակում. քարտեզը գործում է Սմեդերևոյի օրով։ Բելգրադի պայմանագիրը (1739-09-18) ամրագրեց այս վիճակը։", "4b38fa55"]},
"OLAYLAR_EK17:1789-04-07:0":{"b": ["Աբդուլհամիդ I-ը Օչակովի անկման լուրը կարդալիս կաթված ստացավ և մահացավ", "6ac60365"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի abdulhamid-i հոդվածի՝ ռուս-ավստրիական պատերազմի ծանր ընթացքից առողջությունը լիովին խաթարված Աբդուլհամիդ I-ը, Օչակովի բերդի՝ ռուսների կողմից գրավման մասին մեծ վեզիրի զեկուցագիրը կարդալիս, հանկարծակի կաթվածից մահացավ (հիջ. 1203 թ. Ռաջաբ ամսի 11 / 1789 թ. ապրիլի 7)։ Նրա դիակը թաղվեց Ստամբուլի Բահչեքափըում իր իսկ կառուցել տված դամբարանում։ Նույն օրը գահ բարձրացավ նրա եղբորորդի Սելիմ III-ը։", "e0b9fc27"]},
"OLAYLAR_EK17:1799-01-03:0":{"b": ["Օսմանա-ռուսական պաշտպանական դաշինք. համատեղ պաշտպանություն Ֆրանսիայի դեմ", "c87079d1"], "d": ["Նապոլեոնի կողմից Եգիպտոսի գրավումից հետո Սելիմ III-ը և ռուս ցար Պավել I-ը կնքեցին տասնչորս հոդվածից կազմված, ութ տարի ժամկետով պաշտպանական դաշինք։ Կողմերը պարտավորվեցին ունենալ ընդհանուր բարեկամ և թշնամի, միմյանց օգնել և առանձին խաղաղություն չկնքել։", "41183e81"]},
"OLAYLAR_EK17:1799-01-21:0":{"b": ["Օսմանյան պետության և Երկու Սիցիլիաների (Նեապոլի) պաշտպանական դաշինքը. ընդհանուր գործ Ֆրանսիայի դեմ", "1d2be816"], "d": ["Ֆրանսիայի՝ Իտալիան, Մալթան և Եգիպտոսը գրավելու պայմաններում Օսմանյան պետությունը և Երկու Սիցիլիաների թագավորությունը կնքեցին ինը հոդվածից կազմված պաշտպանական դաշինք։ Կողմերը պարտավորվեցին համատեղ պատերազմել, առանձին խաղաղություն չկնքել և միմյանց ցամաքային ու ծովային օգնություն ցույց տալ։", "5a755b31"]},
"OLAYLAR_EK17:1800-04-02:0":{"b": ["Հիմնվեց Յոթ կղզիների հանրապետությունը. Հոնիական կղզիները ռուս-օսմանյան հովանու ներքո", "08839694"], "d": ["1799 թ. ռուս-օսմանյան միացյալ նավատորմը ֆրանսիացիներին դուրս էր մղել Հոնիական կղզիներից (Կորֆուի բերդն ընկավ 1799 թ. մարտի 5-ին). 1800 թ. մարտի 21-ի տասներկու հոդվածից կազմված պայմանագրով կղզիները հիմնվեցին որպես ներքին գործերում ինքնավար, արտաքին գործերում Օսմանյան պետությանը կապված «Cezâyir-i Seb'a-i Müctemia Cumhuru» (Յոթ կղզիների հանրապետություն)։ 1799-03-05-ից մինչև այս օրը համատեղ օկուպացիայի շրջանն է։", "a9d3379e"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["Թիլզիտ. Յոթ կղզիների հանրապետության նկատմամբ ռուսական իրավունքները փոխանցվեցին Ֆրանսիային", "98a78beb"], "d": ["Թիլզիտում Ռուսաստանի և Ֆրանսիայի միջև ձեռք բերված համաձայնությամբ Ռուսաստանը Յոթ կղզիների նկատմամբ իր իրավունքները թողեց Ֆրանսիային. 1807 թ. ամռանը ֆրանսիական զորքերը հաստատվեցին կղզիներում, և Յոթ կղզիների հանրապետությունը վերացավ։", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["Լեֆկադայի և Հոնիական կղզիների անցումը անգլիական հովանու ներքո. նապոլեոնյան դարաշրջանից հետո ստեղծված կարգը", "0af821dc"], "d": ["1797 թ. Ֆրանսիային անցած Լեֆկադան և Հոնիական մյուս կղզիները, Նապոլեոնի վերջնական պարտությունից հետո, 1815 թ. նոյեմբերի 5-ին Փարիզում Անգլիայի, Ռուսաստանի, Ավստրիայի և Պրուսիայի միջև ստորագրված հատուկ պայմանագրով «Յոթ կղզիների միացյալ նահանգներ» անունով թողնվեցին անգլիական հովանու ներքո. սա առանձին փաստաթուղթ է 1815 թ. նոյեմբերի 20-ի Փարիզի ընդհանուր պայմանագրից։ Հովանավորությունը տևելու էր մինչև 1864 թ., ապա կղզիները հանձնվելու էին Հունաստանին։", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["Պրիզրենի գրավումը. օսմանյան սանջակի կենտրոն Կոսովոյում", "f84c220f"], "d": ["Հիջ. 859 թ. Ռաջաբ ամսի 4-ին (1455 թ. հունիսի 20) Ֆաթիհ սուլթան Մեհմեդի հրամանատարությամբ օսմանյան բանակը սերբ դեսպոտ Ջուրաջ Բրանկովիչի (օսմանյան աղբյուրներում՝ Վըլքօղլու) հետ կռվից հետո գրավեց Պրիզրենը։ Քաղաքը 13-րդ դարի կեսին Բյուզանդիայից անցել էր Սերբական թագավորությանը և թագավոր Միլուտինի, ցար Դուշանի ու թագավոր Ուրոշի օրոք եղել էր արքայական նստավայր. Դուշանի մահից հետո նրա նշանակությունը նվազել էր։ Գրավումից հետո այն դարձվեց սանջակի կենտրոն և մինչև 1912 թ.՝ չորսուկես դար, պահպանեց այդ կարգավիճակը։ Պրիզրենը, մինչև Հարավսլավիայի մասնատումը, Բալկաններում միակ քաղաքն էր, ուր միաժամանակ խոսում էին երեք լեզվով՝ ալբաներեն, թուրքերեն և սերբերեն։", "82ab4141"]},
"OLAYLAR_EK19:1789-07-14:0":{"b": ["Բաստիլի անկումը. Ֆրանսիական հեղափոխության սկիզբը", "96e931f1"], "d": ["Թագավոր Լյուդովիկոս XVI-ի՝ ֆինանսների նախարար Նեկկերին պաշտոնանկ անելու (1789 թ. հուլիսի 11) առաջացրած զայրույթի և տնտեսական ճգնաժամի պայմաններում Փարիզի բնակչությունը, զենք և վառոդ պահանջելով, շարժվեց Բաստիլի բերդի վրա։ Կեսօրից հետո սկսված բախման ժամանակ ավելի քան երեք հազար ապստամբների դեմ ընդամենը մոտ հարյուր պահակ ունեցող բերդը ժամը 17:00-ի սահմաններում հանձնվեց. սպանվեցին մի քանի պաշտոնյաներ, այդ թվում բերդի հրամանատար Բեռնար-Ռենե դը Լոնեն, ազատ արձակվեց յոթ կալանավոր։ Գրեթե դատարկ և արդեն քանդվելու նախատեսված բերդը թագավորական բռնակալության խորհրդանիշ էր. նրա անկման մասին Լյուդովիկոս XVI-ին զեկուցեցին. «Ո՛չ, տե՛ր, սա ապստամբություն չէ, այլ հեղափոխություն»։ Հուլիսի 14-ն այսօր Ֆրանսիայի ազգային տոնն է, և իրադարձությունը համարվում է կարճ ժամանակում ողջ երկրում տարածված ժողովրդական շարժման և Ֆրանսիական հեղափոխության (1789-1799) խորհրդանշական սկիզբը. հեղափոխությունը հաջորդ տասնամյակում, տապալելով բացարձակ միապետությունը, հիմնովին փոխելու էր Եվրոպայի քաղաքական քարտեզը և Օսմանյան պետությունն էլ ներառող միջազգային հավասարակշռությունները։", "ecc8db63"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["Մամլուքյան բանակը մտավ Մալաթիա. քաղաքը իլխանական կառավարումից անցավ մամլուքյան կառավարման", "2540363d"], "d": ["Մամլուքները Դամասկոսի նաիբ Սեյֆեդդին Թենգիզի հրամանատարությամբ բանակ ուղարկեցին Մալաթիայի վրա. բանակը հիջ. 715 թ. Մուհառամ ամսի 22-ին (1315 թ. ապրիլի 28) մտավ քաղաք։ Մալաթիան մինչ այդ իլխանական տիրապետության տակ էր և Եփրատից արևմուտք իլխանական ու մամլուքյան ազդեցության գոտիների հպման գծի առանցքային կետն էր։ Քաղաքի ձեռքից ձեռք անցնելը ցույց է տալիս երկու պետությունների երկարատև մրցակցության մեջ մամլուքների առաջխաղացումը դեպի Վերին Եփրատ։ Այս ամսաթվից հետո Մալաթիան որոշ ժամանակ մտնելու էր Էրեթնաօղուլների կառավարման ներքո, իսկ 1338 թվականից կրկին վերադառնալու էր մամլուքյան տիրապետության։", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["Էշրեֆօղուլների բեյության վերջը. Բեյշեհիրն ու Սեյդիշեհիրը անցան Համիդօղուլներին", "e4e70846"], "d": ["Իլխանության Անատոլիայի ընդհանուր կուսակալ էմիր Չոբանի որդի Դեմիրթաշը գործի անցավ անկախություն հռչակած թուրքմենական բեյությունների դեմ և, մտնելով Բեյշեհիր, սպանել տվեց Էշրեֆօղլու Սուլեյման շահին, որը ժամանակին իրենից գանգատվել էր (1326 թ. հոկտեմբերի 9)։ Այսպիսով ավարտվեց 13-րդ դարի վերջին Բեյշեհիր-Սեյդիշեհիրի շրջանում հիմնված Էշրեֆօղուլների բեյությունը։ TDV-ի «Համիդօղուլներ» հոդվածը շարունակությունն է տալիս. Դեմիրթաշի վերացրած Էշրեֆօղուլներին պատկանած Բեյշեհիրը, Սեյդիշեհիրը, Աքշեհիրը և Դողանհիսարը միացան Համիդի բեյության սահմաններին։ Նույն տարում Համիդօղլու Դյունդար բեյն էլ հանձնվեց Դեմիրթաշին և սպանվեց։ Այս հողերը 1381 թ. 80.000 ոսկով վաճառվելու էին Մուրադ I-ին և անցնելու էին օսմանյան կառավարման։", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["Մալաթիան կրկին անցավ մամլուքյան տիրապետության տակ. Էրեթնաօղուլների կառավարման վերջը", "08b80aa2"], "d": ["1315 թ. մամլուքյան կառավարման անցած Մալաթիան Իլխանության քայքայման տարիներին որոշ ժամանակ անցել էր Էրեթնաօղուլների ձեռքը։ TDV-ի «Մալաթիա» հոդվածը վերադարձը մեկ նախադասությամբ է տալիս. 1338 թվականից քաղաքում կրկին իշխեցին մամլուքները։ Սա Անատոլիայի հարավ-արևելքում Իլխանությունից հետո առաջացած դատարկությունը մամլուքների և Էրեթնայի միջև բաժանվելու տարիների մի կտրվածք է։", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["Իզմիրի նավահանգստի կորուստը խաչակրաց նավատորմին. Այդընօղուլների ծովային ուժը կոտրվեց", "775c65fe"], "d": ["Հռոմի պապ Կղեմես VI-ի խրախուսմամբ Վենետիկի, Ջենովայի, Կիպրոսի թագավորության, Հռոդոսի ասպետների և Նաքսոսի դուքսի նավերից կազմված խաչակրաց նավատորմը Իզմիրի նավահանգիստը խլեց Այդընօղուլների ձեռքից (1344 թ. հոկտեմբերի 28)։ Նավահանգիստը Ումուր բեյի հայր Մեհմեդ բեյը 1328-1329 թվականներին վերցրել էր ջենովացի Մարտինո Ձակկարիայից, և այն Էգեյան ծովում Այդընօղուլների ծովային ուժի հենակետն էր։ 1334 թ. սեպտեմբերին նույն նպատակով եկած խաչակրաց նավատորմը ստիպված էր եղել նահանջել. այս երկրորդ արշավանքը հաջողվեց։ Ումուր բեյը շարունակեց դիմադրությունը և, միավորվելով թուրքական մյուս բեյությունների հետ, 1345 թ. հունվարի 17-ին հաղթեց խաչակրաց նավատորմին, բայց նավահանգիստը հետ վերցնել չհաջողվեց։", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["Կարամանօղլու Ալաեդդին բեյը Կոնիան, Ակսարայը և Նիղդեն միացրեց Կարամանի հողերին", "2b8b0f70"], "d": ["Ցանկանալով օգտվել Մամլուքների սուլթանության կողմից Հայկական թագավորությանը վերջ դնելով ողջ Չուքուրովան իր հողերին միացնելուց և Կենտրոնական Անատոլիայի Էրեթնայի պետությունում ծագած խառնակություններից՝ Կարամանօղլու Ալաեդդին բեյը Կարամանյան հողերին միացրեց նախ Կոնիան (1366-1367), ապա Նիղդեի Կարահիսարը (Եշիլհիսար), Ակսարայը, Աքշեհիրը, Իլգընը, Իշաքլըն և Կեսարիան։ Կոնիան, որպես սելջուկյան մայրաքաղաք իր ունեցած կշռի պատճառով, Կարամանօղուլների համար ոչ միայն քաղաք էր, այլև օրինականության հավակնություն։", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["Ուզուն Հասանը վերջ դրեց Կարա Կոյունլուների պետությանը. Վանա լճի ավազանն անցավ Ակ Կոյունլուներին", "d8d6c2e8"], "d": ["Ակ Կոյունլու տիրակալ Ուզուն Հասանը, անակնկալի բերելով 1467 թ. իր վրա եկած անողոք թշնամուն՝ Կարա Կոյունլու տիրակալ Ջահան Շահին, վերջ դրեց Կարա Կոյունլուների պետությանը։ 1438 թվականից իշխող Ջահան Շահի վերացումով Վանա լճի ավազանը՝ Վանը, Բիթլիսը, Բարգիրին (Մուրադիյե), Խոշապը և Կոտուրը, Կարա Կոյունլուներից անցավ Ակ Կոյունլուների կառավարման։ Այս հաղթանակը Ակ Կոյունլուների պետությունը դարձրեց Արևելյան Անատոլիայի և Իրանի միակ մեծ ուժը և Ուզուն Հասանին դրեց այն ճանապարհին, որը մեկ սերունդ անց նրան կանգնեցնելու էր օսմանցիների դեմ հանդիման։", "4d0ea428"]},
"OLAYLAR_EK20:1489-03-04:0":{"b": ["Ջեմ սուլթանին բերեցին Հռոմ. պատանդի դիվանագիտություն և տարեկան 40.000 դուկատ", "1c6715a8"], "d": ["Պապ Իննոկենտիոս VIII-ը, համաձայնության գալով Հռոդոսի ասպետների առաջնորդ Պիեռ դ'Օբյուսոնի հետ, Ջեմ սուլթանին բերել տվեց Հռոմ (1489 թ. մարտի 4)։ Ջեմը 1482 թ. հուլիսի 29-ին ապաստանել էր Հռոդոսում, այնտեղից անցել Սավոյայի հողերը և վերջում՝ պապական հսկողության։ Բայազիդ II-ը, որպես հակառակ ծառայություն՝ եղբորը հսկողության տակ պահելու դիմաց, ընդունել էր ասպետներին տարեկան 40.000 դուկատ վճարել և նրանց օսմանյան տարածքներում ազատ առևտրի իրավունք տալ։ Այս վճարը խարաջ չէր, այլ գահի օրինական հավակնորդին Եվրոպայում անշարժ պահելու գինը. եթե Ջեմը ազատ մնար, կարող էր Անատոլիայում բանակ հավաքել և, բացի այդ, դառնալ խաչակրաց արշավանքի օրինականության աղբյուր։ Այսպիսով հարստության ներքին մի հարց երեսուն տարի դարձավ օսմանյան արտաքին քաղաքականության հիմնական սահմանափակումը. սա է Բայազիդի՝ Արևմուտքում զգուշավոր վարվելու պատճառը։ 1495 թ. Ջեմի մահով այս սահմանափակումը վերացավ։", "60ca67f8"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["Վրաց թագավորությունը բաժանվեց երեքի՝ Քարթլի, Կախեթի և Իմերեթի՝ Քութայիսի կենտրոնով", "f9c5f798"], "d": ["Բագրատունյաց հարստության կառավարած միացյալ Վրաց թագավորությունը երկարատև ներքին պայքարից հետո պաշտոնապես բաժանվեց երեք թագավորության. արևելքում Թիֆլիս կենտրոնով Քարթլի, հյուսիս-արևելքում Կախեթի և արևմուտքում Իմերեթի՝ Քութայիսի կենտրոնով։ TDV-ի «Վրաստան» հոդվածը հաստատում է բաժանումը. «Վրաստանը բաժանվեց երեք թագավորության (Քարթլիա, Կախեթիա, Իմերեթիա) և հինգ իշխանության»։ Բաժանումը վճռորոշ եղավ հաջորդ դարի օսմանա-սեֆյան մրցակցության մեջ. 1555 թ. Ամասիայի պայմանագրով Իմերեթիան, Դադիանը, Գուրիան և Դավելին թողնվեցին Օսմանյան պետությանը, իսկ Քարթլին, Կախեթիան և Մոսուքը՝ Սեֆյաններին։ Այսինքն՝ ատլասի՝ արևմտյան և արևելյան Վրաստանը տարբեր տերերի կապելը ծագում է այս բաժանումից։ Յավուզ Սուլթան Սելիմը դեռ Տրապիզոնի կուսակալ եղած ժամանակ՝ 1508 թ., հնազանդության և խարաջի էր ենթարկել Իմերեթիի (Աչըքբաշ) թագավորությունը։", "6b0aaa55"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["Իսպանացիները գրավեցին Տրիպոլին (Լիբիա). Հաֆսյան տիրապետության վերջը", "de319d23"], "d": ["Ամմարյաններից հետո Տրիպոլիում Հաֆսյանների տիրապետությունը շարունակվեց մինչև 1510 թ.։ Այդ տարում քաղաքը գրավեցին Օլիվետոյի կոմս Դոն Պեդրո Նավառոյի հրամանատարությամբ իսպանացիները. կոտորածից փրկված մուսուլմանները լքեցին քաղաքը։ Գրավումը Հյուսիսային Աֆրիկայի ափին Մելիլիայից Տրիպոլի ձգվող իսպանական բերդերի շղթայի արևելյան ծայրն էր։ Տրիպոլիի բնակչությունը հիջ. 925 (1519) թ. պատվիրակություն ուղարկելով Ստամբուլ՝ իսպանական ներխուժման դեմ օգնություն խնդրեց Օսմանյան պետությունից. 1551 թ. քաղաքը, վերցվելով Թուրգութ ռեիսի և Սինան փաշայի կողմից, անցնելու էր օսմանյան կառավարման։", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["Մալթան և Տրիպոլին տրվեցին Սուրբ Հովհաննեսի ասպետներին. Հռոդոսից վտարված օրդենի նոր հենակետը", "2595729e"], "d": ["Սուլթան Սուլեյման Կանունիի հիջ. 928 (1522) թ. Հռոդոսից դուրս մղած Սուրբ Հովհաննեսի (հոսպիտալյան) ասպետներին ութ տարի անհայրենիք մնալուց հետո Իսպանիա-Գերմանիայի թագավոր Կարլոս V-ը բնակեցրեց Մալթայում. նույն նվիրատվությամբ օրդենին տրվեց նաև Տրիպոլիի պաշտպանությունը։ Մալթան իր իդեալական նավահանգիստներով ծովերում ակտիվ ասպետների համար դարձավ հարմար հենակետ. նախ հաստատվեցին Բիրգուում, ամրացրին Սեն Անջելո բերդը և Սենգլեայի ծայրին կառուցեցին Սեն Միշել բերդը։ Այս բնակեցումը Միջերկրական ծովի կենտրոնում ստեղծեց օսմանյան ծովային ուղիները կտրող մշտական թշնամական հենակետ. Թուրգութ ռեիսի՝ հիջ. 947 (1540) թ. Գոցոյի ասպատակությամբ սկսված բախումները տևելու էին մինչև 1565 թ. Մալթայի պաշարումը։", "3992bdbc"]},
"OLAYLAR_EK20:1648-10-24:0":{"b": ["Վեստֆալյան խաղաղությունը. Երեսնամյա պատերազմներն ավարտվեցին, Սրբազան Հռոմի միասնությունը քայքայվեց", "d7719f05"], "d": ["Երեսնամյա պատերազմներին (1618-1648) վերջ դրած պայմանագրերը նույն օրը ստորագրվեցին Մյունստերում և Օսնաբրյուկում (1648 թ. հոկտեմբերի 24)։ Սրբազան Հռոմեական կայսրության մոտ երեք հարյուր իշխանություններ ստացան իրենց սեփական արտաքին քաղաքականությունը վարելու իրավունք. կայսրությունը դադարեց պետություն լինելուց և վերածվեց ծածկոցի։ Շվեդիան ստացավ Արևմտյան Պոմերանիան և Շտետինը, իսկ Բրանդենբուրգը՝ Արևելյան Պոմերանիան և Մագդեբուրգի արքեպիսկոպոսության ակնկալիքը. Հոհենցոլեռնների՝ 1701 թ. թագավորության ուղղվելիք հողային կուտակումը այստեղ է սկսվում։ Հոլանդիայի և Շվեյցարիայի անկախությունը պաշտոնապես ճանաչվեց։ Օսմանյան պետության համար դրա նշանակությունը անուղղակի է, բայց մեծ. Հաբսբուրգների արևմտյան ճակատից քաշվելով Կենտրոնական Եվրոպայում ծնվեց ուժ, որ կարող էր կրկին դեպի արևելք շրջվել։", "21478661"]},
"OLAYLAR_EK20:1701-01-18:0":{"b": ["Հռչակվեց Պրուսիայի թագավորությունը. Ֆրիդրիխ I-ը թագադրվեց Քյոնիգսբերգում", "337a9f74"], "d": ["Բրանդենբուրգի կուրֆյուրստ Ֆրիդրիխ III-ը, կայսր Լեոպոլդ I-ի հավանությամբ թագադրվելով Քյոնիգսբերգում, ստացավ «թագավոր Պրուսիայում» տիտղոսը (1701 թ. հունվարի 18)։ Տիտղոսը վերցվել էր Արևելյան Պրուսիայից, որովհետև այն Սրբազան Հռոմեական կայսրությունից դուրս էր, և կայսրին ենթակա կուրֆյուրստը կարող էր թագավոր լինել միայն կայսրության սահմաններից դուրս։ Հոհենցոլեռն հարստության ցրված հողերն այս ամսաթվից սկսեցին կոչվել մեկ պետության անունով։", "203ac1b3"]},
"OLAYLAR_EK20:1720-09-02:0":{"b": ["Սարդինիան Իսպանիայից անցավ Սավոյա հարստությանը. ծնվեց Սարդինիայի թագավորությունը", "adf778b7"], "d": ["Իսպանական ժառանգության պատերազմը փակող կարգավորումների վերջին օղակում Սարդինիա կղզին վերցվեց Իսպանիայից և տրվեց Սավոյա հարստությանը. Սավոյայի դուքսը փոխարենը թողեց Սիցիլիան և ստացավ Սարդինիայի թագավորի տիտղոսը։ Այսպիսով Կալյարին և Սասարին դուրս եկան երկդարյա իսպանական կառավարումից։ Ծնված Սարդինիայի թագավորությունը մեկուկես դար անց իտալական միասնությունը կերտելիք պետության միջուկն է. այսինքն՝ 1870 թ. Հռոմ մտած Իտալիայի թագավորության արմատը այստեղ է հասնում։", "a73abd0e"]},
"OLAYLAR_EK20:1768-05-15:0":{"b": ["Կորսիկան Ջենովան վաճառեց Ֆրանսիային. Վերսալի պայմանագիրը", "770343df"], "d": ["Ջենովայի Հանրապետությունը Ֆրանսիային հանձնեց Կորսիկան, որը դարեր շարունակ իր ձեռքում էր, բայց ապստամբությունների պատճառով փաստացի չէր կարողանում վերահսկել։ TDV-ի «Կորսիկա» հոդվածը իրադարձությունը մեկ նախադասությամբ է տալիս. Ջենովան այս կղզին, որին այնքան էլ տեր չէր կարողանում կանգնել, 1768 թ. վաճառեց Ֆրանսիային։ Հանձնումը նշանավորում է Միջերկրական ծովում Ջենովայի վերջին խոշոր տարածքային ունեցվածքից նրա հեռանալը. կղզին 1796 թ. որոշ ժամանակ անցնելու էր անգլիական ձեռք, ապա կրկին վերադարձվելու էր Ֆրանսիային։ Կղզու՝ ֆրանսիական հող դառնալը մեկ տարի անց Այաչչոյում ծնվելիք Նապոլեոն Բոնապարտին դարձրեց ֆրանսիական հպատակ։ Այս տարի (1768) Կորսիկան, ներառյալ Բաստիան, Ջենովայից վաճառվեց Ֆրանսիային (TDV «Կորսիկա». օրը հաստատված չէ)։", "c6214397"]},
"OLAYLAR_EK20:1807-07-09:0":{"b": ["Թիլզիտի պայմանագիրը. Պրուսիան կորցրեց իր հողերի կեսը, հիմնվեց Վարշավայի դքսությունը", "d30bb2cc"], "d": ["Յենա-Աուերշտեդտի ջախջախումից հետո Պրուսիան ստիպված էր Թիլզիտում Նապոլեոնի հետ ծանր խաղաղություն ընդունել (1807 թ. հուլիսի 9)։ Նա զիջեց Էլբայից արևմուտք իր բոլոր հողերը և 1793 ու 1795 թվականների բաժանումներով ստացած լեհական տարածքները. վերջիններից հիմնվեց Վարշավայի դքսությունը, իսկ Բելոստոկի շրջակայքը տրվեց Ռուսաստանին։ Պրուսիան կորցրեց իր բնակչության և հողի մոտ կեսը, բանակը սահմանափակվեց 42.000-ով։ Ատլասում Պոզնանն ու Տորունը այս օրվանից անցնում են Վարշավայի դքսությանը, իսկ Բելոստոկը՝ Ռուսաստանին։ Այս պայմանագրով Լոձը և Չենստոխովան (1772-ից հետո Պրուսիային անցած լեհական նահանգներ) անցան Վարշավայի դքսությանը. Գդանսկը (Դանցիգ) դարձավ անկախ ազատ քաղաք։", "e484982c"]},
"OLAYLAR_EK20:1870-09-20:0":{"b": ["Իտալական զորքերը մտան Հռոմ. Պապական պետության վերջը և իտալական միասնության ամբողջացումը", "a3689f2e"], "d": ["Երբ ֆրանս-պրուսական պատերազմում Նապոլեոն III-ի տապալումը ետ քաշեց Հռոմը պաշտպանող ֆրանսիական կայազորը, իտալական զորքերը մտան քաղաք, և պապը քաշվեց Վատիկան։ Այսպիսով ավարտվեց ավելի քան հազար տարի գոյատևած Պապական պետությունը, իսկ Հռոմն էլ միության մեջ առած Իտալիայի թագավորությունը հանդես եկավ Եվրոպայի և աշխարհի բեմում որպես քաղաքական ուժ։ Սա ատլասի վերջին կես դարի համար անմիջական հետևանքներ ունեցող իրադարձություն է. միացյալ Իտալիան է այն պետությունը, որ 1911 թ. Օսմանյան պետությունից վերցնելու է Տրիպոլին և Տասներկու կղզիները։", "6d9c3e10"]},
"OLAYLAR_EK20:1887-01-07:0":{"b": ["Չելենկոյի ճակատամարտը. Հարարի ամիրայության վերջը և հաբեշական գրավումը", "5671a0d9"], "d": ["Երբ Դավուդը դարձավ Աուսսայի իմամ, օրոմոների կառավարած հողերի կենտրոնում մնացած Հարարը կրկին դարձել էր անկախ ամիրայություն և այդ վիճակը պահել մինչև 1887 թ. հաբեշական գրավումը։ Ջիհադ հայտարարած էմիր Աբդալլահը 5000 հոգով 1887 թ. հունվարի 7-ին դիմավորեց հաբեշներին Շելենեկոյում (Չելենկո). երբ հասկացավ, որ պարտվելու է, փախավ Հարարի հարավում գտնվող Օգադենի շրջան։ Ճակատամարտը ցույց տվեց հրազենով սպառազինված հաբեշական բանակի և ամիրայության ուժերի անհավասարակշռությունը և վերացրեց Կարմիր ծովի հետևի վերջին անկախ մուսուլմանական ամիրայություններից մեկը։ Այսպիսով Հարարը, Ջիջիգան և Դագաբուրը միացան Եթովպիային։", "73175130"]},
"OLAYLAR_EK21:1509-01-01:0":{"b": ["Շահ Իսմայիլը վերցրեց Դերբենդը. սեֆյան տիրապետությունը հասավ Կովկասի դարպասին", "305542c4"], "d": ["1500 թ. Շիրվանշահ Ֆարրուխ Յասարի պարտվելով և սպանվելով Բաքուն և Շամախին անցել էին սեֆյան ձեռքը, իսկ Դերբենդը որոշ ժամանակ դեռ առանձին էր մնացել։ 1509 թ. Շահ Իսմայիլը գրավեց քաղաքը և այնտեղ բնակեցրեց ռումլու ցեղերից մեկին. այսպիսով սեֆյան տիրապետությունը հասավ Կովկասի հյուսիսային դարպասին՝ Կասպից ծովի և լեռների միջև ընկած այս նեղ անցքին։ 1538 թ. Շիրվանի՝ սեֆյան ուղղակի կառավարման անցնելով կապը կայունացավ։ Դերբենդը 1578 թ. արշավանքում անցնելու էր օսմանյան ձեռքը և մինչև 1607 թ. լինելու էր յոթ սանջակ ունեցող բեյլերբեյության կենտրոն։ TDV-ի գրառումը այսպիսին է. «Սեֆյան պետության հիմնումն ու զարգացումը Դերբենդում նոր շրջանի սկիզբ դարձավ։ Շահ Իսմայիլը 1509 թ. գրավեց քաղաքը և այնտեղ բնակեցրեց ռումլու ցեղերից մեկին։ Երբ 1538 թ. Շիրվանն անմիջապես անցավ սեֆյան տիրապետության տակ...»։", "e301b4f1"]},
"OLAYLAR_EK21:1537-01-01:0":{"b": ["Կարսի վերջնական միացումը օսմանյան հողերին. արևելյան սահմանի մեխը", "6235c85a"], "d": ["Սեֆյանների կողմից Ակ Կոյունլուների պետության կործանումից հետո Կարսը որոշ ժամանակ մնացել էր ավշար թուրքմեններից Սևունդյուք խան Կուրչիբաշիի ձեռքին։ Կանունիի Իրաքեյնի արշավանքի ժամանակ (հիջ. 940/1534), Պասենի, Շուրագյալի և Օլթիի բերդերը վերցնելիս, մեծ հավանականությամբ Կարսի բերդն էլ կապվել է օսմանցիներին. սակայն քաղաքի վերջնական միացումը եղել է երեք տարի անց։ TDV-ի գրառումը այսպիսին է. «Կարսը օսմանյան ծառայության անցած Դուլկադիրցի Մեհմեդ խանի կողմից վերջնականապես օսմանյան հողերին ներառվեց հիջ. 944 (1537) թ.»։ Քանի որ երկարատև պայքարների պատճառով քաղաքն ու բերդը մեծ մասամբ ավերվել էին, ձեռնարկվեց արագ վերանորոգում. հիջ. 955 (1548) թ., երբ բերդը նորոգվում էր, սեֆյանները հարձակվեցին քաղաքի վրա և բերդը կրկին ավերեցին։ Դրանից հետո Կարսը երեք հարյուր քառասուն տարի մնալու էր օսմանյան հյուսիս-արևելյան սահմանի բանալին, իսկ 1877-78 թթ. պատերազմից հետո թողնվելու էր Ռուսաստանին։", "dff46f96"]},
"OLAYLAR_EK21:1811-04-01:0":{"b": ["Նիկոպոլի հետ վերցնելը. ավարտվեց վեցամսյա ռուսական օկուպացիան", "7fb299d7"], "d": ["1806-1812 թթ. ռուս-թուրքական պատերազմում Դանուբի հարավային ափ անցած ռուսական ուժերը 1810 թ. հոկտեմբերին գեներալ Կուտուզովի հրամանատարությամբ գրավել էին Նիկոպոլը։ Վեց ամիս անց, տեսնելով, որ Դանուբի գիծը չեն կարողանա պահել, դատարկեցին քաղաքը. նախքան հեռանալը բերդի մեծ մասը պայթեցրին։ TDV-ի գրառումը այսպիսին է. «1810 թ. հոկտեմբերին (1808-1812 թուրք-ռուսական պատերազմի շրջանում) Նիկոպոլը գրավեցին ռուս հռչակավոր գեներալ Միխայիլ Կուտուզովի ուժերը։ Ռուսները, նախքան քաղաքը լքելը, 1811 թ. ապրիլին պայթեցրին բերդի մեծ մասը և քաղաքին մեծ վնաս հասցրին»։ Ռուսական ուժերի հեռանալուց հետո օսմանցիները վերակառուցեցին բերդը. 1813-1814 թվագրված արձանագրությունը այս վերանորոգման վկայությունն է։", "7237449c"]},
"OLAYLAR_EK21:1811-05-01:0":{"b": ["Սիլիստրայի տարհանումը. Դանուբի միջին բերդը լքվեց՝ պարիսպները քանդելով", "561628bb"], "d": ["Դանուբի ամենաուժեղ օսմանյան բերդերից Սիլիստրան 1810 թ. ենթարկվել էր ռուսական հրետանու ռմբակոծության, և զինապահեստի պայթյունից բերդն ու արվարձանը ծանր վնասվել էին։ Ռուսները, քաղաքը գրավելուց հետո, նախընտրեցին ոչ թե պահել այն, այլ ոչնչացնել ամրությունները. գեներալ Կուտուզովը հրամայեց քանդել պարիսպները և 1811 թ. մայիսին ցարին զեկուցեց, որ Սիլիստրայի պարիսպները պայթեցվել են։ TDV-ի գրառումը. «1810 թ. քաղաքը ռմբակոծվեց ռուսների կողմից… Ռուսների՝ քաղաքը գրավելուց հետո և նախքան նահանջելը գեներալ Կուտուզովը հրամայեց քանդել Սիլիստրան։ 1811 թ. մայիսին ցարին հայտնեց, որ Սիլիստրայի պարիսպները պայթեցվել են»։ Նույն բերդը 1827-1828 թթ. պատերազմում ռուսները նորից վերցնելու էին, և այդ պաշարումը մանրամասնորեն նկարագրելու էր Հելմուտ ֆոն Մոլտկեն։", "d18dd90e"]},
"OLAYLAR_EK22:1794-01-01:0":{"b": ["Զենդ հարստության վերջը. Ղաջարների տիրապետությունը Իրանում", "5dda30a4"], "d": ["Զենդ հարստության վերջին տիրակալ Լութֆ Ալի խանի պարտությամբ ավարտվեց 1751 թ. հիմնված հարստությունը, և ողջ Իրանը անցավ Աղա Մուհամմեդ խանի ձեռքը։ Ղաջարների պետության պաշտոնական հիմնումը թվագրվում է երկու տարի ուշ՝ Աղա Մուհամմեդ խանի՝ Թեհրանում շահնշահի թագը կրելով (1796). սակայն իշխանության փոխանցումը կայացել է 1794 թ.։", "793d45c6"]},
"OLAYLAR_EK22:1923-07-24:0":{"b": ["Լոզան–Սևր տարբերությունները. պարտադրված խաղաղությունից դեպի հավասար խաղաղություն", "4b578583"], "d": ["Սևրը (1920 թ. օգոստոսի 10) Ստամբուլի կառավարությանը պարտադրված, երբեք ուժի մեջ չմտած փաստաթուղթ էր. Լոզանը (1923 թ. հուլիսի 24) այն խաղաղությունն է, որը Անկարան ստորագրեց որպես հավասար կողմ, և Թուրքիայի Ազգային մեծ ժողովը (TBMM) վավերացրեց 1923 թ. օգոստոսի 23-ին (Լոզան, հոդվ. 1, 143)։ Սահմանների հարցում Սևրը Թուրքիայի եվրոպական սահմանը քաշում է դեպի Չաթալջայի գիծ և Հունաստանին տալիս Արևելյան Թրակիան՝ ներառյալ Էդիրնեն, ինչպես նաև Իմբրոսն ու Թենեդոսը (Սևր, հոդվ. 27, 84). իսկ Իզմիրն ու շրջակայքը անվանապես մնում են թուրքական ինքնիշխանության տակ, բայց կառավարումը թողնվում է Հունաստանին, և հինգ տարի անց տեղական խորհրդարանը կարող է խնդրել միացում (հոդվ. 65-83)։ Լոզանը գծում է Մարիցա-Արդա գիծը, Էդիրնեն և Կարաաղաչը մնում են Թուրքիային, Իմբրոսն ու Թենեդոսը դառնում են թուրքական (Լոզան, հոդվ. 2, 12, 14. Կարաաղաչի արձանագրություն)։ Նեղուցների հարցում Սևրը ստեղծում է բոլոր ջրերը ընդգրկող միջազգային հանձնաժողով, ուր թուրք անդամն ունի միայն մեկ ձայն. ամրությունները քանդվում են, և շրջանը բացվում է Դաշնակիցների օգտագործման համար (Սևր, հոդվ. 36-61, 178-180)։ Լոզանը պահպանում է ազատ անցման սկզբունքը, բայց թողնում է թուրք նախագահով հանձնաժողով, ապառազմականացված գոտիներ և Ստամբուլում 12.000 հոգանոց կայազոր (Լոզան, հոդվ. 23. Նեղուցների կոնվենցիա)։ Հայաստանի ճանաչումը և ԱՄՆ նախագահի սահմանային արբիտրաժը, ինչպես նաև քրդական ինքնավարության ծրագիրը (Սևր, հոդվ. 62-64, 88-93) Լոզանում տեղ չունեն։ Արաբական հողերի, Եգիպտոսի, Սուդանի և Կիպրոսի հարցերում Սևրը դնում է հանձնման մանրամասն դրույթներ (Սևր, հոդվ. 94-97՝ մանդատներ, հոդվ. 98-100՝ Հիջազ, հոդվ. 101-122՝ Եգիպտոսից, Սուդանից, Կիպրոսից, Մարոկկոյից, Թունիսից և Լիբիայից հրաժարում. TDV-ի հոդվածների միջակայքերն էլ այդպիսին են). Լոզանը հրաժարումը ավելի կարճ է գրում, Տասներկու կղզիները մնում են Իտալիային, Կիպրոսը՝ Անգլիային, Մոսուլի սահմանը հետաձգվում է (Լոզան, հոդվ. 3, 15-21)։ Սևրը վերականգնում և ընդլայնում է կապիտուլյացիաները, Ֆինանսական հանձնաժողովի միջոցով վերահսկում թուրքական բյուջեն և փոխառությունները, զինված ուժը (ժանդարմերիա և համալրման տարրեր) չի կարող անցնել 50.000 հոգին, ռազմական և ծովային ավիացիան արգելված է (Սևր, հոդվ. 155, 164, 191-195, 231-264, 261-263)։ Լոզանը վերացնում է կապիտուլյացիաները, բաշխում պարտքերը և բանակի առանձին սահմանափակում չի դնում (Լոզան, հոդվ. 28, 46-63. հոդվ. 113-ը վերացնում է նաև օտար փոստային բաժանմունքները)։ Փոքրամասնությունների դրույթները Սևրում ավելի լայն են և բաց Դաշնակիցների միջամտության համար, իսկ Լոզանում՝ Ազգերի լիգայի երաշխիքով և փոխադարձ (Սևր, հոդվ. 140-151. Լոզան, հոդվ. 37-45)։\n\nԱռանցք առ առանցք համեմատություն.\n• Արևելյան Թրակիա, Էդիրնե, Չաթալջա — Սևր. սահմանը Չաթալջայի գիծն է. Արևելյան Թրակիան և Էդիրնեն՝ Հունաստանին (հոդվ. 27, 84-85) | Լոզան. սահմանը Մարիցայի և Արդայի երկայնքով. Էդիրնեն և Կարաաղաչը՝ Թուրքիայում (հոդվ. 2. Կարաաղաչի արձանագրություն)\n• Իզմիրի շրջան — Սևր. ինքնիշխանությունը թուրքական, կառավարումն ու բանակը՝ հունական, հինգ տարի անց միացման դիմում (հոդվ. 65-83) | Լոզան. Իզմիրի համար հատուկ կարգավիճակի հոդված չկա. Անատոլիան Թուրքիայի սահմանների ներսում է (հոդվ. 2-3՝ ընդհանուր սահման. Իզմիրի վերաբերյալ առանձին հոդվածային ապացույց չկա)\n• Նեղուցներ և Ստամբուլ — Սևր. Նեղուցների միջազգային հանձնաժողով, Թուրքիան՝ 1 ձայն. ամրությունների քանդում, շրջանը՝ Դաշնակիցների օգտագործման տակ. Ստամբուլը թուրքական ձեռքում, բայց կախված փոքրամասնությունների պայմանից (հոդվ. 36-61, 178-180) | Լոզան. ազատ անցման սկզբունք. թուրք նախագահով հանձնաժողով, ապառազմականացված գոտիներ, Ստամբուլում 12.000 հոգանոց կայազոր (հոդվ. 23. Նեղուցների կոնվենցիա)\n• Հայաստան և Քուրդիստան — Սևր. Հայաստանը ճանաչվում է, սահմանը որոշում է ԱՄՆ նախագահը. քրդական ինքնավարություն, մեկ տարի անց անկախության դիմում (հոդվ. 62-64, 88-93) | Լոզան. համապատասխան դրույթ չկա (հոդվ. 1-143 ամփոփումներում չի հիշատակվում)\n• Էգեյան կղզիներ, Տասներկու կղզիներ — Սևր. Իմբրոսը, Թենեդոսը և Էգեյան կղզիները՝ Հունաստանին. Տասներկու կղզիները և Մեիսը՝ Իտալիային (հոդվ. 84, 122) | Լոզան. Իմբրոսն ու Թենեդոսը՝ Թուրքիայում, արևելաէգեյան կղզիները՝ հունական, Տասներկու կղզիներն ու Մեիսը՝ Իտալիայում (հոդվ. 12-15)\n• Կիպրոս, Եգիպտոս, Սուդան, արաբական հողեր — Սևր. Սիրիայի/Միջագետքի և Պաղեստինի մանդատ, Հիջազը անկախ. ճանաչվում են Եգիպտոսի պրոտեկտորատը, Սուդանի, Կիպրոսի բռնակցումը (հոդվ. 94-98, 101-117) | Լոզան. Սիրիայի սահմանը՝ 1921 թ. ֆրանս-թուրքական համաձայնագրով, Իրաքի սահմանը՝ հետագայում. հրաժարում Եգիպտոսից, Սուդանից, Կիպրոսից (հոդվ. 3, 16-20)\n• Կապիտուլյացիաներ — Սևր. վերականգնվում և ընդլայնվում են. դատական բարեփոխումների ծրագիրը՝ Դաշնակիցների հանձնաժողովում (հոդվ. 136, 261-263, 308-309) | Լոզան. լիովին վերացվում են. վերանում են օտար փոստային բաժանմունքները և Բարձրագույն սանիտարական խորհուրդը (հոդվ. 28, 113-114)\n• Ֆինանսական վերահսկողություն և պարտքեր — Սևր. Դաշնակիցների Ֆինանսական հանձնաժողովը վերահսկում է բյուջեն և փոխառությունները, Օսմանյան պետական պարտքի վարչությունը (Düyun-ı Umumiye) ընդլայնվում է, ռեսուրսները՝ գրավ (հոդվ. 231-264) | Լոզան. Օսմանյան պետական պարտքը բաշխվում է պետությունների բաժնեմասերի միջև. պատերազմական վնասները փոխադարձաբար զիջվում են (հոդվ. 46-63, 58)\n• Ռազմական սահմանափակումներ — Սևր. բանակը 50.000 հոգի, արգելվում են օդուժը և տանկերը, Դաշնակիցների վերահսկիչ հանձնաժողովներ (հոդվ. 152-207) | Լոզան. ընդհանուր սահմանափակում չկա. միայն հունական կղզիներում և Նեղուցների ու Թրակիայի շրջաններում ապառազմականացում (հոդվ. 13. Նեղուցների և Թրակիայի կոնվենցիաներ)\n• Փոքրամասնություններ — Սևր. Դաշնակիցների երաշխիք և միջամտության իրավունք, «լքյալ գույքի» (Emval-i Metruke) չեղարկում, վերադարձ (հոդվ. 140-151, 86, 142-144) | Լոզան. ոչ մուսուլման փոքրամասնություններին՝ Ազգերի լիգայի երաշխավորած իրավունքներ, Հունաստանում մուսուլմանների փոխադարձ իրավունքներ. հույն-թուրք բնակչության փոխանակում (հոդվ. 37-45. Փոխանակման կոնվենցիա)\n• Իրավական կարգավիճակ — Սևր. ստորագրել է Ստամբուլի կառավարությունը, Անկարան մերժել է, ուժի մեջ չի մտել (TDV) | Լոզան. հավասար կողմ. TBMM-ի վավերացումը՝ 1923 թ. օգոստոսի 2, 213 կողմ, 14 դեմ (TDV. հոդվ. 1, 143)", "95c8b4ce"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Օսմանյան առաջին ակչեի հատումը", "38d2d638"], "d": ["Օրհան Ղազիի անունով հատված առաջին արծաթե ակչեն բեյլիքի անկախ գերիշխանության դրամական հռչակումն է. ակչեն հինգ դար մնաց որպես հիմնական դրամական միավոր։", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Հիմնվեց Ռումելիի բեյլերբեյությունը", "ffa16089"], "d": ["Եվրոպական ափի նվաճումները հավաքվեցին մեկ ռազմավարչական տանիքի տակ. բեյլերբեյությունների կարգը դարձավ կայսրության գավառական վարչական կազմակերպության ողնաշարը։", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Յըլդըրըմ Բայազիդ – Դեսպինա խաթուն ամուսնությունը", "4b10dc6c"], "d": ["Կոսովոյից հետո Սերբական դեսպոտության հետ հաստատված վասալությունը կնքվեց Լազարի դստեր Օլիվերայի՝ Բայազիդի հետ ամուսնությամբ. վաղ շրջանի ամուսնական դիվանագիտության բնորոշ օրինակ։", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Հիմնվեց Անատոլիայի բեյլերբեյությունը", "5ef8d3a7"], "d": ["Բռնակցված բեյլիքների հողերի կառավարման համար կազմակերպվեց Անատոլիայի բեյլերբեյությունը. ամբողջացավ Ռումելի-Անատոլիա երկթև վարչական կարգը։", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Ավարտվեց Բուրսայի Ուլու մզկիթը", "27bcc4a5"], "d": ["Նիկոպոլիսի ավարով կառուցված քսան գմբեթով մեծ մզկիթը վաղ օսմանյան ճարտարապետության մոնումենտալ օրինակն է և գեղագրության արվեստի բաց թանգարանը։", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Չանդարլը Հալիլ փաշայի պաշտոնազրկումը և մահապատիժը", "5e19438f"], "d": ["Նվաճումից հետո մահապատժի ենթարկվեց պաշարման նկատմամբ զսպվածություն ցուցաբերած հինավուրց Չանդարլը ընտանիքից սերող մեծ վեզիրը. առաջին անգամ մեծ վեզիրը սպանվում էր փադիշահի հրամանով, բացվում էր դևշիրմե ծագմամբ վեզիրների դարաշրջանը։", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Մոլդովայի խարաջատու դառնալը", "25bd3693"], "d": ["Մոլդովայի վոյևոդությունը համաձայնեց խարաջ վճարել. Վալախիայի և Տրանսիլվանիայի հետ միասին Դանուբից հյուսիս եռակի վասալական գոտին դարձավ կայսրության հյուսիսային բուֆերը։ Նույն ամսաթվին միացած այլ վայրեր՝ Յասսի։", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Դուբրովնիկի (Ռագուզա) խարաջը", "d127c78a"], "d": ["Վաճառական հանրապետություն Ռագուզան խարաջի դիմաց երաշխավորեց իր ինքնավարությունն ու առևտրային արտոնությունները. որպես Ադրիատիկ ծովում օսմանյան պատուհան՝ հարստացավ։ Հանրապետության հողը եղած Մլյետ կղզին (Mljet) ևս կիսում էր այս կարգավիճակը։", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Վալախիայի արշավանքը՝ Ցցահանող վոյևոդը", "fd4530bb"], "d": ["Խարաջ վճարել մերժած և դեսպաններին սպանած Վլադ Ցեպեշի դեմ կազմակերպված արշավանքով Վալախիան վերադարձվեց վասալության. գիշերային հարձակումն ու ցցահանման սարսափելի տեսարանները Եվրոպայում դարձան լեգենդ։ Նույն ամսաթվին միացած այլ վայրեր՝ Բուխարեստ։", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Բացվեց Ֆաթիհի համալիրը", "a150ea55"], "d": ["Իր ութ մեդրեսեներով (Սահն-ը Սեման) համալիրը Ստամբուլը իսլամական աշխարհի գիտական կենտրոնի վերածելու ծրագրի առաջին մեծ քայլն էր։", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ալի Քուշչուն Ստամբուլում", "8508229d"], "d": ["Սամարղանդի աստղադիտարանի վերջին մեծ ներկայացուցիչ Ալի Քուշչուն Ֆաթիհի հրավերով դարձավ Այա Սոֆիայի մեդրեսեի դասախոս (մյուդեռիս). Ստամբուլում հիմնեց մաթեմատիկա-աստղագիտության ավանդույթը։", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Ֆաթիհի կանունամեն", "b08944c9"], "d": ["Պետական կառույցը, արարողակարգը և պատիժները ամփոփող առաջին ընդգրկուն սովորութային կանունամեն. «աշխարհի կարգի համար» եղբայրասպանությունը թույլատրող իր հայտնի հոդվածով մինչև այսօր վիճարկվում է։", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Հատվեց առաջին օսմանյան ոսկեդրամը (սուլթանի)", "2fd5c0dd"], "d": ["Հատվեց վենետիկյան դուկատին համարժեք առաջին օսմանյան ոսկեդրամը. կայսրության ֆինանսները միացան միջազգային դրամական կարգին։", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Տեղափոխություն Թոփքափի պալատ", "b9cd6a5e"], "d": ["Նոր պալատի (Թոփքափի) ավարտով պետական կառավարման կենտրոնը տեղափոխվեց այստեղ. պալատը չորս դար մնաց որպես կայսրության ուղեղը։", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["Ֆլորենցիայի Հանրապետությունը վերածվեց դքսության — Ալեսանդրո դե Մեդիչի", "c08764e1"], "d": ["Պապ Կլեմենտ VII-ի ճնշմամբ Ֆլորենցիայի կառավարող հանձնաժողովը (Balìa) ընդունեց նոր սահմանադրություն. հնգադարյա հանրապետական կարգը վերացավ, Ալեսանդրո դե Մեդիչին հռչակվեց ժառանգական դուքս և մայիսի 1-ին փաստացի գահ բարձրացավ։ Այսպիսով Ֆլորենցիան անկախ քաղաք-հանրապետությունից վերածվեց Մեդիչի հարստության ժառանգական դքսության։", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Քանունի – Հյուրեմ Սուլթան ամուսնությունը", "abc05f26"], "d": ["Քանունիի՝ Հյուրեմի հետ պաշտոնական ամուսնությունը արմատապես փոխեց պալատական ավանդույթը. ծնվեց «Հասեքի սուլթան» հաստատությունը, և հարստության քաղաքականության մեջ բացվեց կանանց դարաշրջանի դուռը։", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Առաջին ընդգրկուն կապիտուլյացիաները Ֆրանսիային", "e2264e48"], "d": ["Որպես հաբսբուրգյան սեղմման դեմ ֆրանսիական դաշինքի մաս՝ Ժան դը լա Ֆորեի և Մաքբուլ Իբրահիմ փաշայի միջև ստորագրվեցին առևտրային արտոնություններ. այն ժամանակ դիվանագիտական միջոց եղած կապիտուլյացիաները դարերի ընթացքում վերածվելու էին ֆինանսական կախվածության դռան։", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Հնդկական օվկիանոսի արշավանքը՝ Դիուի պաշարումը", "fcd1217a"], "d": ["Սուեզից դուրս եկած նավատորմը անցավ Կարմիր ծովը և պաշարեց Գուջարաթի Դիուն. թեև ամրոցը չգրավվեց, օսմանյան ուժն առաջին անգամ հասավ Հնդկական օվկիանոս, և պորտուգալական մենաշնորհը խարխլվեց։", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Սեյդի Ալի Ռեիսի հնդկական ճանապարհորդությունը", "e5da3b2c"], "d": ["Բասրայի նավատորմը Եգիպտոս բերելու հանձնարարություն ստացած Սեյդի Ալի Ռեիսը փոթորիկների հետևանքով քշվեց Հնդկաստան. վերադարձի արկածները պատմող «Միրաթ ալ-մամալիք»-ը օսմանյան առաջին ուղեգրություններից է։", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Պիրի Ռեիսի մահապատիժը", "63026444"], "d": ["Հորմուզի արշավանքից նավատորմը Բասրայում թողած և վերադարձած մեծ ծովագնաց-քարտեզագիրը 84 տարեկանում մահապատժի ենթարկվեց. մեր գիտության պատմության ամենավիճելի որոշումներից մեկը։", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Բացվեց Սուլեյմանիե համալիրը", "1c6458b2"], "d": ["Ճարտարապետ Սինանի՝ «իմ ենթավարպետության գործը» անվանած համալիրը իր մեդրեսեներով, հիվանդանոցով և գրադարանով դարձավ դասական շրջանի ամենամեծ կրթաբարեգործական համալիրը։", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Մալթայի պաշարումը", "f57f6a85"], "d": ["Միջերկրական ծովի բանալի Մալթան չորս ամիս պաշարվեց. Թուրգութ Ռեիսը նահատակվեց, պաշարումը վերացվեց։ Սա դարձավ Քանունիի շրջանի ծովագնացության առաջին մեծ հետընթացը։", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Ավարտվեց Սելիմիե մզկիթը", "3b0484e1"], "d": ["Սինանի՝ «իմ վարպետության գործը» անվանած Սելիմիեն, որտեղ մեկ գմբեթը տիրում է տարածքին, համարվում է օսմանյան դասական ճարտարապետության գագաթնակետը (ՅՈՒՆԵՍԿՕ-ի համաշխարհային ժառանգություն)։", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Հիմնվեց Ստամբուլի աստղադիտարանը", "169bdf5d"], "d": ["Թաքիյուդդինի՝ ժամանակի ամենալավ սարքավորված դիտարաններից մեկը եղած աստղադիտարանը 1577 թվականի գիսավորից հետո ծագած վեճերի հետևանքով 1580 թվականին քանդվեց. ինստիտուցիոնալ աստղագիտությունը ուշացավ երեք դար։", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Չըլդըրի հաղթանակը — սկսվեց արևելյան պատերազմը", "13125a54"], "d": ["Չըլդըրում Սեֆյան բանակի պարտությամբ բացվեցին Կովկասի դարպասները. գրավվեց Թիֆլիսը, և Վրաստանն անցավ օսմանյան տիրապետության տակ։", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Ջահերի ճակատամարտը — Շիրվանը վերջնականապես օսմանյան է", "3bbc23bc"], "d": ["Քանի որ գիշերը ջահերի լույսով էլ շարունակվեց՝ այս անունով հիշվող ճակատամարտում Սեֆյանները վճռական պարտություն կրեցին. ամրապնդվեց օսմանյան տիրապետությունը Շիրվանում և Բաքվում։", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Մեծ արժեզրկումը — ակչեի ճգնաժամը", "9205c3d4"], "d": ["Երկարատև պատերազմների և ամերիկյան արծաթի ճնշման տակ ակչեի արծաթի պարունակությունը կրճատվեց կիսով չափ. գների հեղափոխությունը սնեց սիփահիական կարգի քայքայումը և ջալալիական խառնակությունը։", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Թավրիզի նվաճումը", "6506bdb9"], "d": ["Սերդար Օզդեմիրօղլու Օսման փաշան մտավ Թավրիզ. Սեֆյանների նախկին մայրաքաղաքն անցավ օսմանյան կառավարման տակ։ Օսման փաշան մի քանի շաբաթ անց մահացավ ռազմակայանում։", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Ֆերհադ փաշայի պայմանագիրը — արևելքում ամենաընդարձակ սահմանները", "c429972f"], "d": ["Շահ Աբբասի դեսպան Հայդար Միրզայի՝ Ստամբուլ գալուց (1590 թվականի հունվարի 18) հետո, այն պայմանով, որ նվաճված վայրերը մնային օսմանցիներին, կնքված և 12-ամյա պատերազմին վերջ դրած պայմանագրով Թավրիզը, Ղարաբաղը, Շիրվանը, Վրաստանը և Լուրիստանը մնացին օսմանցիներին. կայսրությունը արևելքում հասավ իր պատմության ամենաընդարձակ սահմաններին։", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Սկսվեց օսմանա-սեֆյան պատերազմը (1603-1612) — Շահ Աբբասի հակահարձակումը, Թավրիզի կորուստը", "abf27dd8"], "d": ["Իր բանակը վերակազմած Շահ Աբբասը, օգտվելով ջալալիական խառնակություններից, անցավ հարձակման. ընկավ Թավրիզը, կովկասյան ձեռքբերումները մի քանի տարվա ընթացքում ձեռքից գնացին։ Նույն արշավանքում և դրանից հետո ձեռքից դուրս եկած այլ բնակավայրեր՝ Նախիջևան, Խոյ, Մարանդ, Սալմաստ. Ղարաջադաղի (Ahar) և մուքրի բեյերը ևս անցան Սեֆյան կողմը։", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Ծնվեց Էվլիյա Չելեբին", "2b6051ff"], "d": ["Իր ավելի քան հիսուն տարվա ճանապարհորդությունները տասնհատորյա «Սեյահաթնամե»-ում ամփոփած Էվլիյա Չելեբին թողեց 17-րդ դարի օսմանյան աշխարհի եզակի համապատկերը։", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Նասուհ փաշայի պայմանագիրը", "bb69e388"], "d": ["1603 թվականից շարունակվող պատերազմին վերջ դրած պայմանագրով հրաժարվեցին 1590 թվականի ձեռքբերումներից և վերադարձան 1555 թվականի Ամասիայի սահմանին. արևելյան ճակատում հավասարակշռությունը վերականգնվեց։", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Բացվեց Սուլթան Ահմեդի մզկիթը", "e39dfd43"], "d": ["Իր վեց մինարեներով և կապույտ իզնիկյան ջնարակապատ սալիկներով «Կապույտ մզկիթը» դասական շրջանի վերջին մեծ սուլթանական համալիրն է։", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Սուլթան Իբրահիմի սպանությունը", "bc4eb452"], "d": ["Շռայլության և կառավարման ճգնաժամի պատրվակով զորաբանակի և ուլեմաների դաշինքը գահընկեց արեց Իբրահիմին. տասը օր անց ֆեթվայով նրան խեղդամահ արեցին։ Գահ բարձրացավ յոթամյա Մեհմեդ IV-ը. իշխանությունը փաստացի անցավ մեծ վալիդե Քյոսեմ սուլթանի ձեռքը։", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Քյաթիբ Չելեբիի մահը", "e167e89d"], "d": ["«Քեշֆ ազ-զունուն» մատենագիտությամբ և «Ջիհաննումա» աշխարհագրությամբ նա օսմանյան գիտության պատմության գագաթային անունն է. հայտնի է եվրոպական աղբյուրներից օգտվող առաջամարտիկ մոտեցմամբ։", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Էդիրնեի դեպքը — Մուստաֆա II-ի գահազրկումը", "0291c1cd"], "d": ["Փադիշահի՝ Էդիրնեում նստելը և Ֆեյզուլլահ էֆենդիի ազդեցության դեմ զայրույթը վերածվեցին բանակի և արհեստավորների մեծ ապստամբության. շեյխ ուլ-իսլամը ամբոխահարվեց, փադիշահը գահընկեց արվեց, պալատը վերադարձավ Ստամբուլ։", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Դեսպան Փարիզում՝ Յիրմիսեքիզ Մեհմեդ Չելեբի", "26312a3f"], "d": ["Ֆրանսիա ուղարկված մեծ դեսպանությունը դարձավ Արևմուտքը տեղում ուսումնասիրող առաջին համակարգված դիտարկումը. նրա «Սեֆարեթնամեն» ոգեշնչեց Կակաչների դարաշրջանի նորացումը։", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Հիմնվեց առաջին օսմանյան տպարանը", "4943f7e5"], "d": ["Թույլտվություն տրվեց թուրքերեն գիրք տպագրելու. առաջին գործը՝ Վանքուլուի բառարանը, տպագրվեց 1729 թվականին։ Տպարանը Կակաչների դարաշրջանի նորացման ամենամնայուն ժառանգությունն է։", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Կապիտուլյացիաները դարձվեցին մշտական", "d044a79e"], "d": ["Ֆրանսիային տրված արտոնությունները, դադարելով սահմանափակվել փադիշահի կյանքով, կապվեցին մշտական պայմանագրի. միակողմանի չեղարկման ենթակա չդարձած կապիտուլյացիոն ռեժիմը կարողացավ վերանալ միայն Լոզանում։", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Հիմնվեց կայսերական ծովային ինժեներական դպրոցը (Mühendishâne-i Bahrî-i Hümâyun)", "9bf3f439"], "d": ["Չեշմեի աղետից հետո ժամանակակից ծովային սպաներ պատրաստելու համար հիմնված ինժեներական դպրոցը արևմտյան ոճի տեխնիկական կրթության առաջին մշտական հաստատությունն է. ցամաքային ինժեներական դպրոցը հետևեց 1795 թվականին։", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Առաջին մշտական դեսպանությունը Լոնդոնում", "6b5630eb"], "d": ["Որպես Նիզամ-ը Ջեդիդ ծրագրի մաս՝ եվրոպական մայրաքաղաքներում բացվեցին մշտական դեսպանություններ. օսմանյան դիվանագիտությունն անցավ փոխադարձության սկզբունքին։", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Ալեմդար Մուստաֆա փաշայի մահը", "4426534e"], "d": ["1808 թվականի նոյեմբերի 15-ի գիշերը սկսված ենիչերիական ապստամբության ժամանակ Բարձր Դռանը պաշարված բարեփոխիչ մեծ վեզիրը, երբ սպասած օգնությունը չեկավ, հաջորդ օրը, պայթեցնելով զինապահեստը, զոհվեց հարյուրավոր հարձակվողների հետ. Սենեդ-ի Իթթիֆաքի կարգը և բարեփոխումների առաջին փորձը թաղվեցին նրա հետ։", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Առաջին պաշտոնական թերթը՝ «Թաքվիմ-ի Վեքայի»", "c637f623"], "d": ["Սկսեց հրատարակվել պետության պաշտոնական թերթը. սա ժամանակակից հասարակական կարծիքի և պաշտոնական հաղորդագրությունների ավանդույթի սկիզբն է։", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Բալթա Լիմանիի առևտրային պայմանագիրը", "e790b383"], "d": ["Անգլիային նույնիսկ ներքին առևտրում ճանաչվեց ամենաարտոնյալ դիրք, վերացվեց մենաշնորհի (yed-i vahit) կարգը. մինչ տեղական արտադրությունը մնում էր անպաշտպան, պայմանագիրը դարձավ օսմանյան շուկայի՝ ազատ առևտրին լիովին բացվելու փաստաթուղթը։", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Լիբանանի ամիրայության ավարտը — Բաշիր III Շիհաբի պաշտոնազրկումը", "f85ae454"], "d": ["Քրիստոնյա-դրուզական պայքարը և Շուֆի շրջանի ներքին հավասարակշռությունները չկարողանալով վերահսկել՝ էմիր Բաշիր II-ը (III) 1842 թվականի հունվարին պաշտոնազրկվեց. 1516 թվականից (Մաան-օղլուների և ապա Շիհաբ-օղլուների ձեռքով) շարունակվող տեղական ամիրայության կարգն ավարտվեց, և շրջանն անցավ ուղղակի օսմանյան կառավարման, ապա երկկայմակամության համակարգի։", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Դրամի ուղղումը (Tashîh-i sikke)՝ մեջիդիեի կարգը", "c77be809"], "d": ["Դրամական բարեփոխմամբ հավաքվեցին հարգը խաթարված դրամները. ստեղծվեց ոսկե լիրայի (մեջիդիե) վրա հիմնված կայուն երկմետաղյա կարգ։", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Բաալբեքում Հարֆուշ ընտանիքի տեղական իշխանության ավարտը", "8438f4ae"], "d": ["1521 թվականից (Ջանբիրդի Ղազալիի ապստամբությունից հետո) Բաալբեքում որպես փոքր տեղական հարստություն իշխող Հարֆուշ ընտանիքի ազդեցությունը Բարձր Դռան նոր վարչական կարգավորմամբ ավարտվեց. քաղաքը դարձավ Դամասկոսի վիլայեթին ենթակա սովորական կազայի կենտրոն։", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Հիմնվեց «Շիրքեթ-ի Խայրիյե» ընկերությունը", "462830e7"], "d": ["Բոսֆորում շոգենավեր շահագործելու համար հիմնված ընկերությունը համարվում է առաջին օսմանյան բաժնետիրական ընկերությունը. շոգենավերի նավամատույցներն իրենց կնիքը դրեցին քաղաքային կյանքի վրա։", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Առաջին արտաքին փոխառության պայմանագիրը", "9017c579"], "d": ["Ղրիմի պատերազմի ֆինանսավորման համար Լոնդոնի շուկայից վերցվեց առաջին արտաքին փոխառությունը. 21 տարում 15 փոխառությամբ հասած կետը եղավ 1875 թվականի մորատորիումը և Պետական պարտքի վարչությունը։", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Հեռագրային գիծը Ստամբուլում", "d320f39f"], "d": ["Ղրիմի պատերազմի կարիքներից ելնելով անցկացված առաջին հեռագրային գիծը գործարկվեց. մի քանի տասնամյակում կայսրությունն ունեցավ աշխարհի ամենաընդարձակ հեռագրային ցանցերից մեկը։", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Հողային կանունամեն", "6bae243a"], "d": ["Հողային իրավունքը արդիականացրած կանունամեն պետական հողի (միրի) փաստացի տիրապետումը կապեց տապուի (հողի վկայագրի) հետ. այսօրվա Մերձավոր Արևելքի սեփականության կարգի հիմնարար փաստաթղթերից մեկն է։", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Առաջին դասերը Դարուլֆունունում", "08f74066"], "d": ["Համալսարանական մակարդակի կրթություն տալու կոչված Դարուլֆունունը սկսեց աշխատել հանրային դասախոսություններով. ընդմիջումներով շարունակված հաստատությունը 1900 թվականին վերջնականապես բացվեց և դարձավ Ստամբուլի համալսարանի միջուկը։", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Վիլայեթների կանոնադրությունը", "ad20853b"], "d": ["Էյալեթային կարգի փոխարեն ֆրանսիական օրինակով ստեղծվեց վիլայեթային կազմակերպությունը. Միդհաթ փաշայի Դանուբի վիլայեթի փորձը որպես օրինակ վերցնելով տարածվեց ողջ երկրով։", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Աբդուլազիզի եվրոպական ճանապարհորդությունը", "9ff0fa1e"], "d": ["Օսմանյան փադիշահի խաղաղ նպատակով եվրոպական առաջին ճանապարհորդությունը. Փարիզի ցուցահանդեսը և Լոնդոն այցելությունը ծառայեցին որպես և՛ դիվանագիտության, և՛ արդիականացման ցուցափեղկ։", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Բացվեց Ղալաթասարայի կայսերական լիցեյը", "f9688524"], "d": ["Ֆրանսերենով կրթություն տվող լիցեյը, իր ուսանողական կազմով, որ խտրություն չէր դնում կրոնի և ազգի միջև, դարձավ Թանզիմաթի կրթական հավասարության իդեալի խորհրդանիշը։", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Մեջելլեի առաջին գիրքն ուժի մեջ է", "6475461c"], "d": ["Իսլամական իրավունքի պարտավորությունների և գույքային իրավունքի ոլորտը ժամանակակից օրենսդրական տեխնիկայով ամփոփող Մեջելլեն համարվում է առաջին իսլամական քաղաքացիական օրենսգիրքը. Ջևդեթ փաշայի նախագահությամբ հանձնաժողովը 16 գիրքն ավարտեց 1876 թվականին։", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Աբդուլազիզի գահազրկումը", "eb7397ea"], "d": ["Սահմանադրական կարգի կողմնակից պետական գործիչները և զինվորական ղեկավարությունը անձայն հեղաշրջմամբ գահազրկեցին Աբդուլազիզին. հինգ օր անց նրա կասկածելի մահը և դրան հաջորդած Չըրաղանի դեպքերը ծնեցին տարիներ տևելիք հաշվեհարդարներ։", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Չըրաղանի հարձակումը (Ալի Սուավիի դեպքը)", "d2a9ac87"], "d": ["Լրագրող Ալի Սուավին, Մուրադ V-ին կրկին գահ բարձրացնելու համար, հարձակվեց Չըրաղան պալատի վրա. հարձակումը ճնշվեց արյունալի կերպով, Աբդուլ Համիդի վարչակարգը մշտապես խստացրեց անվտանգության օղակը։", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Հիմնվեց Ռեժի վարչությունը (ծխախոտի մենաշնորհ)", "bad9b030"], "d": ["Ծխախոտի եկամուտները փոխանցվեցին Պետական պարտքի վարչության կազմում գործող օտար կապիտալով Ռեժի ընկերությանը. գյուղացու և պահակների միջև «Ռեժիի մաքսանենգության» ընդհարումները տևեցին տասնամյակներ։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Զեյլա։", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Կայզեր Վիլհելմ II-ի այցը Ստամբուլ և Երուսաղեմ", "2988cd06"], "d": ["Գերմանական կայսեր երկրորդ այցը ամրապնդեց օսմանա-գերմանական մերձեցումը. բացվեց Բաղդադի երկաթուղու կոնցեսիայի ճանապարհը, Դամասկոսում հնչեց «երեք հարյուր միլիոն մուսուլմանի բարեկամի» ճառը։", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Հիջազի երկաթուղին Մեդինայում", "95009b9c"], "d": ["Միայն մուսուլմանների նվիրատվություններով և տեղական ինժեներությամբ կառուցված 1464 կմ երկարությամբ գիծը հասավ Մեդինա. ուխտագնացության ճանապարհորդությունը շաբաթներից կրճատվեց օրերի։ Սա Աբդուլ Համիդ II-ի շրջանի ամենամեծ ենթակառուցվածքային գործն է։", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Մարտի 31-ի դեպքը", "1d7c2bb2"], "d": ["Սահմանադրական կարգի դեմ մեծ ապստամբությունը գրավեց Ստամբուլը. Սալոնիկից եկած Գործողությունների բանակը ճնշեց ապստամբությունը, և Աբդուլ Համիդ II-ը գահընկեց արվեց։", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Սկսվեց Էդիրնեի պաշարումը", "234d9b28"], "d": ["Շյուքրյու փաշայի հինգ ամիս տևած պաշտպանությունը դարձավ Բալկանյան աղետի մեջ դիմադրության էպոս. քաղաքն ընկավ սովից, հետ վերցվեց 1913 թվականի հուլիսին։", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Բարձր Դռան հարձակումը", "b304d02d"], "d": ["Էդիրնեն հանձնելու նախապատրաստվող կառավարությունը տապալվեց իթթիհադականների զինված հարձակմամբ. սպանվեց ռազմական նախարար Նազըմ փաշան։ Սկսվեց «Միություն և առաջադիմություն» կոմիտեի լիակատար իշխանության շրջանը։", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Լեռնային Լիբանանի մութասարիֆության վերացումը", "b5639051"], "d": ["1861 թվականի Règlement organique-ով հիմնված և 1864 թվականին վերանորոգված միջազգային արձանագրության վրա հիմնված ինքնավար մութասարիֆության կարգը Առաջին համաշխարհային պատերազմի ժամանակ Օսմանյան պետության կողմից միակողմանիորեն չեղարկվեց. ներքին գործերի նախարարությունը սկսեց շրջան ուղղակիորեն նշանակել մուսուլման մութասարիֆներ։ Այսպիսով փակվեց 1861-1915 թվականների ինքնավարության շրջանը, որի ընթացքում պաշտոնավարեցին ութ մութասարիֆ։", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Երկրի բաժանումը շահզադեների միջև", "82f26bfb"], "d": ["Անկարայի ջախջախումից հետո Սուլեյման Չելեբին անցավ Ռումելի և Էդիրնեում հռչակեց սուլթանություն. Իսա Չելեբին իր ձեռքում պահեց Բուրսան, իսկ Չելեբի Մեհմեդը՝ Ամասիա-Թոքաթ-Սեբաստիա շրջանը։ Քարտեզում այս երեք բաժինները ցույց են տրվում առանձին գույներով։", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Գելիբոլուի պայմանագիրը՝ Սև ծովի ափը մինչև Մեսեմբրիա թողնվեց Բյուզանդիային", "a4164eca"], "d": ["Անկարայի ջախջախումից հետո Ռումելիում դիմանալ ցանկացող էմիր Սուլեյմանը Գելիբոլուում պայմանագիր ստորագրեց բյուզանդական կայսր Մանուելի հետ։ Նա Բյուզանդիային թողեց Քարթալը, Պենդիկը և Գեբզեն ու որոշ կղզիներ, Ռումելիում՝ Սալոնիկը և Թեսալիան, Սև ծովում՝ մինչև Մեսեմբրիա ձգվող ափամերձ շերտը. վերացվեց նաև այն հարկը, որ Բյուզանդիան վճարում էր օսմանցիներին։ Ստրանջայի ափի Ահտոպոլը, Իղնեադան և Ռեզվեն այսպիսով քսանմեկ տարի մնացին բյուզանդական կառավարման տակ. Մուրադ II-ը 1424 թվականի հաշտությամբ հետ վերցրեց այս վայրերի մեծ մասը։", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Յըլդըրըմ Բայազիդի մահը գերության մեջ", "7e968d83"], "d": ["Թեմուրի գերության մեջ գտնվող փադիշահը մահացավ Աքշեհիրում. նրա դին բերվեց Բուրսա և թաղվեց։ Նրա մահը շահզադեների միջև գահակալական պայքարը դարձրեց անշրջելի։", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Գելիբոլուի պայմանագիրը — զիջումներ Բյուզանդիային", "dfacbd00"], "d": ["Ռումելիում իր դիրքն ապահովել ցանկացող Սուլեյման Չելեբին, համաձայնության գալով Բյուզանդիայի և լատինական պետությունների հետ, վերադարձրեց Սալոնիկը, Մարմարայի ափերը և որոշ կղզիներ. նա նույնիսկ համաձայնեց խարաջ վճարել։", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Ուլուբաթի ընդհարումը — Իսա Չելեբիի պարտությունը", "500c5d24"], "d": ["Բուրսան ձեռքում պահող Իսա Չելեբին Ուլուբաթում պարտվեց եղբորը՝ Մեհմեդին. վերականգնվելու մի քանի փորձն էլ անարդյունք մնաց։", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Իսա Չելեբիի վերանալը ասպարեզից", "0effa11e"], "d": ["Սուլեյման Չելեբիի աջակցությամբ մի քանի անգամ Անատոլիա վերադարձած Իսա Չելեբին իր վերջին պարտությունից հետո անհետացավ. նրա բաժինն անցավ Չելեբի Մեհմեդին, և քարտեզում Մեհմեդի տարածքն ընդարձակվեց դեպի արևմուտք։", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Մուսա Չելեբին անցավ Վալախիա", "8441267a"], "d": ["Սուլեյման Չելեբիի դեմ Բուրսան և Անկարան կորցրած ու Թոքաթ-Ամասիա նահանջած Չելեբի Մեհմեդը եղբորը՝ Մուսային, խրախուսեց գնալ Ռումելի։ Մուսան, ընդունելով Վալախիայի վոյևոդ Միրչայի հրավերը, ծովով հասավ Վալախիա. այստեղից նա ձեռնամուխ էր լինելու պայքարի, որը Սուլեյմանին թողնելու էր երկու ճակատի միջև։", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Չելեբի Մեհմեդը կրկին գրավեց Բուրսան և Անկարան — անատոլիական բաժինը դուրս եկավ Սուլեյման Չելեբիի ձեռքից", "bfb69f12"], "d": ["Մուսա Չելեբիի՝ Ռումելիում հաջողությունների (Յամբոլ, 1410 թվականի փետրվարի 13) առիթով Անատոլիայում գտնվող էմիր Սուլեյման Չելեբին անցավ Ռումելի։ Անատոլիայից Սուլեյմանի հեռանալուց հետո Մեհմեդ Չելեբին կրկին գրավեց Բուրսայի շրջանը՝ ներառյալ Անկարան, և որպես գահ բարձրանալու նշան հատեց 813 թվականով դրամ։ Քարտեզում Մարմարայի անատոլիական ափը էմիր Սուլեյմանի բաժնից անցնում է Չելեբի Մեհմեդի գույնին։", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Կոսմիդիոնի ճակատամարտը", "0efc2caa"], "d": ["Բյուզանդական աջակցությամբ Ստամբուլի պարիսպների առջև մղված ճակատամարտում Սուլեյման Չելեբին հաղթեց եղբորը՝ Մուսային. սակայն Ռումելիում նրա աջակցությունն արդեն սկսել էր արագորեն հալվել։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Ալասոնյա (Elassona), Այդոս (Aytos), Բոլայիր (քարտեզում Ռումելիում Մուսայից Սուլեյմանին անցած վայրերը)։", "0498cbda"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Մուսա Չելեբիի Ստամբուլի պաշարումը", "4932f586"], "d": ["Սուլեյմանին աջակցած Բյուզանդիային պատժել ցանկացող Մուսա Չելեբին պաշարեց Ստամբուլը. այս պաշարումը Բյուզանդիային մղեց դաշինքի Չելեբի Մեհմեդի հետ։", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Էմիր Սուլեյմանի մահը — Մուսան՝ Ռումելիի տեր", "325c1549"], "d": ["Էդիրնեից փախչելիս բռնված Սուլեյման Չելեբին սպանվեց. ամբողջ Ռումելին անցավ Մուսա Չելեբիի ձեռքը։ Քարտեզում Ռումելին կապույտ գույնից դառնում է մանուշակագույն։", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Չամուրլուի ճակատամարտը — միասնության վերականգնումը", "0b23173e"], "d": ["Բյուզանդիայի, Սերբական դեսպոտության և Ռումելիի բեյերի աջակցությունն ստացած Չելեբի Մեհմեդը Չամուրլուում վճռական պարտության մատնեց եղբորը՝ Մուսային. Մուսան սպանվեց փախչելիս։ Մուսայի ձեռքում եղած Ռումելին Էդիրնեի հետ անցավ Մեհմեդին, և Մեհմեդ Չելեբին Էդիրնեում իրեն հռչակեց Օսմանյան պետության միակ տիրակալ։ Տասնմեկամյա միջգահակալության շրջանն ավարտվեց, և քարտեզի շահզադեական բաժինները միավորվեցին մեկ մարմնի մեջ։", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Վիեննայի արշավանքի որոշումը — Վաշվարի հաշտությունը չվերանորոգվեց, թիրախը Դյորից (Յանըքքալե) տեղափոխվեց Վիեննա", "1bf278f2"], "d": ["Լեոպոլդ I կայսրը ցանկանում էր վերանորոգել Վաշվարի պայմանագիրը, որի ժամկետը դեռ չէր լրացել, և Մեհմեդ IV-ը ևս խաղաղության կողմնակից էր թվում։ Իսկ մեծ վեզիր Մերզիֆոնցի Կարա Մուստաֆա փաշան, պատճառաբանելով Միջին Հունգարիայի թագավոր հռչակել տված Իմրե Թյոքյոլիի գանգատները, թույլ չտվեց վերանորոգել հաշտությունը. գլխավորապես Վանի Մեհմեդ էֆենդիին և քարոզիչներին շարժման մեջ դնելով՝ համոզեց փադիշահին պատերազմել։ Անցկացված խորհրդակցությունում որոշվեց, որ փադիշահը մնա Բելգրադում, իսկ գլխավոր սերդարը առաջանա Դյորը գրավելու. սակայն Սեկեշֆեհերվարի (İstolni Belgrad) խորհրդակցությունում, չնայած Ղրիմի խան Մուրադ Գիրեյի և Բուդայի կուսակալ Ուզուն Իբրահիմ փաշայի առարկություններին, թիրախը փոխվեց Վիեննայի պաշարման։", "7a572168"]}
});
